window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-gineco-gin-5"]={"block":"medcurso:medcurso-gineco-gin-5","label":"Medcurso · GIN 5","count":426,"questions":[{"id":"medcurso-gineco-gin-5-343773","number":"343773","sourceNumber":"343773","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Sobre as lesões pré-neoplasicas e neoplásicas do colo uterino, é incorreto afirmar:","options":{"A":"A infecção pelo vírus HPV é o principal fator de risco para o desenvolvimento de atipias na zona\nde transformação no colo uterino.","B":"O HPV pode acometer pessoas de qualquer idade, mas é mais frequente na faixa etária\ncompreendida entre 20-40 anos - período de maior atividade sexual.","C":"Existem mais de 100 subtipos de HPV, e esses são capazes de acelerar a velocidade das\nmitoses celulares, o que aumenta a chance de desenvolver atipias citológicas.","D":"A infecção por HPV sempre cursa com persistência do vírus associado a citologia anormal."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-281129","number":"281129","sourceNumber":"281129","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer do endométrio tornou-se o câncer ginecológico mais comum em países\nindustrializados, notando-se aumento de sua frequência. Em relação as recomendações gerais\npara prevenção, rastreamento e diagnóstico desse tipo de câncer, é CORRETO afirmar que:","options":{"A":"Pacientes em uso de SERMS (Tamoxifeno), que tem ação antagonista no endométrio, não\nnecessitam de investigação.","B":"O uso de anticoncepção hormonal aumenta o risco para o câncer do endométrio.","C":"A espessura endometrial para pacientes na pós menopausa sem terapia hormonal é\nconsiderado limite de corte 8mm de espessura.","D":"A citologia vaginal (Papanicolau) com células endometriais presentes em mulheres no climetério,\nnão indica necessidade de investigação do\nendométrio.","E":"A associação do estrogênio e progesterona usados durante a terapia hormonal no climetério é\ncapaz de bloquear os efeitos proliferativos sobre o endométrio."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-281139","number":"281139","sourceNumber":"281139","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 43 anos de idade apresenta carcinoma espinocelular do colo do útero,\nestadio FIGO Ib. Foi realizada cirurgia de Wertheim-Meigs, com preservação dos ovários. O\nresultado anatomopatológico da peça mostrou margens vaginais livres, linfonodos negativos e\ninfiltração dos paramétrios laterais por neoplasia, porém com margens cirúrgicas livres de\nneoplasia. A conduta subsequente deve ser:","options":{"A":"Ooforectomia bilateral.","B":"Quimioterapia adjuvante.","C":"Radioterapia pélvica.","D":"Exenteração pélvica anterior.","E":"Seguimento clínico mensal com citologia e colposcopia."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-283339","number":"283339","sourceNumber":"283339","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente com 60 anos de idade apresenta prurido crônico vulvar, e seu exame físico\napresenta mancha branca e espessa envolvendo toda a vulva. A conduta é:","options":{"A":"Citologia esfoliativa.","B":"Biópsia.","C":"Corticoide.","D":"Testosterona tópica."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-283363","number":"283363","sourceNumber":"283363","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com relação às estratégias de prevenção e controle do câncer do colo do útero e da\nmama, assinale a alternativa correta:","options":{"A":"Foram elaboradas e implantadas diversas ações, dentre elas o Programa Viva Mulher -\nPrograma Nacional de Controle do Câncer do Colo do Útero e Mama.","B":"Todas as mulheres a partir da primeira relação sexual deverão realizar o exame de PCCU-\nExame Preventivo do Câncer de Colo Uterino, anualmente.","C":"O exame citopatológico deve ser realizado em mulheres de 18 a 60 anos de idade.","D":"Mulheres grávidas não devem realizar o rastreamento do câncer de colo de útero."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-251890","number":"251890","sourceNumber":"251890","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considerando que a ecografia endovaginal após a menopausa tornou-se importante\ninstrumento para a detecção do carcinoma do\nendométrio e do ovário, julgue os seguintes itens. I.\nHavendo espessura endometrial de 20 mm, o exame é considerado normal para mulheres com até\n60 anos de idade. II. Havendo espessura endometrial de menos de 4 mm, o quadro é sugestivo de\nendométrio senil normal. III. O endométrio de espessura aumentada, com dimensões irregulares e\nsangramentos, está muito associado a câncer. Assinale a opção correta:","options":{"A":"Apenas o item I está certo.","B":"Apenas o item II está certo.","C":"Apenas os itens I e II estão certos.","D":"Apenas os itens II e III estão certos."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-247200","number":"247200","sourceNumber":"247200","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 54 anos de idade, obesa, hipertensa e diabética, realizou citologia oncológica\ncervico-vaginal cujo laudo foi de atipia em células glandulares (ACG). A propedêutica considerada\nindispensável é","options":{"A":"Ultrassonografia transvaginal para avaliação do eco endometrial, apenas se colposcopia normal.","B":"Ultrassonografia transvaginal para avaliação do eco endometrial, mesmo se colposcopia\nalterada.","C":"Colposcopia com biópsia dirigida, uma vez que a ACG é uma alteração histológica exclusiva do\ncolo uterino.","D":"Colposcopia com biópsia dirigida; se normal, histerectomia total profilática com congelação do\nendométrio.","E":"Conização cervical clássica, independente da colposcopia, pois ACG é uma lesão endocervical\nde alto grau."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-247202","number":"247202","sourceNumber":"247202","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher de 78 anos de idade apresenta lesão numular de 1,5 cm em grande lábio\ndireito. Submeteu-se à biópsia incisional ambulatorial que revelou carcinoma espinocelular com\ninvasão estromal de 0,5 mm. A conduta recomendada é","options":{"A":"Radioterapia locoregional exclusiva, uma vez que o risco cirúrgico é elevado.","B":"Vulvectomia simples direita e remoção do linfonodo sentinela inguinal isilateral.","C":"Vulvectomia radical e remoção do linfonodo sentinela inguinal bilateral.","D":"Ressecção ampliada da lesão com margem de 2cm, dispensando linfadenectomia.","E":"Cauterização química ou elétrica da lesão e excisão cirúrgica se houver recidiva."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-247204","number":"247204","sourceNumber":"247204","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 46 anos de idade com história de hipermenorragia. A biópsia por\nhisteroscopia mostrou hiperplasia endometrial\ncomplexa com atipia. Apresenta dosagem de FSH =\n\n5.0. A conduta recomendada é:","options":{"A":"Terapia hormonal oral contínua com progesterona até a menopausa definitiva.","B":"Ablação endometrial por histeroscopia, uma vez que a paciente se encontra em idade próxima à\nmenopausa.","C":"Curetagem fracionada de prova para obter uma maior representação tecidual do endométrio.","D":"Introdução de dispositivo intrauterino com progesterona até menopausa definitiva.","E":"Histerectomia total abdominal com preservação de ovários se a congelação endometrial for\nnegativa para neoplasia."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-247230","number":"247230","sourceNumber":"247230","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 32 anos de idade, casada, 3g 3p, procura posto de saúde para exame\nginecológico de rotina. Passar em consulta\nginecológica anual e coletar o exame citológico\ncervicovaginal, sempre com resultados normais. De acordo com as normas do Ministério da Saúde,\nvocê a orienta que, em relação à coleta do Papanicolau, ela deve repetir o exame","options":{"A":"De dois em dois anos, por não pertencer à grupo de risco câncer de colo de útero.","B":"Anualmente como vem fazendo.","C":"Somente após três anos, já que os dois últimos exames são normais.","D":"Todos os anos enquanto mantiver vida sexual ativa.","E":"A cada seis meses somente quando estiver acima de 40 anos de idade."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-217642","number":"217642","sourceNumber":"217642","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Sobre a anatomia da vulva, pode-se afirmar que:","options":{"A":"As glândulas de Skene se localizam na superfície interna dos grandes lábios.","B":"As glândulas de Bartholin originam-se do ducto mesonéfricos.","C":"Os lábios maiores são homólogos à próstata.","D":"Os pequenos retalhos do hímen, restantes após o parto são chamados de carúnculas."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-183134","number":"183134","sourceNumber":"183134","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 65 anos com carcinoma de vulva invasivo com 3 cm de diâmetro sem\nevidência de disseminação linfática. Qual deve ser o tratamento inicial de escolha?","options":{"A":"Quimioterapia.","B":"Radioterapia.","C":"Vulvectomia simples.","D":"Vulvectomia radical sem linfadenectomia inguinal.","E":"Vulvectomia radical parcial com linfadenectomia inguinal bilateral."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-182710","number":"182710","sourceNumber":"182710","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considerando que a ecografia endovaginal após a menopausa tornou-se importante\ninstrumento para a detecção do carcinoma do\nendométrio e do ovário, julgue os seguintes itens. I.\nHavendo espessura endometrial de 20 mm, o exame é considerado normal para mulheres com até\n60 anos de idade. II. Havendo espessura endometrial de menos de 4 mm, o quadro é sugestivo de\nendométrio senil normal. III. O endométrio de espessura aumentada, com dimensões irregulares e\nsangramentos, está muito associado a câncer. Está(ão) CORRETO(S) apenas o(s) item(ns):","options":{"A":"I.","B":"II.","C":"I e II.","D":"II e III."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-182713","number":"182713","sourceNumber":"182713","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 54 anos, menopausa há 17 meses, tem queixa de corrimento vaginal\nserossanguinolento há um mês. O exame ginecológico revela atrofia genital, com petéquias na\nvagina. O laudo citopatológico de esfregaço cervical é: \"Inflamatório acentuado com atrofia;\npresença de células endometriais\". Está indicado:","options":{"A":"Solicitar cultura de secreção vaginal para tratar processo inflamatório.","B":"Reavaliar atrofia genital e processo inflamatório após tratamento.","C":"Investigar cavidade uterina.","D":"Avaliar menopausa com dosagens hormonais."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-159052","number":"159052","sourceNumber":"159052","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Dentre os abaixo, qual NÃO se constitui em fator de risco para neoplasia intraepitelial\nvaginal (NIVA)?","options":{"A":"Tratamento prévio para neoplasia intraepitelial.","B":"Radioterapia prévia para câncer de colo uterino.","C":"Tabagismo.","D":"Adenose vaginal."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-108811","number":"108811","sourceNumber":"108811","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher de 36 anos de idade veio para um exame ginecológico de rotina. O exame\nespecular mostrou uma lesão aceto-branca e iodo negativo ao lábio anterior do colo uterino. Foi\ncolhida citologia oncótica cujo laudo demonstra \"NIC II\". Qual seria a melhor conduta para o caso?","options":{"A":"Repetir a colpocitologia com 6 meses;","B":"Utilizar Imiquimode tópico;","C":"Realizar a eletrocauterização;","D":"Realizar uma conização."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-50072","number":"50072","sourceNumber":"50072","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Durante um exame de rotina, uma paciente multípara, assintomática, apresenta um\ncisto elevado de 1 cm no colo uterino. A área\né biopsiada e elimina muco claro. O exame\nhistológico da peça mostra uma fissura de células de epitélio colunar achatado ou do tipo cuboide.\nEsse quadro clínico seria mais compatível com:","options":{"A":"Cervicite;","B":"Infecção por varicela;","C":"Cisto de Naboth;","D":"Neoplasia intraepitelial cervical;"},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-50124","number":"50124","sourceNumber":"50124","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considerando uma paciente de 25 anos, a mais provável para o desenvolvimento de\nadenocarcinoma endometrial é uma:","options":{"A":"Profissional do sexo utilizando anticoncepcional;","B":"Mulher casada com Síndrome dos Ovários Policísticos (SOP);","C":"Garçonete com feminização testicular;","D":"Médica com um Dispositivo Intrauterino (DIU)."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-50126","number":"50126","sourceNumber":"50126","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher de 40 anos vem para um exame de rotina. Sua menstruação tem sido\nregular e ela não tem queixas. Os achados,\nincluindo aqueles de exame pélvico, são normais. Dez\ndias depois, seu esfregaço de Papanicolau retorna com o seguinte relatório: \"lesão escamosa\nintraepitelial de alto grau\". Das seguintes opções, a MELHOR ação a ser realizada seria:","options":{"A":"Histerectomia ampliada imediata;","B":"Repetição do esfregaço de Papanicolau em intervalos de 3 meses;","C":"Dilatação e curetagem fracionada;","D":"Colposcopia com biópsia."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-29431","number":"29431","sourceNumber":"29431","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Você recebe um laudo de colpocitologia oncótica com metaplasia escamosa, o que\nfará?","options":{"A":"encaminhar ao Centro de Controle de Câncer (CECON).","B":"solicita colposcopia para esclarecer diagnóstico.","C":"solicita biópsia de colo guiada por colposcopia.","D":"repete colpocitologia oncótica em 6 meses.","E":"orienta paciente sobre o resultado para rotina anual."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-29401","number":"29401","sourceNumber":"29401","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Dentre os itens descritos abaixo, que fator que tem maior magnitude de risco para o\ndesenvolvimento de Câncer de Colo de Útero e que coloca essa patologia como uma doença\nSexualmente Transmissível?","options":{"A":"Múltiplos parceiros sexuais.","B":"Início precoce da vida sexual.","C":"Infecção pelo Papilomavirus Humano.","D":"Multiparidade.","E":"Uso de contraceptivo por longo tempo."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-341060","number":"341060","sourceNumber":"341060","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher, 26 anos de idade, primípara, vem ao consultório do ginecologista para exames\nde rotina, desejando a troca de método\ncontraceptivo. Exames laboratoriais gerais, atuais, sem\nalterações. Ultrassom de Abdome do último mês evidenciou adenoma hepático de 2,7cm. Última\ncolpocitologia oncótica, realizada há 6 meses, apresentou atipia de células escamosas de\nsignificado indeterminado (ASC-US). Ultrassonografia transvaginal recente sem alterações. Frente\nao caso descrito, indique a conduta a ser adotada diante do resultado da citologia oncótica.","options":{"A":"Realizar colposcopia.","B":"Realizar nova colpocitologia oncótica daqui a 6 meses.","C":"Realizar nova colpocitologia oncótica nessa consulta.","D":"Fazer biópsia do colo uterino."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-313460","number":"313460","sourceNumber":"313460","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 60 anos com quadro de prurido vulvar, comparece ao ginecologista, que\nrealiza biópsia. O resultado do anatomopatológico evidencia moléstia de Paget. Trata-se de lesão:","options":{"A":"Inflamatória.","B":"Infecciosa crônica.","C":"Neoplásica.","D":"Auto-imune."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-315196","number":"315196","sourceNumber":"315196","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A colpocitologia oncótica visa a detecção precoce de lesões precursoras do câncer de\ncolo uterino. Sobre este tema assinale a alternativa INCORRETA.","options":{"A":"A infecção persistente pelo HPV é fator necessário para evolução do câncer de colo uterino,\nsendo alguns subtipos, como 16 e 18, mais oncogênicos.","B":"A presença de metaplasia escamosa imatura não indica a necessidade de prosseguir\ninvestigação com colposcopia, uma vez que não se trata de lesão precursora do câncer.","C":"A zona de transformação deve ser representada na amostra, uma vez que é nela onde se\niniciam as neoplasias celulares, por se tratar de um local de encontro entre ectocérvice e\nendocérvice.","D":"Segundo as Diretrizes para rastreio do câncer de colo do útero, há diferenças quanto ao rastreio\nem pacientes portadoras do vírus HIV.","E":"Pacientes com lesão escamosa intraepitelial de baixo grau (NIC I) devem ser submetidas à\ncirurgia de alta frequência (conização)."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-313464","number":"313464","sourceNumber":"313464","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Quando se submete uma paciente ao teste de Schiller, a tonalidade marrom que\nacontece nas áreas consideradas normais do colo, é devido à interação do iodo com o:","options":{"A":"meio ácido.","B":"meio alcalino.","C":"glicogênio livre.","D":"lactobacilo."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-278653","number":"278653","sourceNumber":"278653","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"No exame de colposcopia, a utilização do filtro verde serve principalmente para\nvisualizar","options":{"A":"a zona de transformação.","B":"vasos atípicos.","C":"orifícios glandulares.","D":"lesões aceto-brancas inespecíficas."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-278654","number":"278654","sourceNumber":"278654","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Um carcinoma de endométrio que apresenta metástases à distância, incluindo\nlinfonodos inguinais, corresponde ao estadiamento","options":{"A":"III B.","B":"III C.","C":"IV A.","D":"IV B."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-278659","number":"278659","sourceNumber":"278659","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Não é ramo da Artéria Ilíaca Interna,","options":{"A":"artéria epigástrica inferior.","B":"artéria uterina.","C":"artéria obturatória.","D":"artéria vesical inferior."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-231368","number":"231368","sourceNumber":"231368","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 33 anos tem um esfregaço de Papanicolaou mostrando neoplasia\nintraepitelial escamosa de alto grau. Qual dos seguintes é o melhor próximo passo?","options":{"A":"Repetir o esfregaço de Papanicolaou em 3 meses.","B":"Conização da cervice.","C":"Biópsia dirigida pela colposcopia.","D":"Histerectomia radical.","E":"Tomografia computadorizada do abdômen e da pelve."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-249405","number":"249405","sourceNumber":"249405","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A sinéquia vulvar ou aglutinação labial é uma condição benigna, comum nas meninas,\nmas que costuma causar preocupação nos pais.\nDas alternativas abaixo, assinale aquela que não\nrepresenta uma possível causa de sinéquia.","options":{"A":"Traumatismos repetitivos.","B":"Higiene inadequada.","C":"Hímen imperfurado.","D":"Infecções locais."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-201761","number":"201761","sourceNumber":"201761","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Cada um dos seguintes é um fator de risco para câncer endometrial, exceto:","options":{"A":"Nuliparidade.","B":"Obesidade.","C":"Diabetes mellitus.","D":"Uso de contraceptivo oral.","E":"Hipertensão."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-215234","number":"215234","sourceNumber":"215234","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O pior achado colposcópico dos listados abaixo é:","options":{"A":"Mosaico.","B":"Vasos atípicos.","C":"Pontilhado.","D":"Orifícios glandulares espessados."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-212229","number":"212229","sourceNumber":"212229","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer de colo uterino acomete mulheres jovens, em idade economicamente ativa,\ncom maior concentração entre 45 e 50 anos. O fator etiológico é a infecção persistente pelo\npapilomavírus humano (HPV). Sobre o estadiamento e o tratamento dessa patologia, dadas as\nafirmativas: I. No estádio IIa, o tumor é de qualquer magnitude, porém com infiltração do terço\nsuperior da vagina. Na maioria dos casos, são detectados apenas no pós-operatório de\nhisterectomias radicais por meio da análise histológica da peça, que apresenta infiltração\nmicroscópica. II. Pode-se optar por conização com margens livres em pacientes com desejo\nreprodutivo que foram diagnosticadas no estágio Ia1. III. Para o estágio IVa, onde se identifica\nmetástases a distância, como pulmonar e hepática, o tratamento é basicamente paliativo.\nverifica-se que está(ão) correta(s) apenas","options":{"A":"II.","B":"III.","C":"I e II.","D":"I e III.","E":"II e III."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-187781","number":"187781","sourceNumber":"187781","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 32 anos de idade, apresenta resultado de citologia oncótica revelando\ndisplasia cervical grave (Lesão intra-epitelial escamosa de alto grau). Qual a próxima etapa na\nconduta para essa paciente?","options":{"A":"Cauterização do colo uterino","B":"Colposcopia com biópsia direcionada","C":"Conização do colo uterino","D":"Repetir a Citologia em 6 meses"},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-187786","number":"187786","sourceNumber":"187786","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 61 anos de idade, obesa, em amenorréia há 10 anos, com queixa de\nsangramento vaginal há 3 meses. Nega uso de tratamento hormonal. História clínica e exames\nclínicos e ginecológico sem outras anormalidades. Citologia oncótica cervical sem alterações.\nUltrassonografia Transvaginal mostrando eco endometrial com espessura de 14mm. Qual é a\nconduta MAIS APROPRIADA para essa paciente?","options":{"A":"Colposcopia com biópsia do colo uterino","B":"Dosagem de FSH, LH e estradiol","C":"Histeroscopia com biópsia de endométrio","D":"Iniciar reposição hormonal com estrogênio"},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-180115","number":"180115","sourceNumber":"180115","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A propedêutica subsequente ao achado de lesão de alto grau na colpocitologia oncótica\né:","options":{"A":"Repetir a colpocitologia oncótica imediatamente","B":"Repetir a colpocitologia oncótica após três (03)\nmeses","C":"Realizar colposcopia e biópsia dirigida","D":"Realizar conização.","E":"Nenhuma das respostas acima"},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-181407","number":"181407","sourceNumber":"181407","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 45 anos, G3P3A0, realizou colposcopia e biópsia do colo do útero com\nexame histopatológico compatível com carcinoma. Qual\na conduta inicial mais adequada?","options":{"A":"Cauterização química com ácido tricloracético a 85% ou eletrocauterização.","B":"Histerectomia total + anexectomia bilateral.","C":"Realizar nova colposcopia em 6 meses.","D":"Histerectomia total.","E":"Conização."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-183090","number":"183090","sourceNumber":"183090","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Das seguintes lesões vulvares, qual é considerada como Neoplasia?","options":{"A":"Lipoma.","B":"Hidroadenoma papilar.","C":"Fibroma.","D":"Doença de Paget vulvar."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-183027","number":"183027","sourceNumber":"183027","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 21 anos, nuligesta, encaminhada pelo clínico geral ao consultório\nginecológico devido ao encontro de NIC 1 na\ncolpocitologia oncologica. A conduta ADEQUADA,\nnesse caso, é","options":{"A":"realizar colposcopia com biopsia.","B":"indicar conização profilática.","C":"aguardar 6 meses e repetir colpocitologia.","D":"solicitar hibridização para HPV."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-181395","number":"181395","sourceNumber":"181395","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O papillomavírus humano (HPV) é classificado em 140 tipos genômicos, divididos em\ngrupos, de acordo com o risco oncogênico: baixo risco (principalmente os subtipos 6 e 11) e alto\nrisco (principalmente os subtipos 16 e 18). Além da infecção pelo HPV de alto risco, outras\ncondições aumentam o risco para o desenvolvimento de lesões pré-neoplásicas e de carcinoma\ninvasor do colo uterino. Dados os fatores de risco para as patologias descritas: I. Tabagismo; II.\nIniciação sexual precoce; III. Multiplicidade de parceiros sexuais; IV. Nuliparidade. Verifica-se\nque\nestão corretos apenas:","options":{"A":"I e II.","B":"I e IV.","C":"II e III.","D":"III e IV.","E":"I, II e III."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-161214","number":"161214","sourceNumber":"161214","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação à Neoplasia Intraepitelial Cervical (NIC), assinale a alternativa em que a\nafirmação esteja INCORRETA.","options":{"A":"Sua incidência varia com a população estudada, já que está fortemente relacionada com\nprecocidade sexual, fatores socioeconômicos e comportamentos de risco.","B":"As lesões pré-invasivas (NIC 1) podem regredir espontaneamente.","C":"Multiplicidade de parceiros pode ser considerado risco aumentado para NIC.","D":"Parceiro único, com múltiplas parceiras sexuais, não representa risco aumentado para NIC."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-161365","number":"161365","sourceNumber":"161365","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente sem queixas ginecológicas, com diagnóstico de Metaplasia Escamosa ao\nexame de papanicolau, é encaminha ao\nambulatório de ginecologia cirúrgica para\nacompanhamento. Nesse caso, a conduta será:","options":{"A":"Colposcopia com biópsia da área de metaplasia.","B":"Aplicação de ácido tricloroacético a 90% em colo uterino.","C":"Nada a fazer.","D":"Conização com margem de segurança."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-161279","number":"161279","sourceNumber":"161279","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 16 anos procura consultório ginecológico relatando ter vida sexual ativa,\nsolicitando coleta de exames preventivos. O médico realiza exame ginecológico completo e\nprescreve anticoncepcional oral. Após consulta, a mãe da paciente procura o médico querendo\nsaber se a filha é virgem. Nesse caso, o médico","options":{"A":"deve manter o sigilo, não relatando nada à mãe.","B":"deve contar os fatos à mãe para resguardar a saúde da paciente.","C":"deve solicitar a presença do pai para relatar os fatos referentes à consulta.","D":"não deveria ter prescrito o anticoncepcional sem antes pedir permissão à mãe ou pai da\npaciente."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-134895","number":"134895","sourceNumber":"134895","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao Carcinoma do Colo Uterino, aponte a alternativa CORRETA.","options":{"A":"O principal agente etiológico é o Papilomavírus Humano.","B":"O Papilomavírus Humano é necessário para o seu desenvolvimento.","C":"O Papilomavírus Humano pode não ser suficiente para o seu desenvolvimento.","D":"Todas as anteriores estão corretas."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-134866","number":"134866","sourceNumber":"134866","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 26 anos, G2P2A0C2, fez exame de Papanicolaou cujo resultado foi\n\n?carcinoma in situ?. Diante de tal resultado, qual é a MELHOR conduta?","options":{"A":"Controle anual com Papanicolaou.","B":"Fazer Conização.","C":"Repetir Papaniclaou em 6 meses.","D":"Fazer Colposcopia e Biópsia dirigida."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-134100","number":"134100","sourceNumber":"134100","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 22 anos, vida sexual ativa, usa ACO, comparece em consulta de rotina\ncom exame de preventivo com diagnóstico de NIC I / lesão de baixo grau. Qual é a MELHOR\nconduta diante de tal diagnóstico?","options":{"A":"Colposcopia e biópsia.","B":"Conização.","C":"Ultrassonografia endovaginal.","D":"Repetir exame de 6 / 6 meses."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-134058","number":"134058","sourceNumber":"134058","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O adenocarcinoma do endométrio pode ser descrito por todas as seguintes afirmativas,\nEXCETO uma. Indique-a.","options":{"A":"É principalmente uma doença de mulheres na pós-menopausa.","B":"A média de idade das mulheres afetadas é superior à média de idade das mulheres portadoras\nde carcinoma cervical.","C":"Possui um prognóstico mais favorável que o do câncer cervical, com uma taxa de sobrevida em\ncinco anos próxima de 75%.","D":"Sua incidência está relacionada ao número de parceiros sexuais."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-134347","number":"134347","sourceNumber":"134347","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 17 anos, G0P0, com vida sexual ativa desde os 15 anos, sem método\ncontraceptivo desde então. Refere lesões\nverrucosas em vulva há 2 meses, que estão aumentando\nde tamanho. Qual é o diagnóstico MAIS provável?","options":{"A":"Herpes genital.","B":"Foliculite.","C":"Condiloma acuminado.","D":"Cisto de Bartholin."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-134285","number":"134285","sourceNumber":"134285","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação à drenagem venosa ovariana esquerda, ou seja, vascularização venosa do\novário esquerdo, ocorre para a:","options":{"A":"Veia cava inferior.","B":"Veia renal.","C":"Veia ilíaca.","D":"Veia hipogástrica."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-110565","number":"110565","sourceNumber":"110565","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"São fatores associados ao maior risco de câncer do colo uterino, EXCETO:","options":{"A":"Más condições de higiene.","B":"Má nutrição.","C":"Doenças sexualmente transmissíveis.","D":"HIV.","E":"Nuliparidade."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-110569","number":"110569","sourceNumber":"110569","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O principal cofator relacionado ao câncer de colo do útero é:","options":{"A":"Promiscuidade sexual.","B":"HIV.","C":"Infecção pelo HPV.","D":"Desnutrição.","E":"Multiparidade."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-109977","number":"109977","sourceNumber":"109977","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"No exame de Colposcopia, podemos considerar como achados anormais durante a\nrealização desse exame, EXCETO","options":{"A":"Leucoplasia.","B":"Epitélio acetobranco.","C":"Pontilhado e mosaico.","D":"Junção escamocolunar."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-109723","number":"109723","sourceNumber":"109723","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 22 anos, vida sexual ativa, vem para consulta ginecológica de rotina,\nreferindo aparecimento de lesões verrucosas em\nregião vulvar, que aumentaram de tamanho após\ndepilação. Qual é a PRINCIPAL suspeita diagnóstica?","options":{"A":"Herpes simples vulvar.","B":"Condiloma acuminado.","C":"Cancro mole.","D":"Molusco contagioso."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-86822","number":"86822","sourceNumber":"86822","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Os cistos de Naboth resultam:","options":{"A":"De remanescentes do ducto de Wolff;","B":"Do bloqueio de criptas na cérvix uterina que são revestidas por epitélio colunar;","C":"De resíduos de células escamosas que causam irritação cervical;","D":"De carcinoma;","E":"De remanescentes paramesonéfricos."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-108590","number":"108590","sourceNumber":"108590","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"São resultado da obstrução dos ductos das glândulas secretoras de muco do\nrevestimento epitelial do colo uterino:","options":{"A":"Cistos de ovário.","B":"Pólipo endometrial.","C":"Veias subserosas.","D":"Cistos de Naboth.","E":"Glândula de Skene."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-49631","number":"49631","sourceNumber":"49631","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"São consideradas fístulas geniturinárias, EXCETO:","options":{"A":"Uretrovaginal.","B":"Vesicovaginal.","C":"Retovaginal.","D":"Ureterovaginal.","E":"Ureterouterina."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-49602","number":"49602","sourceNumber":"49602","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A complicação séria mais comum da histerectomia radical é:","options":{"A":"Obstrução intestinal.","B":"Doença advinda da transfusão.","C":"Fístula genitourinária.","D":"Infecção.","E":"Óbito intraoperatório."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-13132","number":"13132","sourceNumber":"13132","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"As vacinas anti-HPV terão melhor resposta se aplicadas:","options":{"A":"Antes do início da atividade sexual.","B":"Imediatamente após o início da atividade sexual.","C":"Na idade adulta.","D":"Em qualquer idade.","E":"NDA."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-298236","number":"298236","sourceNumber":"298236","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente 35 anos, fez citologia oncótica cujo resultado foi ASC-US. Qual a conduta\nCORRETA?","options":{"A":"Biópsia","B":"Repetir citologia em 6 meses","C":"Colposcopia","D":"Repetir citologia em 12 meses"},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-298237","number":"298237","sourceNumber":"298237","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente 19 anos realizou citologia oncótica cujo resultado foi ASC-US. Qual a conduta\nCORRETA?","options":{"A":"Reavaliar em 3 anos e caso essa atipia se persista, manter seguimento trienal até 25 anos. Se\npersistir a citologia de ASC-US ou aumentar a gravidade, encaminhar para colposcopia com 25\nanos.","B":"Reavaliar em 3 anos e caso essa atipia persista, ou aumentar a gravidade, encaminhar para\ncolposcopia.","C":"Reavaliar em 1 ano e caso essa atipia persista, manter seguimento anual até 25 anos. Se\npersistir a citologia de ASC-US ou aumentar a gravidade, encaminhar para colposcopia.","D":"Reavaliar em 1 ano e caso essa atipia persista, ou aumentar a gravidade, encaminhar para\ncolposcopia."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-286756","number":"286756","sourceNumber":"286756","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente, 20 anos, nuligesta, foi ao ambulatório com queixa de sinusiorragia, corrimento\nvaginal e dor pélvica. Realizou biópsia de\ncolo que evidenciou carcinoma escamoso estádio 1 A.\nQual o tratamento indicado para essa paciente?","options":{"A":"Conização a frio","B":"Histerectomia radical com linfadenectomia pélvica","C":"Histerectomia com ooforectomia","D":"Traquelectomia"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-252258","number":"252258","sourceNumber":"252258","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente retornou com resultado de preventivo: amostra satisfatória, presença de\nepitélio escamoso, negativo para neoplasia,\nLactobacillus sp. Ela tinha um exame do ano anterior\nnormal. Sua conduta deve ser:","options":{"A":"Repetir o exame em 3 anos.","B":"Repetir o exame em 6 meses.","C":"Repetir imediatamente o exame.","D":"Repetir o exame em 1 ano."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-208387","number":"208387","sourceNumber":"208387","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O carcinoma cervical é a terceira malignidade ginecológica no mundo. Sobre essa\nneoplasia, assinale a opção CORRETA:","options":{"A":"O Papanicolau não é um exame sensível para o diagnóstico do subtipo do adenocarcinoma de\ncélula claras.","B":"A disseminação ocorre principalmente pela via hematogênica.","C":"O câncer cervical se origina no epitélio escamoso maduro, propagando-se para a endocérvice\napós anos do seu aparecimento.","D":"O mais importante preditor de recorrência da doença é o estado dos linfonodos para aórticos."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-151889","number":"151889","sourceNumber":"151889","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"JXB, 26 anos, procurou o hospital ginecológico com sangramento vaginal com odor\nfétido e dor em baixo ventre há 3 semanas. Nunca foi ao ginecologista. Ao exame especular,\nobservou-se lesão vegetante e friável com sangramento moderado vindo da lesão. Baseado na\nhipótese diagnóstica, qual dos exames abaixo tem a capacidade de avaliar: profundidade da\ninvasão, tamanho tumoral, extensão parametrial, extensão vaginal, invasão de bexiga e reto,\navaliar metástase à distância e avaliar metástase linfonodal?","options":{"A":"Ressonância Nuclear Magnética.","B":"Tomografia computadorizada","C":"Ultrassonografia.","D":"PET"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-129759","number":"129759","sourceNumber":"129759","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Léia foi ao ambulatório para pegar o resultado da colpocitologia oncótica que tinha\nfeito.\nO resultado foi de metaplasia escamosa\nimatura. Qual a conduta CORRETA a ser adotada?","options":{"A":"Solicitar colposcopia.","B":"Indicar conização.","C":"Repetir a citologia.","D":"Seguir rotina de rastreamento citológico."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-129790","number":"129790","sourceNumber":"129790","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Adolescente de 15 anos com diagnóstico histológico de NIC 2 (Neoplasia Intraepitelial\nCervical) sem outra especificação. É INCORRETO\nafirmar:","options":{"A":"Após três resultados negativos consecutivos para neoplasia intraepitelial ou lesão invasora\n(citologia e colposcopia negativas, com\ncolposcopia satisfatória), as adolescentes podem voltar ao\nrastreamento citológico de rotina.","B":"O acompanhamento prospectivo em mulheres jovens deve ser limitado àquelas dispostas a\naderirem as recomendações.","C":"É recomendável tratamento quando há persistência de NIC 2 por 24 meses.","D":"A observação deve ser realizada por citologia e colposcopia semestrais por até 24 meses."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-107893","number":"107893","sourceNumber":"107893","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Assinale a afirmativa correta sobre o câncer de colo uterino:","options":{"A":"São fatores de risco para o câncer de colo: relação sexual em idade jovem, tabagismo, paridade\nelevada e baixa condição sócio econômica.","B":"Não há relação entre o início da idade da relação sexual e câncer de colo.","C":"O sintoma mais comum do câncer de colo é a dispareunia.","D":"No estágio IIa o carcinoma se estende além do colo, atinge paramétrio mas não atinge a parede."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-103875","number":"103875","sourceNumber":"103875","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com aproximadamente 530 mil casos novos por ano no mundo, o câncer do colo do\nútero é o terceiro tipo de câncer mais comum entre as mulheres, sendo responsável pelo óbito de\n274 mil mulheres por ano (WHO, 2008). Na análise regional no Brasil, o câncer do colo do útero\ndestaca-se como o primeiro mais incidente na Região Norte, com 24 casos por 100 mil mulheres.\nAssinale a alternativa CORRETA:","options":{"A":"A transmissão da infecção pelo HPV ocorre por via sexual, presumidamente por meio de\nabrasões microscópicas na mucosa ou na pele da\nregião anogenital. Consequentemente, o uso de\npreservativos durante a relação sexual com penetração protege totalmente do contágio pelo HPV.","B":"As lesões precursoras do câncer do colo do útero costumam ser sintomáticas, podendo ser\ndetectadas por meio da realização periódica do exame citopatológico e confirmadas pela\ncolposcopia e exame histopalógico.","C":"A Reunião de Consenso, realizada em 1988 pelo Ministério da Saúde, definiu que, no Brasil, o\nexame citopatológico deveria ser priorizado para mulheres de 25 a 60 anos, uma vez por ano e,\napós dois exames anuais consecutivos negativos, a cada três anos.","D":"Há duas principais categorias de carcinomas invasores do colo do útero, dependendo da origem\ndo epitélio comprometido: o carcinoma\nepidermoide, que acomete o epitélio escamoso (representa\ncerca de 20% dos casos), e o adenocarcinoma, que acomete o epitélio glandular."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-103847","number":"103847","sourceNumber":"103847","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com relação ao colo uterino durante a gestação é INCORRETO afirmar:","options":{"A":"As glândulas da cérvice sofrem uma proliferação tão acentuada que, ao final da gravidez,\nocupam aproximadamente metade da massa do colo.","B":"Somente após a 30ª semana o colo uterino inicia um processo de amolecimento e cianose.\n\nEssas alterações resultam de aumento da vascularidade e edema em todo o colo, junto com\nhipertrofia e hiperplasia das glândulas da cérvice.","C":"As células da mucosa endocervical produzem uma grande quantidade de muco tenaz que\nobstrui o canal da cérvice logo após a concepção.","D":"A gravidez está associada à hiperplasia glandular endocervical e ao aspecto hipersecretório\n(Reação de Arias-Stella), que torna difícil a\nidentificação de células glandulares atípicas no exame\ncitológico do colo uterino."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-107778","number":"107778","sourceNumber":"107778","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 44 anos retorna ao médico de família e comunidade trazendo resultado de\nseu exame citopatológico (CP) do colo\nuterino coletado há 02 meses. O laudo informa: amostra\nsatisfatória; células escamosas, endometriais e metaplásicas representadas; e células escamosas\natípicas de significado indeterminado possivelmente não neoplásico. O exame anterior, realizado há\ndois anos, era normal. A paciente encontra-se sem queixas no momento. Assinale a alternativa que\ncontém a conduta adequada diante do caso apresentado:","options":{"A":"Indicar colposcopia imediatamente para confirmação diagnóstica.","B":"Tratar com antibiótico via oral de amplo espectro.","C":"Repetir o CP em 06 meses.","D":"Encaminhar ao ginecologista para investigação."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-81991","number":"81991","sourceNumber":"81991","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Qual papilomavírus humano é mais comum em paciente com câncer cervical invasivo\n(HPV) e qual é mais comum nas verrugas genitais, respectivamente?","options":{"A":"HPV 16, HPV 6","B":"HPV 6, HPV 16","C":"HPV 11, HPV 6","D":"HPV 18, HPV 16","E":"HPV 6, HPV 11"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-81007","number":"81007","sourceNumber":"81007","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 48 anos vem para consulta com seu Médico de Família e Comunidade\ntrazendo o resultado de seu exame\ncitopatológico do colo uterino coletado há 2 meses. Resultado\ndo exame; amostra satisfatória; células escamosas endometriais e metaplásicas representadas;\ncélulas escamosas atípicas de significado indeterminado possivelmente não neoplástica. O exame\nanterior, realizado há dois anos, era normal. A paciente encontra-se sem queixas no momento.\n\nAssinale a alternativa que contém a conduta adequada diante do caso apresentado.","options":{"A":"Indicar colposcopia imediatamente para confirmação diagnóstica.","B":"Tratar com antibiótico via oral de amplo espectro.","C":"Tratar com creme vaginal e repetir o CP em 10 dias","D":"Repetir o CP em 6 meses","E":"Encaminhar ao ginecologista para investigação."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-60962","number":"60962","sourceNumber":"60962","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 28 anos realiza seu primeiro exame de preventivo. Ela tem vida sexual\nativa há 5 anos e relata 2 parceiros sexuais\nnesse período. O exame ginecológico é normal,\nentretanto o resultado da citologia revela a presença de lesão intraepitelial escamosa de alto grau,\nidentificada como NIC II (HSIL), sem a presença de células endocervicais no esfregaço. A conduta\nmais apropriada para a paciente é:","options":{"A":"realizar conização cervical.","B":"realizar colposcopia e biópsia dirigida.","C":"realizar a pesquisa de HPV por método de biologia molecular.","D":"estimular o uso de condom e repetir a citologia em 4 meses.","E":"repetir imediatamente a citologia oncótica para obter amostragem de células endocervicais."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-60832","number":"60832","sourceNumber":"60832","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com relação à infecção pelo HPV, assinale a alternativa INCORRETA.","options":{"A":"A taxa de HPV em esfregaços citológicos diminui com a idade","B":"A imunidade do hospedeiro influencia na duração da infecção","C":"A maioria dos casos de lesão de baixo grau apresenta HPV de alto risco","D":"As infecções por HPV de baixo e alto risco podem regredir espontaneamente","E":"Os tipos de baixo risco são encontrados com frequência no câncer invasor"},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-46730","number":"46730","sourceNumber":"46730","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Sobre o câncer de colo uterino podemos afimar:","options":{"A":"O papiloma vírus humano está relacionado com a incidência de em até 99% dos carcinomas\nepidermoides e os sorotipos 6 e 11 são encontrados em até 62% dos carcinomas cervicais.","B":"Podem ser considerados sinais clínicos de lesão invasiva: secreção vaginal de odor fétido,\nuropatia obstrutiva, hemorragia vaginal e emagrecimento.","C":"A idade da sexarca não se inclui dentre os fatores de risco do câncer cervical como estão: o\nnúmero de parceiros sexuais, raça, paridade elevada e baixa condição socioeconômica.","D":"a colposcopia não é obrigatória em pacientes com suspeita de neoplasia invasiva incipiente,\nvisto que o diagnóstico só poderá ser concluído\ncom a citologia cervical e a aparência do colo no\nexame ginecológico.","E":"Nenhuma das alternativas anteriores."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-46720","number":"46720","sourceNumber":"46720","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente procura unidade básica de saúde com colpocitologia mostrando lesão\nintraepitelial de baixo grau do efeito citopático do papilomavírus humano. Qual a deverá ser a\nconduta indicada pelo médico?","options":{"A":"Repete a colpocitologia em 6 meses.","B":"Repete colpocitologia pelo método da citologia líquida.","C":"Solicita captura híbrida.","D":"Encaminha para colposcopia.","E":"Nenhuma das alternativas anteriores."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-46679","number":"46679","sourceNumber":"46679","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A antatomia e embriologia do aparelho reprodutor é absolutamente importante para o\nentendimento de algumas doenças e seus respectivos tratamentos. Em relação a anatomia do colo\nuterino podemos afirmar:","options":{"A":"A eversão ou ectopia é um distúbio que pode ser observado muito frequentemente na gestação\nou em mulheres que utilizam como método os\ncontraceptivos orais.","B":"O canal endocervical é revestido por epitélio estratificado, secretor de muco, o que faz\napresentar-se após o teste de Schiller sem impregnação pela solução de lugol.","C":"As tubas uterinas são divididas em 4 porções. O maior segmento, o infundíbulo, é suprido pela\nartéria uterina e ovárica.","D":"O tamanho e o formato do corpo uterino independem do estado hormonal e da paridade.","E":"Nenhuma das alternativas anteriores."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-26504","number":"26504","sourceNumber":"26504","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"São fatores de Risco para o câncer de Corpo Uterino:","options":{"A":"Idade abaixo de 40 anos","B":"Multíparas","C":"Biótipo: Mulheres Obesas","D":"Menopausa Precoce","E":"Oligonomenorreia"},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-26506","number":"26506","sourceNumber":"26506","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O Condiloma Acuminatum leva ao aumento da incidência de neoplasia de cérvice\nuterina principalmente dos sorotipos:","options":{"A":"16-15","B":"6-11","C":"12-18","D":"34-12","E":"18-6"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-7519","number":"7519","sourceNumber":"7519","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Cistos de Naboth são encontrados em paciente que previamente apresentou:","options":{"A":"disceratose.","B":"ectopia.","C":"vaginite por tricomonas.","D":"NIV.","E":"NIC."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-7441","number":"7441","sourceNumber":"7441","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Os subtipos mais comuns de papilomavírus humano (HPV), associados a verrugas\ngenitais, são:","options":{"A":"HPV - 1 e 2.","B":"HPV - 4 e 7.","C":"HPV - 18 e 24.","D":"HPV - 6 e 11.","E":"HPV - 22 e 23."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-7481","number":"7481","sourceNumber":"7481","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação ao Estadiamento do Câncer Cervical:","options":{"A":"Estágio 0 - carcinoma in situ.","B":"Estágio I - carcinoma confinado ao colo do útero.","C":"Estágio II - carcinoma estende-se além do colo do útero, mas não atinge a parede pélvica.","D":"Estágio III - carcinoma se estende à parede pélvica, 1/3 inferior da vagina e parte da bexiga.","E":"Estágio IV - o carcinoma já se estendeu para além de pelve verdadeira, invadiu bexiga e reto; já\npossuem metástases a distância."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-294480","number":"294480","sourceNumber":"294480","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher, 71 anos de idade, nuligesta, procura atendimento devido à sangramento genital\nde pequena quantidade, há 15 dias.\nAntecedentes médicos: Hipertensa. Antecedentes\nginecológicos: Menarca aos 11 anos, na menacme apresentava ciclos longos, menopausou aos 49\nanos, não faz reposição hormonal e não tem mais vida sexual ativa. Ao exame físico, PA:\n130x80mmHg; Peso: 79Kg; Altura: 1,64m; Circunferência abdominal: 89cm. Exame segmentar:\nsem nenhum achado relevante. Vulva coaptada, sem lesões. Exame especular: Mucosa pálida,\ncolo aparentemente epitelizado, sangramento +/4+ fluindo pelo Orifício externo; Toque vaginal:\nútero AVF volume normal; anexos não palpáveis. Indique os fatores de risco mais prevalentes\nassociados à principal hipótese diagnóstica:","options":{"A":"Infertilidade, uso de Tamoxifeno e síndrome de ovários de policísticos.","B":"Hipertensão, diabetes e menarca tardia.","C":"Menarca tardia, obesidade e diabetes.","D":"Hipertensão, infertilidade e menopausa precoce."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-62863","number":"62863","sourceNumber":"62863","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente, 22 anos de idade, apresenta, no exame citopatológico cervical, diagnóstico\nde lesão intraepitelial de baixo grau (LSIL).\nSeguindo as recomendações do Ministério da Saúde, a\nconduta é:","options":{"A":"solicitar biópsia da LSIL.","B":"repetir o exame citopatológico com seis meses.","C":"realizar a cirurgia de alta frequência.","D":"realizar histerectomia.","E":"repetir exame citopatológico com um ano."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-49402","number":"49402","sourceNumber":"49402","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Adolescente, 15 anos de idade, tem achado na citologia (Bethesda): lesão intraepitelial\nescamosa de alto grau, HSIL. A próxima conduta a ser tomada para esse caso é:","options":{"A":"indicar vacina quadrivalente.","B":"realizar cirurgia de alta frequência.","C":"realizar biópsia.","D":"realizar colposcopia.","E":"realizar histerectomia."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-27469","number":"27469","sourceNumber":"27469","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente, 33 anos de idade, apresenta resultado de histopatologia de biópsia do colo\nuterino compatível com lesão de alto grau, localizada ao nível da JEC. A conduta mais adequada\npara esse caso é:","options":{"A":"controle colposcópico.","B":"captura híbrida","C":"excisão da lesão por cirurgia de alta frequência (LEEP)","D":"ablação da lesão por ATA 80%.","E":"histerectomia total."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-13370","number":"13370","sourceNumber":"13370","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente, 52 anos de idade, G4P3A1, queixa-se de sangramento pós-coital há 7\nmeses. Relata, ainda, fluxo genital com mau\ncheiro há 15 dias. Coitarca aos 15 anos. Relata\npassado de sífilis e ser tabagista desde os 17 anos, fumando atualmente uma carteira por dia. Ao\nexame físico, TA: 100 X 70 mmHg, PR: 80 bpm. Exame segmentar sem alterações. Exame\nespecular revela lesão exofítica de 2,0 cm em lábio anterior do colo uterino. Considerando-se a\nhistória clínica e os achados referidos, o próximo passo na avaliação da paciente é:","options":{"A":"realização do Papanicolau","B":"biópsia da lesão","C":"conização do colo com LEEP","D":"conização alargada do colo","E":"ultrassonografia transvaginal"},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-13374","number":"13374","sourceNumber":"13374","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente, 52 anos de idade, G4P3A1, queixa-se de sangramento pós-coital há 7\nmeses. Relata, ainda, fluxo genital com mau\ncheiro há 15 dias. Coitarca aos 15 anos. Relata\npassado de sífilis e ser tabagista desde os 17 anos, fumando atualmente uma carteira por dia. Ao\nexame físico, TA: 100 x 70 mmHg, PR: 80 bpm. Exame segmentar sem alterações. Exame\nespecular revela lesão exofítica de 2,0 cm em lábio anterior do colo uterino. São fatores para\ncâncer de colo uterino, EXCETO:","options":{"A":"Coitarca precoce","B":"Tabagismo","C":"DST","D":"Menopausa tardia","E":"Multiparidade"},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-13376","number":"13376","sourceNumber":"13376","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente, 52 anos de idade, G4P3A1, queixa-se de sangramento pós-coital há 7\nmeses. Relata, ainda, fluxo genital com mau\ncheiro há 15 dias. Coitarca aos 15 anos. Relata\npassado de sífilis e ser tabagista desde os 17 anos, fumando atualmente uma carteira por dia. Ao\nexame físico, TA: 100 X 70 mmHg, PR: 80 bpm. Exame segmentar sem alterações. Exame\nespecular revela lesão exofítica de 2,0 cm em lábio anterior do colo uterino. Dos tipos de HPV a\nseguir, os que estão relacionados ao câncer cervical são:","options":{"A":"2, 4, 16 e 18","B":"6, 11, 16 e 18","C":"16, 18, 31 e 33","D":"6, 11, 31 e 33","E":"31, 33, 44 e 46"},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-218128","number":"218128","sourceNumber":"218128","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Maria Aparecida, negra, 36 anos, bem-humorada, compareceu à Unidade Básica de\nSaúde onde tem como equipe: a agente de\nsaúde Filomena, a técnica de enfermagem Carla, o\nenfermeiro Mário e a médica Daiane. Maria Aparecida tem uma história de realização de\nCitopatológico (CP) de colo de útero com uma certa regularidade. Seu último exame foi há 3 anos,\nquando era casada com Paulo, uma relação que durou 7 anos. O resultado fora normal. Na mesma\nocasião, em uma campanha de educação em saúde promovida pelo Ministério da Saúde e\nSecretarias de Saúde do Estado e do Município, Maria fez a mamografia também com resultados\nnormais. Maria Aparecida teve menarca aos 13 anos, sexarca aos 16 anos. Teve uma filha, Lelê, e\num filho, Carlinhos, com Paulo. Duas gestações com dois partos vaginais. Maria Aparecida\nmenstrua regularmente. Sem casos conhecidos de câncer de mama na família. Divorciou-se de\nPaulo há 2 anos: me libertei doutora - sempre dizia à Daiane. Recentemente, conheceu um homem\nde 30 anos, Valdomiro, com quem está namorando e já está pensando em se \"juntar\". Maria é\nhipertensa em uso de enalapril 10 mg de 12/12 horas. Na consulta, observou-se PA = 140/ 90\nmmHg, pesa 78 kg, mede 1,60 m de altura (IMC 30,5). Considerando o caso clínico acima, sobre o\nrastreamento de câncer de colo de útero, segundo as diretrizes nacionais do Ministério da Saúde, é\nCORRETO afirmar que:","options":{"A":"O CP está no tempo certo. Deve ser recomendado um novo exame e, se normal, repetir o\npróximo em três anos.","B":"O CP está atrasado, portanto, deve ser feito o mais rápido possível e, se normal, repetir o\npróximo em dois anos.","C":"É recomendado realizar o CP e, se for encontrada lesão intraepitelial de baixo grau, passar a\nfazer a rotina anualmente.","D":"Realizar o CP e, se forem encontradas lesões escamosas mesmo que provavelmente não\nneoplásicas, encaminhar para colposcopia.","E":"O CP está atrasado, portanto, deve ser feito o mais rápido possível e, se normal, repetir,\nanualmente, em casa campanha nacional ou municipal."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-215614","number":"215614","sourceNumber":"215614","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O objetivo principal do tratamento das lesões anogenitais induzidas pelo HPV é a\nremoção das lesões clínicas. Não sendo adequado o seguinte item:","options":{"A":"Se não houver esse tratamento, os condilomas podem desaparecer, permanecer inalterados ou\naumentar em tamanho ou número.","B":"Nenhuma evidência indica que os tratamentos disponíveis erradicam ou afetam a história natural\nda infecção do HPV.","C":"Como o carcinoma escamoso costuma surgir mais raramente em imunossuprimidos, valoriza-se\na biópsia de lesões nesse grupo.","D":"O tratamento das lesões anogenitais induzidas pelo HPV deve ser individualizado, considerando\ntamanho, morfologia, número e local das lesões."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-215617","number":"215617","sourceNumber":"215617","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Outros fatores necessitam ser considerados no momento da decisão terapêutica das\nlesões induzidas pelo HPV, como preferência do\npaciente, custos, disponibilidade de recursos,\nconveniência, efeitos adversos e experiência do profissional de saúde. Sobre isso, está inadequado\no item:","options":{"A":"As verrugas anogenitais localizadas em superfícies úmidas e/ou nas áreas intertriginosas\nrespondem pior à terapêutica tópica (ex.: ácido\ntricloroacético ? ATA, podofilina) que as verrugas\nem superfícies secas.","B":"Deve-se mudar de opção terapêutica quando um paciente não apresentar melhora significativa\napós três sessões, ou se as verrugas não\ndesaparecerem após seis sessões.","C":"Menos frequentemente, podem estar presentes em áreas extragenitais, como conjuntivas,\nmucosa nasal, oral e laríngea.","D":"A infecção por um genótipo de HPV não impede a infecção por outros tipos de HPV. O\ntratamento deve basear-se nos mesmos princípios referidos para os não-imunossuprimidos."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-181196","number":"181196","sourceNumber":"181196","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em caso de citologia evidenciando ASC-US (Células Escamosas Atípicas de\nSignificado Indeterminado), a conduta que não condiz com opção terapêutica válida é:","options":{"A":"Teste reflexo para DNA de HPV.","B":"Conização em mulheres com prole constituída.","C":"Repetir citologia com 6 e 12 meses.","D":"Colposcopia imediata caso o acompanhamento futuro seja incerto (pacientes problemáticas)."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-181158","number":"181158","sourceNumber":"181158","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação à Neoplasia Intra-epitelial Cervical (NIC), assinale o fator de risco que não\nse aplica a essa patologia:","options":{"A":"Início precoce de atividade sexual.","B":"Antecedente familiar de primeiro grau.","C":"Tabagismo.","D":"Parceiro masculino com várias parceiras sexuais."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-181164","number":"181164","sourceNumber":"181164","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente portadora de câncer de endométrio geralmente procura o ginecologista\nreferindo o seguinte sintoma:","options":{"A":"Sangramento via vaginal pós- menopausa.","B":"Emagrecimento.","C":"Vômitos.","D":"Edema assimétrico de membros inferiores."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-157656","number":"157656","sourceNumber":"157656","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente cujo citopatológico evidenciou NIC 2, é CORRETO afirmar que:","options":{"A":"É suficiente realizar o citopatológico a cada 6 meses.","B":"Está indicada colposcopia com biópsia.","C":"Está indicada hibridização para HPV.","D":"É suficiente realizar citopatológico de rotina, anualmente."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-139751","number":"139751","sourceNumber":"139751","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao carcinoma do colo uterino:","options":{"A":"O principal agente etiológico é o Papilomavírus Humano.","B":"O Papilomavírus Humano é necessário para seu desenvolvimento.","C":"O Papilomavírus Humano pode não ser suficiente para o seu desenvolvimento.","D":"Todas as alternativas anteriores estão corretas."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-139744","number":"139744","sourceNumber":"139744","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer de colo, estádio III, costuma produzir:","options":{"A":"Exclusão renal.","B":"Nefrite intersticial.","C":"Parametrite.","D":"Ureterotrigonite."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-139747","number":"139747","sourceNumber":"139747","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Qual é a neoplasia ginecológica mais comum?","options":{"A":"Carcinoma do colo uterino.","B":"Carcinoma do endométrio.","C":"Carcinoma de vulva.","D":"Carcinoma de fundo de saco vaginal."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-134707","number":"134707","sourceNumber":"134707","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 22 anos, vida sexual ativa, vem para consulta ginecológica de rotina,\nreferindo aparecimento de lesões verrucosas em\nregião vulvar, que aumentaram de tamanho após\ndepilação. Qual é a PRINCIPAL suspeita diagnóstica?","options":{"A":"Herpes simples vulvar.","B":"Condiloma acuminado.","C":"Cancro mole.","D":"Molusco contagioso."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-111835","number":"111835","sourceNumber":"111835","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao Carcinoma do Colo Uterino:","options":{"A":"o principal agente etiológico é o Papilomavírus Humano.","B":"o Papilomavírus Humano é necessário para o seu desenvolvimento.","C":"o Papilomavírus Humano pode não ser suficiente para o seu desenvolvimento.","D":"todas as anteriores estão corretas."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-111929","number":"111929","sourceNumber":"111929","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 22 anos, vida sexual ativa, usa ACO, comparece em consulta de rotina\ncom exame de preventivo com diagnóstico de NIC I / lesão de baixo grau. Qual é a MELHOR\nconduta diante de tal diagnóstico?","options":{"A":"Colposcopia e biópsia.","B":"Conização.","C":"Ultrassonografia endovaginal.","D":"Repetir exame de 6 / 6 meses."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-111907","number":"111907","sourceNumber":"111907","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação à vacina do HPV, é CORRETO afirmar que:","options":{"A":"portadoras de displasias cervicais não se beneficiam.","B":"necessita de reforço após cinco anos.","C":"sua eficácia é de 70%.","D":"a quadrivalente está indicada para mulheres entre 9 e 26 anos."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-321371","number":"321371","sourceNumber":"321371","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"VSS, 36 anos, G4P4A0, comparece a UBS para receber resultado de citologia\n\ncérvico-vaginal colhida há 1 mês, que revelou ASC-US (Células escamosas atípicas de significado\nindeterminado). Qual a melhor conduta?","options":{"A":"Colposcopia e avaliação endometrial.","B":"Manter periodicidade normal das suas citologias pois este achado não representa nenhum risco.","C":"Manter vigilância com citologia e encaminhar para colposcopia apenas se novos exames\nalterados.","D":"Colposcopia imediata, pela grande probabilidade de este achado citológico indicar a presença\nde lesão pré-neoplásica do colo uterino."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-259783","number":"259783","sourceNumber":"259783","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 37 anos, G2PC2, com dois filhos vivos, vem à consulta na policlínica com\nresultado de citologia oncótica, há um mês, revelando: células glandulares atípicas. Realizou\ncolposcopia e biópsia de colo, que mostrou adenocarcinoma in situ. Qual a melhor conduta a\nseguir?","options":{"A":"Nova citologia e exérese da zona de transformação.","B":"Conização e histeroscopia com biópsia.","C":"Histerectomia total com anexectomia.","D":"Histerectomia total simples."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-199711","number":"199711","sourceNumber":"199711","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Durante a campanha do Outubro Rosa, um agente comunitário de saúde leva paciente\nde 26 anos, lésbica, a unidade básica de\nsaúde e questiona sobre a necessidade de realizar o\nexame de Prevenção do Câncer de Colo Uterino (PCCU). A paciente teve sua primeira relação\nsexual aos 16 anos. Que pergunta o profissional de saúde deve fazer para decidir se há indicação\ndo exame de rastreamento?","options":{"A":"?Possui corrimento??.","B":"?Está sexualmente ativa??.","C":"?Qual a data de realização do último exame de PCCU??.","D":"?Já teve práticas sexuais com homens, anteriormente??."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-199786","number":"199786","sourceNumber":"199786","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher, 42 anos, sangramento intermitente há cerca de 6 meses, comparece à consulta\nginecológica para investigação. À colposcopia, apresenta lesão acetobranca no colo uterino. Não\nse evidenciou lesões vaginais. Ao toque retal, observou-se útero de volume normal e paramétrios\nsem anormalidades. A biópsia excisional por cirurgia de alta frequência revelou carcinoma\nescamoso com invasão estromal de 7 mm de profundidade. Qual o tratamento mais provável para\nessa paciente?","options":{"A":"Histerectomia radical sem anexectomia.","B":"Histerectomia tipo II e anexectomia.","C":"Histerectomia vaginal.","D":"Radioterapia pélvica."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-172989","number":"172989","sourceNumber":"172989","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 35 anos, G2P2A0, vem à UBS com resultado de exame de citologia do colo\nuterino de rotina cujo laudo traz escrita a seguinte conclusão: presença de Lesão Intraepitelial\nEscamosa de Baixo Grau (LIEBG). Realizou exame ginecológico com achado de colo uterino\nnormal. Qual a conduta mais adequada para esse caso, de acordo com o Ministério da Saúde do\nBrasil (2016)?","options":{"A":"Realizar colposcopia.","B":"Repetir citologia a cada 6 meses.","C":"Solicitar teste de DNA para HPV.","D":"Realizar excisão eletrocirúrgica em alça da zona de transformação."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-150886","number":"150886","sourceNumber":"150886","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 40 anos, assintomática, recebeu resultado de exame citológico recente com\no laudo \"Células Glandulares Atípicas\". Nega\ngravidez e não apresenta imunossupressão. Qual a\nconduta mais adequada a seguir?","options":{"A":"Referenciar para colposcopia e exérese da zona de transformação do colo uterino.","B":"Recomendar nova coleta para citologia de canal cervical e colposcopia, em seis meses.","C":"Indicar procedimento de conização do colo uterino com bisturi frio e curetagem de canal cervical\nem centro cirúrgico.","D":"Encaminhar para colposcopia com nova coleta para citologia de canal cervical e solicitar\nultrassom pélvico transvaginal."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-126960","number":"126960","sourceNumber":"126960","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mãe de 45 anos e filha de 16 anos comparecem à consulta no Posto de Saúde. Elas\nquestionam o médico sobre a realização de citologia oncótica de rastreamento para o câncer de\ncolo uterino. A mãe refere histerectomia total por leiomiomas uterinos há 5 anos e a filha traz\numa citologia realizada há 6 meses com resultado de LIE (Lesão Intra-epitelial escamosa) de baixo\ngrau. Sobre as orientações que devem ser dadas, à mãe e à filha, respectivamente, assinale a\nassertiva correta.","options":{"A":"Mãe: não recomendar mais citologia de rastreamento. Filha: repetir na ocasião da consulta nova\ncitologia oncótica e colposcopia.","B":"Mãe: recomendar citologia de rastreamento anual. Filha: repetir na ocasião da consulta nova\ncitologia oncótica e colposcopia.","C":"Mãe: não recomendar mais citologia de rastreamento. Filha: recomendar realização de citologias\nem intervalos de 12 meses.","D":"Mãe: recomendar citologia oncológica de rastreamento anual. Filha: recomendar realização de\ncitologias em intervalos de 12 meses."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-126972","number":"126972","sourceNumber":"126972","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 50 anos, G3P3A0, sem comorbidades, há 6 meses apresenta\nirregularidade menstrual com intervalos de 60 a 90\ndias e episódios de sangramento\ntransvaginal de grande monta com coágulos. Ao exame, apresenta-se estável\nhemodinamicamente, exame ginecológico sem alterações. Trouxe resultado de exame\nanatomopatológico de curetagem semiótica realizada há um mês cujo laudo foi compatível com\nhiperplasia endometrial com atipias. Sobre o melhor tratamento a ser tomado, assinale a\nassertiva correta.","options":{"A":"Histerectomia abdominal total.","B":"Histerectomia laparoscópica supracervical com extração uterina por mocelamento.","C":"Terapia de baixa dosagem de progestogênio cíclico por via oral por três a seis meses e biópsia\nendometrial ambulatorial anualmente.","D":"Terapia com alta dosagem de progestogênio oral diários contínuo por três a seis meses e\nbiópsia\n\nendometrial ambulatorial semestralmente."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-102104","number":"102104","sourceNumber":"102104","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 59 anos de idade, menopausada aos 52 anos (SIC), vem em busca de\norientações sobre como ?prevenir? câncer do\nútero, sua irmã, de 50 anos, teve recentemente o\ndiagnóstico de câncer de endométrio. Nega sangramento, é obesa e diabética controlada. Traz US\ntransvaginal que mostra miométrio heterogêneo e eco endometrial homogêneo de 7 mm. O método\ndefinitivo para o diagnóstico do CA de endométrio nesse caso é:","options":{"A":"Curetagem uterina fracionada.","B":"Biopsia endometrial guiada por vídeo-histeroscopia.","C":"Biopsia endometrial ambulatorial com cureta de Novak.","D":"Biopsia endometrial ambulatorial por aspiração manual intrauterina."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-65687","number":"65687","sourceNumber":"65687","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 46 anos de idade, IMC de 32 kg/m², laqueada, G4P4, apresenta ciclos\nmenstruais longos associados à hipermenorragia.\nApresentava espessamento endometrial ao\nexame ultrassonográfico. Após biópsia, o exame histopatológico de endométrio revelou aumento do\nnúmero e do tamanho de glândulas em proliferação irregular, com presença de atipias nucleares. A\nmelhor conduta terapêutica é:","options":{"A":"realizar histerectomia total.","B":"realizar a ablação endometrial.","C":"prescrever progestínico por via oral.","D":"prescrever contraceptivo hormonal combinado.","E":"inserir um sistema intrauterino liberador de levonorgestrel."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-51217","number":"51217","sourceNumber":"51217","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 28 anos realizou citologia oncótica cervicovaginal em dezembro de 2010 e\nnovembro de 2011 com resultados semelhantes: leve processo inflamatório, presença de\nlactobacillus, ausência de sinais de malignidade. Qual deve ser agora a periodicidade do\nrastreamento para câncer de colo uterino para essa mulher, segundo normas do Ministério da\nSaúde Brasileiro?","options":{"A":"A cada ano.","B":"A cada 2 anos.","C":"A cada 3 anos.","D":"A cada 6 meses."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-51298","number":"51298","sourceNumber":"51298","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 40 anos de idade foi submetida à biópsia de colo uterino guiada por\ncolposcopia em uma área de epitélio\nacetobranco. A análise histopatológica evidenciou mitoses e\ncélulas imaturas nos terços médio e superior do epitélio escamoso, não ultrapassando a membrana\nbasal. Qual o tratamento recomendado?","options":{"A":"Conização.","B":"Histerectomia.","C":"Eletrocauterização.","D":"Aplicação de ácido tricloroacético a 90%."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-51302","number":"51302","sourceNumber":"51302","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 16 anos, sexo feminino, assintomática, vem ao consultório médico com\nlaudo de exame citopatológico de colo uterino, mostrando lesão intraepitelial de baixo grau,\nprocesso inflamatório leve, presença de lactobacilos. Qual a conduta a ser seguida?","options":{"A":"Cauterizar o colo uterino.","B":"Pesquisar HPV oncogênico.","C":"Tratar o processo inflamatório.","D":"Repetir o exame em 6 a 12 meses."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-141584","number":"141584","sourceNumber":"141584","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente 35 anos, G3P3A0, com citologia oncótica mostrando lesão intra-epitelial de\nalto grau. Foi submetida a biópsia de colo\nuterino que revelou Neoplasia Intra-Cervical grau III. Qual\na melhor conduta?","options":{"A":"Conização.","B":"Cauterização.","C":"Histerectomia.","D":"Citologia Semestral."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-45351","number":"45351","sourceNumber":"45351","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A presença de epitélio acetobranco à colposcopia é devida à:","options":{"A":"coagulação de proteínas do núcleo e citoplasma.","B":"circulação de capilares a blocos celulares.","C":"coagulação de glicogênio.","D":"dilatação de capilares.","E":"leucoplasia."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-30847","number":"30847","sourceNumber":"30847","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher 22 anos realiza a primeira citologia oncótica cérvico-vaginal. Ela tem vida sexual\nhá 5 anos e relata 3 parceiros sexuais\nnesse período. O exame ginecológico é normal, entretanto o\nresultado da citologia revela lesão intraepitelial escamosa de alto grau, identificada como NIC II,\nsem células endocervicais no esfregaço. A conduta mais apropriada para o seguimento dessa\npaciente é:","options":{"A":"Realizar conização cervical.","B":"Repetir a citologia oncótica para obter amostragem de células endocervicais.","C":"Realizar a pesquisa de HPV por método de biologia molecular.","D":"Estimular o uso de condom e repetir a citologia em 4 meses.","E":"Realizar colposcopia e biópsia dirigida."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-32543","number":"32543","sourceNumber":"32543","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Quais das afirmações a seguir sobre hiperplasia endometrial é verdadeira?","options":{"A":"Hiperplasia endometrial resulta de estimulação androgênica prolongada do endométrio.","B":"Hiperplasia endometrial é caracterizada pela proliferação de glândulas, mas não de estroma.","C":"Hiperplasia endometrial raramente sofre regressão espontânea.","D":"Atipia citológica é uma característica importante na determinação do risco de progressão para\ncarcinoma.","E":"O tempo necessário para uma hiperplasia endometrial progredir até um carcinoma é inferior a\num ano."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-32545","number":"32545","sourceNumber":"32545","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Qual dos seguintes tipos de câncer vulvar ocorre mais comumente?","options":{"A":"Célula basal.","B":"Adenocarcinoma.","C":"Melanoma.","D":"Epidermoide.","E":"Paget."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-32548","number":"32548","sourceNumber":"32548","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Os esfregaços de Papanicolaou obtidos do colo uterino durante uma gestação normal:","options":{"A":"Devem ser parte de um acompanhamento obstétrico de rotina.","B":"Estão indicados apenas nas pacientes com riscos elevados para infecções.","C":"São difíceis de interpretar em decorrência das modificações próprias da gravidez.","D":"São um bom substituto para exames de pesquisa de doenças sexualmente transmissíveis.","E":"Podem facilmente induzir ao abortamento, ao ensejo da colheita de Papanicolaou."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-36991","number":"36991","sourceNumber":"36991","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher de 22 anos de idade, em atendimento na unidade básica de saúde,\napresenta o resultado de exame da citologia\noncótica cervicovaginal que mostra células atípicas\ncompatíveis com infecção pelo HPV e lesão intraepitelial de baixo grau com coilócitos. Qual a\nconduta mais adequada?","options":{"A":"Cirurgia de Alta Frequência (CAF), se lesão\nectocervical.","B":"Aplicação tópica de 5-fluorouracil a 5%.","C":"Repetir citologia.","D":"Eletrocauterização do colo uterino."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-36995","number":"36995","sourceNumber":"36995","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma senhora de 47 anos, solteira, G4 P4, fumante, não faz exames preventivos há\ncerca de 6 anos. Saiu recentemente de seu terceiro relacionamento. Vem queixando-se de\nsinusiorragia há 4 meses. Qual a hipótese diagnóstica mais provável?","options":{"A":"Câncer de colo uterino","B":"Pólipo endometrial.","C":"Ectopia cervical.","D":"Mioma uterino."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-37457","number":"37457","sourceNumber":"37457","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Carmen de Sousa de 30 anos de idade compareceu ao consultório médico conduzindo\nlaudo histopatológico compatível com NIC III.\nRelata ser mãe de quatro filhos de pais diferentes,\nnão desejando mais procriar. Assinale a conduta correta:","options":{"A":"Acompanhar cuidadosamente com citologia oncótica e colposcopia de três em três meses.","B":"Submetê-la a uma conização do colo do útero.","C":"Efetuar nova biópsia dirigida para confirmação ou não do diagnóstico.","D":"Realizar histerectomia abdominal.","E":"Realizar pan-histerectomia vaginal."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-37459","number":"37459","sourceNumber":"37459","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O adenocarcinoma do endométrio estádio IIB significa que há:","options":{"A":"Invasão de metade do miométrio.","B":"Invasão de mais da metade do miométrio.","C":"Citologia do líquido peritonial positiva para células\nneoplásicas.","D":"Infiltração de todo o endométrio.","E":"Comprometimento do estroma endocervical."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-37472","number":"37472","sourceNumber":"37472","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Dona Hilda de 60 anos de idade, viúva, aposentada, marcou consulta com seu\nginecologista devido a um sangramento irregular e em pequena quantidade que apareceu há 5\nmeses. Refere última menstruação há cinco anos. Refere disúria. Ao exame ginecológico\nconstatou-se dor à inserção do espéculo, mucosa vaginal seca e eritematosa. Em relação às\ncausas de sangramento pós-menopausa, podemos afirmar que:","options":{"A":"As causas mais comuns são hiperplasia e carcinoma endometriais.","B":"No caso de D. Hilda pode-se tratar apenas com\n\nestrógenos tópicos por 3 semanas com intervalo livre de uma semana.","C":"Em casos de hiperplasias endometriais com atipias, o tratamento ideal é terapia com\nprogestogênios e\n\nhisterectomia subtotal.","D":"Os fatores de risco de CA de endométrio são menarca tardia, menopausa precoce,\nmultiparidade e obesidade.","E":"A causa deste sangramento pode ser um mioma uterino submucoso, comum nessa faixa etária."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-24346","number":"24346","sourceNumber":"24346","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao estadiamento dos tumores de vagina segundo a FIGO, o tumor maligno\nde vagina envolvendo tecido paravaginal, sem\napresentar extensão à parede pélvica encontra-se\nno estádio:","options":{"A":"Zero;","B":"I;","C":"II;","D":"III."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-9089","number":"9089","sourceNumber":"9089","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considerando o câncer de colo uterino, quais as diretrizes do Ministério da Saúde para\nrastreamento populacional?","options":{"A":"A citologia deve ser colhida a cada 2 anos após 3 exames consecutivos anuais negativos, em\nmulheres de 25 a 60 anos de idade.","B":"A citologia deve ser colhida a cada 3 anos após 2 exames consecutivos anuais negativos em\nmulheres de 20 a 70 anos de idade.","C":"A citologia deve ser colhida a cada 3 anos após 2 exames consecutivos anuais negativos em\nmulheres de 25 a 60 anos de idade.","D":"A citologia deve ser colhida a cada 2 anos após 2 exames consecutivos anuais negativos em\nmulheres de 20 a 65 anos de idade."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-7277","number":"7277","sourceNumber":"7277","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em uma mulher com biópsia de colo uterino (pequeno fragmento), realizada às cegas\n(sem colposcopia), com invasão de 2 mm, qual a\nmelhor conduta seguinte?","options":{"A":"histerectomia abdominal + anexectomia bilateral.","B":"histerectomia radical.","C":"conização.","D":"histerectomia vaginal + anexectomia bilateral.","E":"histerectomia vaginal."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-9139","number":"9139","sourceNumber":"9139","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao carcinoma de vulva, a cirurgia é o recurso terapêutico mais efetivo; ela\nserá realizada de acordo com a extensão do\ntumor, grau de invasão e condições pré-operatórias da\npaciente. Assim sendo, no estádio II da doença, indica-se:","options":{"A":"Vulvectomia radical com linfadenectomia inguinal bilateral, podendo ser necessária a remoção\nda porção distal da uretra, vagina ou ânus\ne/ou exenteração pélvica","B":"Exérese ampla da lesão e quimioterapia adjuvante após a cirurgia","C":"Vulvectomia radical com linfadenectomia inguinal bilateral","D":"Ressecção ampla, com margens de 3 cm ou hemivulvectomia com linfadenectomia inguinal\nunilateral"},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-17871","number":"17871","sourceNumber":"17871","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Onde se localiza o linfonodo de Cloquet?","options":{"A":"Área inguinal superficial","B":"Área femoral superficial","C":"Área inguinal profunda","D":"Área ilíaca externa","E":"Área femoral profunda"},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-17872","number":"17872","sourceNumber":"17872","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Qual dos seguintes tipos de câncer de vulva ocorre mais comumente?","options":{"A":"Melanoma","B":"Adenocarcinoma","C":"Tumor de célula basal","D":"Tumor de Paget","E":"Tumor epidermoide"},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-17873","number":"17873","sourceNumber":"17873","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em um exame colposcópico, o achado mais indicativo de carcinoma de colo invasivo é:","options":{"A":"leucoplasia","B":"mosaico","C":"lesão puntiforme","D":"epitélio branco","E":"vaso sanguíneo atípico"},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-17878","number":"17878","sourceNumber":"17878","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O tratamento de eleição do sarcoma uterino é, primariamente:","options":{"A":"terapia hormonal","B":"quimioterapia","C":"radioterapia","D":"cirurgia","E":"terapia quimio-hormonal"},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-17879","number":"17879","sourceNumber":"17879","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Um tumor vaginal maligno de crianças, que se apresenta clinicamente como massa\nvolumosa em cacho de uvas, é sugestivo de:","options":{"A":"coriocarcinoma","B":"adenocarcinoma","C":"sarcoma botrioide","D":"carcinoma de células escamosas","E":"vaginite enfisematosa"},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-16025","number":"16025","sourceNumber":"16025","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher de 32 anos apresenta menstruações irregulares e infertilidade. A biópsia\nde endométrio evidencia hiperplasia complexa com\natipia citológica mínima. A melhor conduta para\nesta paciente é:","options":{"A":"observação.","B":"indução da ovulação com clomifeno.","C":"tratamento cíclico com pílula combinada.","D":"histerectomia com anexectomia.","E":"tratamento contínuo com progestagênio."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-16028","number":"16028","sourceNumber":"16028","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Os subtipos mais comuns de papilomavírus humano (HPV), associados a verrugas\ngenitais, são:","options":{"A":"HPV-1 e 2.","B":"HPV- 4 e 7.","C":"HPV- 6 e 11.","D":"HPV- 18 e 24.","E":"HPV- 22 e 23."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-365570","number":"365570","sourceNumber":"365570","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A citologia cervicovaginal é um método bastante eficaz na detecção de lesões\nprecursoras de câncer de colo uterino. De acordo com as diretrizes do Ministério da Saúde,\nassinale a alternativa correta.","options":{"A":"As pacientes abaixo de 25 anos de idade devem iniciar o rastreio com citologia anual tão logo se\ninicie a atividade sexual.","B":"As pacientes com células escamosas de significado indeterminado (ASC-US) devem ser\nencaminhadas para realização de colposcopia.","C":"A presença de alterações citopáticas sugestivas de HPV deve ser tratada com cauterização do\ncolo uterino.","D":"As pacientes abaixo de 25 anos de idade que apresentam lesões escamosas de baixo grau\n(LSIL) devem repetir o exame de citologia cervicovaginal em três anos."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-349724","number":"349724","sourceNumber":"349724","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 56 anos procura atendimento por um quadro de prurido vulvar crônico, com\npiora no período noturno. É menopausada há 5 anos e nega terapia de reposição hormonal.\n\nDurante a inspeção, apresenta vulva com área de pápulas atróficas branquicentas, simétrica,\nregressão dos pequenos lábios e encobrimento do clitóris. Após a avaliação, o médico\nginecologista indicou tratamento para líquen escleroso, sendo a melhor medicação para essa\npatologia","options":{"A":"nistatina por 30 dias em região vulvar.","B":"prednisona 20 mg via oral por 30 dias. Após, iniciar a redução do corticoide progressivamente.","C":"itraconazol associado à pomada de clindamicina gel por 20 dias consecutivos.","D":"propionato de clobetasol a 0,05.","E":"neomicina + bacitracina zincica associadas a anti-histamínico de primeira geração."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-305328","number":"305328","sourceNumber":"305328","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher, 35 anos, refere última ida ao ginecologista há 5 anos, com exames\ncitopatológicos cervicovaginais normais. Após\ncolposcopia, recebeu um resultado de citopatológico\nindicando a presença de células escamosas atípicas de significância indeterminada (ASC-US).\n\nAssinale a alternativa que corresponde à conduta adequada para essa paciente.","options":{"A":"Histerectomia de Wertheim-Meigs.","B":"Conização.","C":"Repetir colpocitologia em 6 meses.","D":"Repetir colpocitologia em 12 meses.","E":"Realizar colposcopia com biópsia."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-261281","number":"261281","sourceNumber":"261281","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente de 56 anos de idade comparece à consulta com o ginecologista para\nrevisão. Refere realizar exames ginecológicos\nde rastreamento, conforme orientação do médico\nclínico geral que a atendia até então. Informa que faz uso de cálcio, vitamina D e sinvastatina, por\nhistórico de osteoporose identificada em densitometria óssea (DMO) prévia, e dislipidemia.\n\nRecentemente recebeu diagnóstico de nefrolitíase após crise de dor renal. Relata ser tabagista e\netilista desde os 23 anos de idade, e o peso atual dela é 54 Kg. Teve dois partos vaginais prévios,\nmenarca aos 12 anos e menopausa aos 38 anos de idade. Nega ter realizado terapia de reposição\nhormonal. Considerando esse caso clínico e com base nas recomendações do Ministério da Saúde\npara exames de rastreamento e nos conhecimentos médicos correlatos, julgue o item a seguir. A\npaciente poderia realizar o exame citopatológico do colo do útero a cada três anos, caso tenha dois\nresultados anuais consecutivos negativos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-274416","number":"274416","sourceNumber":"274416","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer do corpo do útero pode ter origem em diferentes partes do órgão. O tipo mais\ncomum se origina no endométrio e o menos comum é o que se origina na musculatura e no tecido\nde sustentação do órgão. Em relação ao câncer de endométrio, assinale a alternativa correta.","options":{"A":"A curetagem uterina é o padrão-ouro para diagnóstico.","B":"Tem como fatores de risco obesidade, diabetes e ciclos anovulatórios.","C":"É a principal causa de sangramento na pós-menopausa.","D":"Pacientes com fator de risco para câncer do endométrio não devem ser rastreadas se\nassintomáticas.","E":"A tomografia computadorizada pode ser útil no rastreamento de pacientes obesas."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-274417","number":"274417","sourceNumber":"274417","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Sobre o rastreio do câncer de colo de útero, assinale a alternativa que condiz com as\ndiretrizes atuais.","options":{"A":"A captura híbrida apresenta índices superiores em relação à citologia.","B":"É um exame com alto valor preditivo negativo.","C":"Podem ser excluídas do rastreamento pacientes histerectomizadas.","D":"É recomendado a partir de 25 anos para mulheres com atividade sexual.","E":"Com a introdução das vacinas, o rastreio tende a diminuir."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-261296","number":"261296","sourceNumber":"261296","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente de 36 anos de idade foi atendida em primeira consulta com equipe de\noncologia ginecológica, em abril de 2019, com queixa de sinusiorragia. Foi diagnosticada com\nadenocarcinoma de colo do útero, estágio clínico IIB. Indicou-se tratamento, porém a paciente não\ndesejou realizá-lo naquele momento, retornando um ano depois, grávida (G6P4C1), com idade\ngestacional de 30 semanas e 3 dias, referindo dificuldade para deambular e dor no quadril à\nesquerda. Foram, então, identificadas metástase óssea e fratura patológica, e re-estadiada para\nestágio clínico IVB. Após avaliações iniciais, a paciente definiu que desejava manter a gestação.\n\nCom base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A\npaciente não poderá realizar nenhum tipo de tratamento com radioterapia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-261297","number":"261297","sourceNumber":"261297","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente de 36 anos de idade foi atendida em primeira consulta com equipe de\noncologia ginecológica, em abril de 2019, com queixa de sinusiorragia. Foi diagnosticada com\nadenocarcinoma de colo do útero, estágio clínico IIB. Indicou-se tratamento, porém a paciente não\ndesejou realizá-lo naquele momento, retornando um ano depois, grávida (G6P4C1), com idade\ngestacional de 30 semanas e 3 dias, referindo dificuldade para deambular e dor no quadril à\nesquerda. Foram, então, identificadas metástase óssea e fratura patológica, e re-estadiada para\nestágio clínico IVB. Após avaliações iniciais, a paciente definiu que desejava manter a gestação.\n\nCom base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A\npaciente poderá realizar tratamento com quimioterapia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-261298","number":"261298","sourceNumber":"261298","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente de 36 anos de idade foi atendida em primeira consulta com equipe de\noncologia ginecológica, em abril de 2019, com queixa de sinusiorragia. Foi diagnosticada com\nadenocarcinoma de colo do útero, estágio clínico IIB. Indicou-se tratamento, porém a paciente não\ndesejou realizá-lo naquele momento, retornando um ano depois, grávida (G6P4C1), com idade\ngestacional de 30 semanas e 3 dias, referindo dificuldade para deambular e dor no quadril à\nesquerda. Foram, então, identificadas metástase óssea e fratura patológica, e re-estadiada para\nestágio clínico IVB. Após avaliações iniciais, a paciente definiu que desejava manter a gestação.\n\nCom base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Se\nindicado, o tratamento proposto será paliativo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-261299","number":"261299","sourceNumber":"261299","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente de 36 anos de idade foi atendida em primeira consulta com equipe de\noncologia ginecológica, em abril de 2019, com queixa de sinusiorragia. Foi diagnosticada com\nadenocarcinoma de colo do útero, estágio clínico IIB. Indicou-se tratamento, porém a paciente não\ndesejou realizá-lo naquele momento, retornando um ano depois, grávida (G6P4C1), com idade\ngestacional de 30 semanas e 3 dias, referindo dificuldade para deambular e dor no quadril à\nesquerda. Foram, então, identificadas metástase óssea e fratura patológica, e re-estadiada para\nestágio clínico IVB. Após avaliações iniciais, a paciente definiu que desejava manter a gestação.\n\nCom base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A\npaciente não possui indicação de tratamento cirúrgico para o câncer de colo do útero.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-265582","number":"265582","sourceNumber":"265582","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente de 42 anos de idade, com queixa de sangramento transvaginal, procurou\nauxílio médico para avaliação. Durante a investigação pelo ginecologista, verificou-se lesão\nulcerada do colo uterino, sangrante, semifixa ao toque vaginal. Ao toque retal, havia retração e\ninvasão parametrial bilateral, mas sem chegada aos planos ósseos. O estadiamento radiológico\nnão determinou presença de doença metastática a distância. O resultado da biópsia do colo uterino\nveio compatível com um carcinoma espinocelular. No que se refere a esse caso clínico, tendo em\nvista as neoplasias de colo uterino e os conhecimentos médicos correlatos, julgue o item a seguir.\nSabe-se que a grande maioria dos casos de carcinoma de colo uterino está relacionada à\nexposição ao papilomavírus humano (HPV). Alguns dos subtipos mais comumente associados ao\ncarcinoma de colo uterino são os subtipos 6, 11, 40, 42, 43 e 54.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-250146","number":"250146","sourceNumber":"250146","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer de colo uterino é o câncer ginecológico mais comum nas mulheres. No que\ndiz respeito a essa temática, julgue o item a seguir. O local típico de surgimento do carcinoma de\ncélulas escamosas do colo uterino é a junção escamocolunar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-250147","number":"250147","sourceNumber":"250147","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer de colo uterino é o câncer ginecológico mais comum nas mulheres. No que\ndiz respeito a essa temática, julgue o item a\nseguir. O adenocarcinoma surge das células colunares\nprodutoras de muco da endocérvice.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-239324","number":"239324","sourceNumber":"239324","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente de 50 anos de idade vai à consulta em UBS com queixa de corrimento\nvaginal acinzentado e com odor fétido na última\nsemana. Refere também que gostaria de realizar\ncheck-up, pois não se consulta com médico há mais de 10 anos e está preocupada, pois a própria\nmãe foi diagnosticada com câncer de mama quando tinha 68 anos de idade. História médica\npregressa: G6P6A0, diagnóstico prévio de sífilis tratada recentemente e coitarca aos 14 anos de\nidade. Tabagista de um maço de cigarro ao dia desde os 15 anos de idade. Considerando esse\ncaso clínico e os conhecimentos médicos relacionados à saúde da mulher, julgue o item a seguir.\nDeverá ser solicitado o exame colpocitológico para rastreamento de neoplasia de colo uterino, cujo\nprincipal fator de risco são as infecções do HPV, particularmente os subtipos 16 e 18.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-239325","number":"239325","sourceNumber":"239325","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente de 50 anos de idade vai a consulta em UBS com queixa de corrimento\nvaginal acinzentado e com odor fétido na última\nsemana. Refere também que gostaria de realizar\ncheck-up, pois não se consulta com médico há mais de 10 anos e está preocupada, pois a própria\nmãe foi diagnosticada com câncer de mama quando tinha 68 anos de idade. História médica\npregressa: G6P6A0, diagnóstico prévio de sífilis tratada recentemente e coitarca aos 14 anos de\nidade. Tabagista de um maço de cigarro ao dia desde os 15 anos de idade. Considerando esse\ncaso clínico e os conhecimentos médicos relacionados à saúde da mulher, julgue o item a seguir. O\nfato de ter apresentado quadro de sífilis anteriormente não eleva o risco de a paciente vir a\ndesenvolver câncer de colo uterino.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-239332","number":"239332","sourceNumber":"239332","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considere uma paciente de 88 anos de idade, hipertensa, diabética tipo 2, em uso de\ninsulina e com quadro de insuficiência cardíaca NYHA classe III. Ela foi diagnosticada com câncer\nde colo uterino estágio IIIB pela classificação da FIGO (2009). Na última ecografia de aparelho\nurinário, foi visualizada hidronefrose moderada à direita. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, julgue o item a seguir. A paciente pode ser tratada com\nquimiorradioterapia primária.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-239333","number":"239333","sourceNumber":"239333","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considere uma paciente de 88 anos de idade, hipertensa, diabética tipo 2, em uso de\ninsulina e com quadro de insuficiência cardíaca NYHA classe III. Ela foi diagnosticada com câncer\nde colo uterino estágio IIIB pela classificação da FIGO (2009). Na última ecografia de aparelho\nurinário, foi visualizada hidronefrose moderada à direita. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, julgue o item a seguir. Os achados de hidronefrose ou rim não\nfuncionante devem ser incluídos no estadiamento no câncer de colo uterino, quando excluídas\noutras causas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-239334","number":"239334","sourceNumber":"239334","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considere um paciente de 88 anos de idade, hipertensa, diabética tipo 2, em uso de\ninsulina e com quadro de insuficiência cardíaca NYHA classe III. Ela foi diagnosticada com câncer\nde colo uterino estágio IIIB pela classificação da FIGO (2009). Na última ecografia de aparelho\nurinário, foi visualizada hidronefrose moderada à direita. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, julgue o item a seguir. Considerando o status funcional da\npaciente, as comorbidades envolvidas e o tratamento proposto para a neoplastia em questão,\ndeve-se introduzir a ideia de cuidados paliativos com familiares e paciente, visando, entre outros,\nao bem-estar, apesar da evolução da doença, e ao manejo álgico adequado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-255763","number":"255763","sourceNumber":"255763","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente de 44 anos de idade procura a equipe da Estratégia Saúde da Família\npara solicitar exames de rastreamento, pois\nestá preocupada com o fato de que vai iniciar atividade\nfísica (corrida). Ela afirmou que não tem doenças prévias e não usa medicamentos contínuos. Nega\nhistória de neoplasias na família e também tabagismo. Gesta 2 para 2, cesáreas 0 e aborto 0. PA =\n120 mmHg x 80 mmHg; FC = 70 bpm; FR = 14 irpm; SpO2 = 98%; peso = 64 kg; estatura = 1,68; e\nIMC = 22,7. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a\nseguir. Conforme as recomendações atuais do Ministério da Saúde, deverá ser realizada coleta do\ncitopatológico do colo uterino dessa paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-179183","number":"179183","sourceNumber":"179183","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A realização do exame citopatológico continua sendo a estratégia mais amplamente\nadotada para rastreamento do câncer de colo\nuterino. Com relação aos aspectos que devem ser\nconsiderados para realização do exame Papanicolau, assinale a alternativa correta.","options":{"A":"Como política de saúde pública, deve-se realizar o exame na população-alvo anualmente.","B":"Em adolescentes e mulheres jovens com lesões precursoras do câncer de colo de útero, a\nconduta deve ser mais agressiva.","C":"O rastreamento em mulheres com menos de 25 anos de idade não tem impacto na redução da\nincidência ou mortalidade por câncer de colo de útero.","D":"É consenso que mesmo mulheres que nunca tiveram relação sexual correm risco de\ndesenvolver câncer de colo de útero.","E":"Mulheres na pós-menopausa devem ser rastreadas com mais frequência devido ao maior risco\nde desenvolvimento desse câncer."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-177629","number":"177629","sourceNumber":"177629","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"No contexto da Atenção Primária à Saúde, eventualmente, encontram-se prontuários\nque relatam todo o curso de vida de certo\npaciente, desde o período gestacional até a idade adulta,\nincluindo-se o período reprodutivo. Suponha que o M.S.F., atualmente com 28 anos de idade, foi\nacompanhada, no posto de saúde, durante toda a sua vida, desde a própria gestação da qual foi\nfruto. Ao longo de sua vida, várias estratégias de prevenção e programas de rastreamento foram\nefetuados e, eventualmente, continuarão sendo utilizados ao longo de seu envelhecimento. A\npaciente é sexualmente ativa, solteira, negra, com dois filhos (2 e 4 anos de idade), secretária,\nnão\ntabagista, não etilista, fisicamente ativa, com IMC = 22,5 e PA = 125 mmHg x 70 mmHg na última\nconsulta. A respeito dessas estratégias e desses programas e considerando as recomendações\ndos Cadernos de Atenção Básica do Ministério da Saúde, julgue o item a seguir. Atualmente a\npaciente encontra-se no público alvo do rastreamento do câncer do colo de útero por meio do\nexame de Papanicolau.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-152152","number":"152152","sourceNumber":"152152","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 28 anos de idade, nuligesta, casada, ciclos menstruais regulares, nega uso\nde métodos anticonceptivos, pois deseja\ngestar. Foi encaminhada ao serviço de patologia cervical;\ntrouxe resultado de citopatológico apresentando LIEAG e colposcopia com biópsia evidenciando\nNIC III. A respeito desse caso clínico, julgue o item a seguir: deve-se realizar histerectomia total\nsem anexectomia.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-152161","number":"152161","sourceNumber":"152161","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 28 anos de idade, nuligesta, casada, ciclos menstruais regulares, nega uso\nde métodos anticonceptivos, pois deseja\ngestar. Foi encaminhada ao serviço de patologia cervical;\ntrouxe resultado de citopatológico apresentando LIEAG e colposcopia com biópsia evidenciando\nNIC III. A respeito desse caso clínico, julgue o item a seguir: deve-se realizar conização do colo\ndo\nútero.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-152058","number":"152058","sourceNumber":"152058","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 28 anos de idade, nuligesta, casada, ciclos menstruais regulares, nega uso\nde métodos anticonceptivos, pois deseja\ngestar. Foi encaminhada ao serviço de patologia cervical:\ntrouxe resultado de citopatológico apresentando LIEAG e colposcopia com biópsia evidenciando\nNIC III. A respeito desse caso clínico, julgue o item a seguir: deve-se realizar nova colposcopia\ncom\nbiópsia em seis meses para definir a conduta, visto que uma paciente jovem com desejo de\nengravidar não está indicada a realizar cirurgia neste momento.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-131837","number":"131837","sourceNumber":"131837","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considere hipoteticamente que uma paciente de 19 anos de idade, nuligesta,\nassintomática, com vida sexual ativa desde os 16\nanos, após realização de seu primeiro exame\ncitopatológico cervicovaginal, apresentou resultado compatível com lesões intraepiteliais\nescamosas cervicais de baixo grau (LSIL), conforme o Sistema Bethesda. Nesse caso, a conduta\nmais indicada é a seguinte:","options":{"A":"Repetir o exame citopatológico a cada 12 meses, sendo referida para colposcopia somente se\nhouver persistência diagnóstico citopatológico por 24 meses.","B":"Encaminhamento imediato para colposcopia e biópsia.","C":"Realização de captura híbrida para detecção do DNA do HPV e tipagem (baixo ou alto risco).","D":"Exérese da zona de transformação por meio de Large Loop Excision of the Cervical\nTransformation Zone (LLETZ).","E":"Conização a laser."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-135019","number":"135019","sourceNumber":"135019","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Julgue o próximo item, com relação aos distúrbios pré-malignos e malignos do trato\ngenital feminino e da mama. São fortes\nevidências de infecção pelo vírus do HPV laudo de exame\ncolpocitológico evidenciando alterações nas células escamosas compatíveis com vacuolização\ncitoplasmática, aumento volumétrico, irregularidade e hipercromasia nuclear.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-105564","number":"105564","sourceNumber":"105564","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente de 54 anos de idade compareceu à consulta de rotina com o\nginecologista. Referiu perda de urina a médios\nesforços e sangramento vaginal há duas semanas.\nAntecedentes ginecológicos: menarca aos doze anos, menopausa aos 51 anos de idade,\nG1PN1A0, sem antecedentes familiares de câncer ginecológico. Foram solicitados exames com os\nseguintes resultados: Ecografia transvaginal: útero em AVF com volume de 80 cm³, endométrio de\n10 mm, ovários atróficos; Mamografia: BIRADS 2; Estudo urodinâmico: incontinência urinária de\nesforço com defeito esfincteriano. Com relação ao achado endometrial na ecografia transvaginal, o\nexame padrão ouro para investigação é a:","options":{"A":"curetagem uterina semiótica.","B":"videolaparoscopia.","C":"histeroscopia com biópsia.","D":"curetagem com cureta de Novak.","E":"tomografia computadorizada de pelve com contraste."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-108212","number":"108212","sourceNumber":"108212","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com referência a oncologia ginecológica e mamária julgue o item a seguir. Os cânceres\ninvasivos de vulva que acometem principalmente mulheres portadoras do HPV, são multifocais e\napresentam lesões bilaterais mal delimitadas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-108205","number":"108205","sourceNumber":"108205","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com referência à oncologia ginecológica e mamária, julgue o item a seguir. Mulheres\nna pós-menopausa sem sangramento uterino, que\napresentam histiócitos no esfregaço de citologia\noncótica cervical, têm maior probabilidade de desenvolver câncer endometrial.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-82104","number":"82104","sourceNumber":"82104","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considerando as políticas públicas brasileiras voltadas à saúde da mulher, julgue o item\nsubsecutivo. O rastreamento do câncer do colo do útero nas gestantes é uma medida importante,\npodendo ser feito em qualquer período da gestação, mas, preferencialmente, até o sétimo mês.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-64279","number":"64279","sourceNumber":"64279","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Acerca de oncologia ginecológica, julgue o item subsequente. A quimioprofilaxia com\ntamoxifeno é um relevante fator de proteção para as pacientes com elevado risco de desenvolver\ncâncer do endométrio.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-49163","number":"49163","sourceNumber":"49163","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A respeito de ginecologia, julgue o item seguinte. Atualmente, existem duas vacinas\npara HPV: uma quadrivalente, que imuniza a\npaciente contra os vírus de HPV 16, 18, 6 e 11, e\noutra, bivalente, que imuniza a paciente contra o vírus HPV 16 e 18.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-45724","number":"45724","sourceNumber":"45724","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente de 34 anos de idade, solteira, comparece à consulta de rotina no\nginecologista sem queixas, com última Colpocitologia Oncótica (CCO), realizada há três anos,\ndemonstrando ASCUS. Ciclos menstruais regulares, G2P2 (N2C0) A0, exame clínico normal e é\ncolhida nova CCO. Após 45 dias, a CCO apresenta o seguinte laudo: \"Amostra satisfatória,\nrepresentada por células escamosas. Ausência de representação dos epitélios glandular e\nmetaplásico. Padrão citolítico, inflamatório leve. Negativo para malignidade na amostra\nrepresentada\". A conduta adequada diante desse resultado citológico é:","options":{"A":"acompanhamento de rotina com nova CCO em um ano.","B":"repetição de CCO em seis meses.","C":"repetição de CCO imediatamente.","D":"tratamento tópico e oral para vulvovaginite.","E":"colposcopia com biópsia dirigida."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-52611","number":"52611","sourceNumber":"52611","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Julgue o item a seguir, acerca das recomendações constantes nas Diretrizes Brasileiras\npara o Rastreamento do Câncer do Colo do\nÚtero para mulheres sem história prévia de lesões\nprecursoras do câncer do colo uterino. O método de rastreamento do câncer do colo útero e de\nsuas lesões precursoras é o exame citopatológico. Após dois exames negativos com intervalo\nanual, o intervalo entre os exames deverá ser de três anos.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-52616","number":"52616","sourceNumber":"52616","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Julgue o item a seguir, acerca das recomendações constantes nas Diretrizes Brasileiras\npara o Rastreamento do Câncer do Colo do\nÚtero para mulheres sem história prévia de lesões\nprecursoras do câncer do colo uterino. Mulheres com cinquenta ou mais anos de idade que nunca\nrealizaram o exame citopatológico devem ser submetidas a dois exames, com intervalo de um a\ntrês anos. Se o resultado de ambos for negativo, essas mulheres poderão ser dispensadas de\nexames adicionais.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-37957","number":"37957","sourceNumber":"37957","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com referência a infecções geniturinárias e doença sexualmente transmissível, julgue o\nitem. Os principais tipos de papilomavírus humano (HPV) relacionados aos condilomas, em mais de\n90% dos casos, são o 6 e o 11. O HPV produz infecção em que os genes virais estimulam a mitose\nda célula infectada e provocam lesões benignas, não apresentando potencial oncogênico.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-32166","number":"32166","sourceNumber":"32166","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente com 57 anos de idade, solteira, aposentada, chega ao pronto-socorro\ncom sangramento uterino anormal iniciado há um dia.\nRelata ser virgem e menopausada há três\nanos. A sua última consulta ginecológica foi há três anos, com rotina de exames ginecológicos\nnormais. Usa apenas hipoglicemiante oral, porém de forma irregular. Ao exame clínico,\nconstatou-se bom estado geral; pressão arterial de 130/80 mmHg; pulso de 88 bpm; aparelho\ncardiovascular: bulhas normofonéticas, ritmo cardíaco regular em 2T; aparelho respiratório:\nmurmúrio vesicular fisiológico, ausência de ruídos adventícios; abdome: plano, flácido, sem\n\nvisceromegalias. Ao exame ginecológico, verificou-se genitália externa sem alterações e presença\nde pequena quantidade de sangramento em\nabsorvente. Com base no caso clínico relatado no\ntexto, assinale a alternativa que apresenta o procedimento que o médico deve realizar, na\nemergência.","options":{"A":"Solicitar ultrassonografia transvaginal e fazer uma curetagem por aspiração para cessar o\nsangramento e, ao mesmo tempo, obter amostra para biópsia.","B":"Solicitar exames laboratoriais de emergência (bioquímica e urinálise) e ultrassonografia\npélvica.","C":"Internar a paciente e solicitar o pré-operatório imediatamente.","D":"Prescrever estrógeno-progestogênio por via oral.","E":"Prescrever vitamina K."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-32177","number":"32177","sourceNumber":"32177","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente com 57 anos de idade, solteira, aposentada, chega ao pronto socorro\ncom sangramento uterino anormal iniciado há um dia.\nRelata ser virgem e menopausada há três\nanos. A sua última consulta ginecológica foi há três anos, com rotina de exames ginecológicos\nnormais. Usa apenas hipoglicemiante oral; porém, de forma irregular. Ao exame clínico,\nconstatou-se bom estado geral; pressão arterial de 130/80 mmHg; pulso de 88 bpm; aparelho\ncardiovascular: bulhas normofonéticas, ritmo cardíaco regular em 2T; aparelho respiratório:\nmurmúrio vesicular fisiológico, ausência de ruídos adventícios; abdome: plano, flácido, sem\n\nvisceromegalias. Ao exame ginecológico, verificou-se genitália externa sem alterações e presença\nde pequena quantidade de sangramento em\nabsorvente. No caso clínico apresentado no texto,\nconsidere que o laudo da ultrassonografia pélvica tenha mostrado útero anteversofletido ou em\nanteversão (AVF), textura homogênea, espessura endometrial de 8 mm, com líquido intracavitário\nno seu interior e tamanho de 60 cm³. Ovário direito mede 1,3 cm³; e esquerdo, 1,5 cm³. Assinale a\nalternativa que apresenta a atitude que deve ser tomada pelo médico, diante desse laudo.","options":{"A":"Informar à paciente que o diagnóstico é a hiperplasia endometrial.","B":"Explicar à paciente que o motivo do sangramento é a hiperplasia endometrial e, por isso,\ninterná-la para resolução do caso.","C":"Solicitar o pré-operatório para histerectomia total e encaminhar a paciente ao ambulatório de\noncologia ginecológica.","D":"Internar a paciente e fazer de imediato a curetagem uterina.","E":"Explicar à paciente que o espessamento do endométrio necessita ser mais bem investigado com\na realização da histeroscopia, após exames\npré-operatórios."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-32167","number":"32167","sourceNumber":"32167","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Assinale a alternativa correta a respeito de doenças da vulva.","options":{"A":"O prurido é o sintoma mais comum do câncer de vulva em mulheres idosas. Quando a lesão é\nlocalizada nos grandes lábios, a drenagem linfática se faz ipsolateral.","B":"A úlcera em região vulvar pode ser uma Doença Sexualmente Transmissível (DST). Ao exame\nfísico de uma lesão que se mostra como única dolorosa de margem irregular e associada à\nadenopatia unilateral, tal fato é indicador de cancro sifilítico.","C":"O purido vulvar pode ser consequência de uma vulvovaginite, como tricomoníase. A\ntricomoníase causa um eritema vulvar devido à\nsecreção vaginal abundante, purulenta, de odor\nfétido ao teste do KOH 10% e secrceção de pH ácido ao estudo da fita de nitrazina.","D":"A presença de condiloma vulvar já caracteriza a presença de HPV, e não se faz necessária a\nrealização da vulvoscopia.","E":"O tratamento da infecção genital por HPV em grávidas dá-se apenas no final do segundo\ntrimestre, devido ao efeito doloroso\npós-tratamento causar aumento da contratilidade uterina."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-27550","number":"27550","sourceNumber":"27550","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O achado de lesão classificada como alto grau em exame colpocitológico tem como\nindicação:","options":{"A":"a realização de conização.","B":"repetição imediata do exame colpocitológico.","C":"criocauterização.","D":"aguardar 2 meses e repetir a colpocitologia.","E":"biópsia orientada por colposcopia."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-8605","number":"8605","sourceNumber":"8605","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 23 anos de idade em tratamento da infecção causada pelo papilomavírus\nhumano, cujo objetivo é:","options":{"A":"Erradicar lesões clínicas e intraepiteliais; eliminar o vírus.","B":"Erradicar lesões clínicas e intraepiteliais; prevenir o câncer.","C":"Evitar a transmissão sexual; erradicar lesões clínicas e intraepiteliais.","D":"Evitar a transmissão sexual; eliminar o vírus.","E":"Eliminar o vírus, prevenir o câncer."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-7526","number":"7526","sourceNumber":"7526","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Qual o tratamento adequado para uma mulher de 34 anos de idade, GII PII A0, vida\nsexual ativa, em uso de contraceptivo hormonal, com diagnóstico histopatológico de carcinoma\ncervical de células escamosas no estágio clínico lB1?","options":{"A":"Conização por ser paciente jovem.","B":"Histerectomia total do tipo II com preservação de ambos os ovários.","C":"Histerectomia total do tipo III com linfadenectomia pélvica e para-aórtica.","D":"Histerectomia total do tipo II com linfadenectomia pélvica.","E":"Radioterapia antes de qualquer técnica cirúrgica."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-334900","number":"334900","sourceNumber":"334900","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A colpocitologia oncótica, ou citologia vaginal, segue representando método importante\nno rastreio do câncer de colo uterino no\ncontexto do Sistema Único de Saúde. Quanto à\ninterpretação dos achados citológicos, assinale a alternativa correta.","options":{"A":"A história de radioterapia pélvica ou de quimioterapia prévia não gera alterações na\ninterpretação dos achados citológicos, uma\nvez que não leva a alterações celulares mimetizadoras\nde lesões intraepiteliais.","B":"A presença de dispositivo intrauterino não muda a interpretação dos exames, não necessitando\nde tal informação na solicitação do exame por\nnão alterar os achados da citologia.","C":"O achado de Ascus em paciente com idade inferior a 30 anos deve suscitar prontamente a\nsolicitação de exame colposcópico com biópsia.","D":"A coilocitose corresponde ao achado citológico de halo escurecido perinuclear, associado a\nalterações nucleares características, como diminuição do tamanho nuclear.","E":"É necessário ter atenção para que não haja confusão entre o achado de coilocitose e o acúmulo\nfisiológico de glicogênio intracelular. Nesse último caso, o núcleo permanecerá picnótico, como é\nesperado na célula superficial normal."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-343439","number":"343439","sourceNumber":"343439","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Dentre os tipos de sarcomas de partes moles, apresenta localização habitual no útero e\ntrato digestivo:","options":{"A":"Sarcoma de Kaposi.","B":"Fibrossarcoma.","C":"Leiomiossarcoma.","D":"Sarcoma sinovial."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-307124","number":"307124","sourceNumber":"307124","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considerando os métodos de rastreio de neoplasias do colo uterino e as condutas\nassociadas, assinale a alternativa correta. Alternativas:","options":{"A":"Os vírus do HPV mais prevalentes no câncer cervical são os das cepas 6 e 11.","B":"Nas pacientes com citologia cervicovaginal negativa para malignidade e teste molecular positivo\npara papilomavírus humano (HPV), está indicada\nbiópsia ampla (conização ou cirurgia de alta\nfrequência).","C":"A colposcopia é uma avaliação in situ do colo uterino por meio de um microscópio. Ela utiliza\nreagentes como formaldeido e ácido tricloroacético para avaliar lesões citopáticas do HPV.","D":"A citologia cervicovaginal consiste no método de avaliação das células cervicais descamadas,\ncom predição de lesões precursoras de neoplasia.","E":"Aproximadamente 70% da população adulta mundial, segundo o Instituto Nacional do Câncer\n(Inca), possui infecção pelo vírus do HPV e a\nmaioria é assintomática."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-273323","number":"273323","sourceNumber":"273323","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"São considerados fatores de risco para neoplasia endometrial, EXCETO:","options":{"A":"Obesidade","B":"Diabetes","C":"Hipertensão","D":"Gravidez"},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-268916","number":"268916","sourceNumber":"268916","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente de 35 anos de idade comparece ao ginecologista para realização de sua\nrotina ginecológica. É feita coleta de colpocitologia oncótica convencional (esfregaço celular em\nlâmina), que, após análise apropriada, revela resultado de atipias celulares de significado\nindeterminado, não se podendo excluir lesão de alto grau (ASC-H). Depois da avaliação do\nresultado em consultório, a paciente é encaminhada para a realização de colposcopia.\n\nConsiderando esse caso clínico e os temas correlatos, assinale a alternativa correta.","options":{"A":"Alguns dos achados colposcópicos maiores que indicam necessidade de biópsia são epitélio\nacetobranco denso, orifícios glandulares espessados, mosaico e pontilhado grosseiros, sinal da\nborda interna e sinal da crista.","B":"Assim como a citologia, a colposcopia apresenta menor sensibilidade e facilidade para a\ndetecção de alterações do epitélio escamoso do que alterações do epitélio glandular.","C":"Na colposcopia, as zonas de transformação (ZT) tipos 1 e 2 correspondem, respectivamente, à\npresença de junção escamocolunar (JEC) parcialmente e totalmente visível.","D":"Caso fosse realizado co-teste com PCR DNA-HPV, revelando detecção de HPV 16 e (ou) 18, a\npaciente deveria ser encaminhada diretamente para conização do colo uterino.","E":"Se fosse realizada biópsia durante colposcopia no caso clínico descrito, com resultado\nhistológico revelando lesão intraepitelial de\nbaixo grau (LSIL), a conduta seria nova cirurgia de alta\nfrequência imediata (CAF)."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-263380","number":"263380","sourceNumber":"263380","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher com 30 anos de idade assintomática, vem à Unidade Básica de Saúde\npara mostrar o resultado do exame de colo\nuterino. A paciente havia realizado a coleta há cerca de\n20 dias, como rotina ginecológica. No dia da coleta, nenhuma anormalidade foi detectada no exame\nespecular. O resultado da citologia oncótica revelou células escamosas atípicas de significado\nindeterminado, possivelmente não neoplásicas (ASC-US). Qual conduta médica deverá ser adotada\na partir desse resultado?","options":{"A":"Orientar a repetir a citologia oncótica em 12 meses.","B":"Orientar a repetir a citologia oncótica em 6 meses.","C":"Solicitar biópsia do colo uterino.","D":"Solicitar colposcopia."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-291522","number":"291522","sourceNumber":"291522","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma adolescente com 18 anos de idade, procura assistência primária para realizar o\nexame preventivo do câncer do colo uterino. Sexarca aos 17 anos, em uso de contraceptivo oral.\nDe acordo com as diretrizes brasileiras na prevenção do câncer de colo uterino, qual deve ser a\nconduta do agente de saúde?","options":{"A":"Fazer o exame clínico e ginecológico completo e coletar material para o exame citopatológico do\ncolo uterino.","B":"Coletar material para identificar o DNA-HPV (captura híbrida), se estiver disponível, pois é mais\nsensível que o exame citológico.","C":"Colher a história clínica e informar que não há necessidade de realizar o exame preventivo antes\nde completar 25 anos.","D":"Coletar material para citologia e caso tenha duas citologias normais com intervalo de 1 ano,\nfazer a coleta a cada 3 anos."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-291543","number":"291543","sourceNumber":"291543","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher, 28 anos de idade, professora, com 2 gestações anteriores, sendo um parto\nnormal e um aborto espontâneo\nanteriormente. Tem um filho de 7 anos de idade de outro\nrelacionamento. Há 2 anos está casada com homem de 35 anos, sem filhos. Ambos sem\nantecedentes patológicos significativos. Referem que há vários anos não procuram assistência com\na equipe de saúde. O exame físico do casal revelou como únicos achados positivos em relação à\nmulher: PA = 140 x 85 mmHg e índice de massa corporal de 30 Kg/m². Exame físico do homem foi\nnormal. Estavam em uso de preservativo e pílula combinada, mas interromperam há 2 semanas.\n\nVão em busca de orientação pré-concepcional. Nesta situação, está indicado(a)","options":{"A":"coleta de exame citopatológico cervicovaginal para prevenção do câncer de colo uterino.","B":"dosagem sérica de folato para prevenção de defeitos de fechamento do tubo neural.","C":"teste oral de tolerância à glicose para descartar diabetes mellitus prévio à gestação.","D":"dosagens hormonais de progesterona e estradiol para avaliação do ciclo menstrual e ovulação."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-244492","number":"244492","sourceNumber":"244492","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente com 34 semanas de gravidez, realizou exame citológico de colo uterino, que\nevidenciou lesão intraepitelial de alto grau (HSIL). Ela foi, então, encaminhada à unidade de\nreferência e realizou-se colposcopia com achados sugestivos de invasão. Optou-se pela realização\nde biópsia, com resultado de neoplasia intraepitelial cervical (NIC) 3. Quanto à melhor conduta\nnesse caso clínico, assinale a alternativa correta.","options":{"A":"Repetição da colposcopia em seis meses.","B":"Conização imediata.","C":"Repetição da colpocitologia em seis meses.","D":"Reavaliação 90 dias após o parto.","E":"Interrupção da gestação e tratamento imediato da lesão."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-230616","number":"230616","sourceNumber":"230616","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher de 45 anos procura ginecologista para tratar um corrimento marrom, fétido.\nPor habitar zona rural, ficou os últimos 10\nanos sem controles de rotina. Ao exame físico, é\nevidenciada massa friável ocupando colo uterino e região parametrial bilateral. Realizado urografia\nexcretora que demonstra rim esquerdo não funcionante. O estadiamento dessa neoplasia é:","options":{"A":"IIA.","B":"IIB.","C":"IIIA.","D":"IIIB."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-230618","number":"230618","sourceNumber":"230618","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"MELHOR método para investigação de hiperplasia endometrial:","options":{"A":"curetagem uterina.","B":"Aspiração Manual Intrauterina (AMIU).","C":"histerossonografia.","D":"histeroscopia."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-203021","number":"203021","sourceNumber":"203021","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considere uma paciente de 34 anos de idade, com colpocitologia evidenciando atipia\nde células escamosas, possivelmente não\nneoplásica. Não há lesões visíveis no exame especular.\nCom relação a esse caso clínico, é correto afirmar que a melhor conduta é:","options":{"A":"Proceder à biópsia do colo para definição diagnóstica.","B":"Manter o rastreio com citologia anual, já que esse laudo representa baixo risco para lesões\nneoplásicas.","C":"Realizar curetagem para avaliação da cavidade endometrial, já que essa alteração pode\nrepresentar lesão endometrial adjacente.","D":"Realizar colposcopia imediata para avaliação da necessidade de biópsia de colo.","E":"Repetir a citologia em seis meses e, caso se mantenha a alteração, encaminhar a paciente para\ncolposcopia."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-206087","number":"206087","sourceNumber":"206087","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente com câncer de colo uterino com lesão confinada ao colo menor que 4 cm,\ncorresponde ao estadiamento:","options":{"A":"IA.","B":"IA2.","C":"IB1.","D":"IB2."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-212026","number":"212026","sourceNumber":"212026","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Julgue o item, relativo à oncologia ginecológica. De acordo com as Diretrizes Brasileiras\npara o Rastreamento de Câncer de Colo do\nÚtero do Ministério da Saúde e do Instituto Nacional do\nCâncer, pode-se interromper o rastreamento colpocitológico em mulher com mais de sessenta e\nquatro anos de idade, desde que ela tenha pelo menos dois laudos com resultados negativos nos\núltimos cinco anos.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-212035","number":"212035","sourceNumber":"212035","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Julgue o item, relativo à oncologia ginecológica. O teste de Schiller será positivo se\nocorrer tingimento do colo uterino após a aplicação de solução iodada (lugol).","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-212018","number":"212018","sourceNumber":"212018","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Julgue o item, relativo à oncologia ginecológica. Entre os fatores de risco para o câncer\nendometrial estão a idade, a obesidade, a hereditariedade, o uso de contraceptivos hormonais orais\ncombinados e o antecedente de câncer de mama ou intestino.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-175155","number":"175155","sourceNumber":"175155","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Sobre o Colo Uterino, responda a alternativa correta:","options":{"A":"Células colunares são geralmente coletadas utilizando-se a escova cervical.","B":"Apresenta na sua porção externa (ectocérvice) um epitélio cilíndrico simples.","C":"A coleta do preventivo em base líquida melhora muito a acurácia do exame e os resultados finais\nsobre a mortalidade da população rastreada.","D":"O epitélio escamoso apresenta-se em camadas sobrepostas, impedindo o aparecimento de\nalterações pré-neoplásicas."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-175156","number":"175156","sourceNumber":"175156","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Sobre a lesão intra-epitelial de alto grau, descrita nos laudos de exame citológico de\ncolo uterino, assinale a alternativa correta:","options":{"A":"Seguindo a classificação mais antiga, essas lesões envolvem as Neoplasias Intraepiteliais\nCervicais (NIC) de grau I e II.","B":"Necessita de confirmação histológica mediante biópsia, preferencialmente guiada por\ncolposcopia.","C":"10 a 20% evoluem para carcinoma invasor.","D":"A colposcopia imediata com biópsia é a conduta mais aceita, podendo a paciente ser submetida\nà histerectomia, antes mesmo da realização da\ncolposcopia, caso a mesma já tenha prole\ncompleta."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-175153","number":"175153","sourceNumber":"175153","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Assinale a alternativa correta:","options":{"A":"O teste de Schiller negativo indica a presença de câncer de colo uterino.","B":"O toque retal é importante na avaliação dos paramétrios, por exemplo, na infiltração dos tumores\ndo colo uterino.","C":"O teste de Schiller positivo indica a presença de câncer de colo uterino.","D":"O epitélio cilíndrico endocervical pode sofrer metaplasia escamosa, que é lesão precursora do\ncâncer de colo."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-183921","number":"183921","sourceNumber":"183921","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com relação à prevenção e à atenção à doença oncológica, julgue o próximo item. O\ncâncer de mama em gestantes costuma apresentar estadiamento avançado no momento do\ndiagnóstico, em função das dificuldades de detecção pelo exame físico e pela semiologia armada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-183926","number":"183926","sourceNumber":"183926","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com relação à prevenção e à atenção à doença oncológica, julgue o próximo item. A\nmamografia é contraindicada durante a gravidez.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-168507","number":"168507","sourceNumber":"168507","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher com 27 anos de idade comparece à Unidade Básica de Saúde para\napresentar resultado de seu primeiro exame\npreventivo, cujo laudo citopatológico do colo uterino\ndemonstra \"células escamosas atípicas de significado indeterminado, possivelmente não\nneoplásicas\". Para o caso descrito, a conduta médica adequada, de acordo com as Diretrizes do\nMinistério da Saúde, é","options":{"A":"encaminhar a paciente para imediata colposcopia.","B":"encaminhar a paciente para exêrese da zona de transformação.","C":"solicitar a repetição do exame preventivo com novo exame citopatológico em um ano.","D":"solicitar a repetição do exame preventivo com novo exame citopatológico em 6 meses."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-154474","number":"154474","sourceNumber":"154474","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 29 anos retorna com resultado de citologia de colo uterino colhida na última\nconsulta, há 15 dias: epitélio escamoso, amostra satisfatória para avaliação, negativo para lesões\nneoplásicas e malignidade. A conduta médica é:","options":{"A":"Tranquilizar a paciente e repetir a citologia de colo uterino após 3 anos.","B":"Colher nova amostra nesta consulta e repetir a citologia de colo uterino.","C":"Obter material para avaliação histológica do colo uterino.","D":"Tranquilizar a paciente e reiterar a necessidade de realizar anualmente a citologia de colo\nuterino.","E":"Indicar colposcopia, visto que não foi realizada na consulta anterior."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-159521","number":"159521","sourceNumber":"159521","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em um dia normal de trabalho, médicos de família e comunidade atendem a muitos\ncasos diferentes. Certa manhã, determinado\nmédico atendeu a quinze pacientes, entre os quais se\nencontravam os seguintes: (1) uma criança de cinco anos de idade com suspeita de abuso sexual,\ntrazida pela mãe; (2) um idoso de sessenta e seis anos de idade, tabagista, com diabetes melito\n(DM) e hipertensão arterial sistêmica (HAS); (3) uma mulher de vinte e três anos de idade,\nestudante universitária, que não tomava banho havia uma semana; (4) um bebê de uma semana de\nvida (5) e sua mãe, puérpera, para consulta normal; (6) um adolescente de dezessete anos de\nidade, com rolha de cera; (7) uma idosa de setenta e um anos de idade, com diabetes melito (DM)\ne obesa, com úlcera no membro inferior esquerdo, (8) e sua filha, e cuidadora, de quarenta e nove\nanos de idade, que não dormia regularmente havia um mês. Considerando esses casos clínicos,\njulgue o item a seguir. No que se refere à saúde pública e às informações contidas nos casos\nclínicos, como medida preventiva oportunística, o médico de família deverá oferecer o exame\nPapanicolau às pacientes 3, 5 e 8.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-129016","number":"129016","sourceNumber":"129016","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente realizou exame citopatológico de rotina do colo do útero, obtendo o\nseguinte resultado: células escamosas atípicas de significado indeterminado possivelmente não\nneoplásicas. Com base nesse caso hipotético, assinale a alternativa que apresenta a melhor\nconduta em relação ao caso:","options":{"A":"Indicação cirúrgica com histerectomia total se acima de quarenta anos de idade.","B":"Repetição da citologia, em seis meses, na unidade básica de saúde.","C":"Colposcopia.","D":"Biópsia do colo do útero.","E":"Cauterização do colo do útero."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-129028","number":"129028","sourceNumber":"129028","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O papilomavírus humano (HPV) é um DNA-vírus do grupo papovavírus com mais de\ncem tipos reconhecidos atualmente. Vinte\ndesses tipos podem infectar o trato genital, estando\ndivididos em grupos de acordo com seu potencial de oncogenicidade. Em relação a essa patologia,\nassinale a alternativa correta.","options":{"A":"Os tipos seis e onze raramente se asssociam ao carcinoma invasivo de células escamosas,\nestando mais associados como agentes\netiológicos dos condilomas, isto é, das lesões clínicas.","B":"O uso de preservativos elimina o risco de transmissão para parceiros não infectados, como\nocorre na prevenção da AIDS.","C":"As evidências indicam que os tratamentos disponíveis erradicam o HPV.","D":"Mulheres com verrugas genitais estão associadas a apenas um tipo de HPV, pois não há a\npossibilidade de estarem infectadas simultaneamente por vários tipos.","E":"Há dois grupos de tipos distintos de alto risco oncogênico: os ligados a câncer invasor do colo\ndo\nútero, da vulva e da vagina e os associados a câncer da região anal e da orofaringe."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-129044","number":"129044","sourceNumber":"129044","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A atenção integral à saúde da mulher, que apresenta predisposição a várias doenças, é\nfundamental. Com relação a esse tema, assinale a alternativa correta.","options":{"A":"Apesar de os transtornos mentais serem mais frequentes em mulheres, a depressão é um\nevento raro durante a gravidez, devendo o uso de medicação antidepressiva ser evitado.","B":"A identificação de alterações inflamatórias no exame citopatológico, sem a identificação de\nagentes patogênicos específicos, deve ser objeto\nde tratamento devido ao risco de contaminação\ndo feto em caso de gravidez.","C":"A mamografia para mulheres com idade entre cinquenta e 69 anos deve ser realizada com\nintervalo máximo de dois anos. Para mulheres\npertencentes a grupos populacionais com risco\nelevado de desenvolver câncer de mama, a mamografia deve ser anual a partir dos quarenta anos\nde idade.","D":"A ectopia do colo do útero é uma situação fisiológica, por isso a denominação \"ferida no colo do\nútero\" é inapropriada.","E":"No Brasil, a principal estratégia utilizada para detecção precoce/rastreamento do câncer do colo\ndo útero é a realização de colposcopia."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-133992","number":"133992","sourceNumber":"133992","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com relação ao câncer de endométrio, assinale a alternativa correta.","options":{"A":"Para o estadiamento cirúrgico do câncer de endométrio, deve sempre ser realizado\nhisterectomia, salpingo-ooforectomia bilateral,\nlinfadenectomia pélvica e para-aórtica e citologia\nperitoneal, mesmo em pacientes com risco desprezível de disseminação linfática.","B":"A radioterapia adjuvante pós-operatória não tem impacto nenhum na diminuição do risco de\nrecorrência local vaginal/pélvica, tampouco na sobrevida sem doença.","C":"Em geral, os sarcomas uterinos são muito semelhantes ao câncer de endométrio quanto a\nfatores de risco, diagnóstico, comportamento clínico, padrão de disseminação e tratamento.","D":"Na avaliação de uma mulher com sangramento uterino anormal e suspeita de doença\nendometrial, a biopsia por aspiração do\nendométrio realizada em consultório é de pouca valia.","E":"A maioria dos fatores de risco para o surgimento de carcinoma de endométrio está relacionada\ncom a estimulação estrogênica, prolongada e\nsem oposição da progesterona."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-133947","number":"133947","sourceNumber":"133947","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Acerca das lesões precursoras do câncer do colo do útero, assinale a alternativa\ncorreta.","options":{"A":"De acordo com as Diretrizes Brasileiras para o Rastreamento do Câncer do Colo do Útero, o\nexame eltopatológico deve ser realizado trienalmente após dois resultados anuais negativos.","B":"A população alvo para realização do exame citopatológico para rastreamento compreende\nmulheres na faixa etária entre 18 anos, que\njá iniciaram a respectiva atividade sexual, e 64 anos de\nidade.","C":"Mulheres de até 20 anos de idade, com lesão intraepitelial de alto grau na citologia de\nrastreamento e colposcopia com achados\nmenores, devem ser tratadas com exérese da zona de\ntransformação ou conização.","D":"Paciente com lesão intraepitelial de alto grau na citologia de rastreamento, mas com colposcopia\nnegativa deve ser submetida à conização para avaliação do canal endocervical.","E":"Paciente com diagnóstico anatomopatológico de carcinoma in situ, submetida a tratamento\nexcisional e que apresente margens\ncomprometidas tem indicação imediata de um novo tratamento\nexcisional."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-104777","number":"104777","sourceNumber":"104777","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente de 56 anos de idade apresentou sangramento pós-menopausa. Seus\nantecedentes ginecológicos são: menarca aos nove anos, menopausa aos 45 anos, G4PN3PC1A0,\nhipertensa em uso de atenolol, IMC de 21 kg/m², usuária de contraceptivo hormonal oral por vinte\nanos; nega uso de TH. Com base nesse caso hipotético, assinale a alternativa que apresenta\napenas fatores de risco para o câncer de endométrio,","options":{"A":"Menarca precoce e uso de contraceptivo","B":"Hipertensão arterial e menarca precoce","C":"Uso de contraceptivo e multiparidade","D":"Multiparidade e hipertensão arterial","E":"Menarca precoce e multiparidade"},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-111281","number":"111281","sourceNumber":"111281","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Das lesões epiteliais vulvares descritas abaixo, qual se refere a uma neoplasia\nintraepitelial?","options":{"A":"Líquen plano.","B":"Doença de Paget.","C":"Líquen escleroso.","D":"Doença de Behçet.","E":"Hiperplasia de células escamosas."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-80713","number":"80713","sourceNumber":"80713","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 56 anos com diagnóstico de câncer de colo de útero tem exame\nginecológico conforme a ilustração. O tumor foi\nbiopsiado por cistoscopia e o histopatológico\ncorresponde ao da lesão cervical. Com relação a esse caso, é correto afirmar que: (VER IMAGEM)","options":{"A":"O estádio é IVb.","B":"A biópsia deve corresponder a carcinoma espinocelular, considerando que a paciente possua o\ntipo mais comum de neoplasia cervical.","C":"É necessário solicitar retoscopia, urografia excretora e ressonância magnética de pelve para fins\nde estadiamento, além da cistoscopia.","D":"O estadiamento definitivo é cirúrgico.","E":"A cirurgia para tratamento do caso é a operação de Wertheim-Meigs."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":["question_bank/media/medcurso/medcurso-gineco-gin-5/80713.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-64430","number":"64430","sourceNumber":"64430","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Evidências edipemiológicas permitem associar algumas infecções virais persistentes ao\ndesenvolvimento de neoplasias. É exemplo dessa associação:","options":{"A":"Hepatite E e carcinoma hepatocelular","B":"Papilomavírus e câncer de colo de útero","C":"Vírus Epstein-Barr e adenocarcinoma renal","D":"HTVL-1 e melanoma","E":"Citomegalovírus e retinoblastoma"},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-75498","number":"75498","sourceNumber":"75498","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher com 25 anos de idade procura Unidade Básica de Saúde para exame\nginecológico de rotina. Relata ter iniciado\natividade sexual há seis anos e já ter tido quatro parceiros\nsexuais. Não há alterações visíveis ao exame especular. Nessa oportunidade a paciente é\nsubmetida pela primeira vez ao exame de colpocitologia oncológica. Após um mês, retorna com\nresultado da citologia, que revela a presença de lesão intraepitelial escamosa de baixo grau (HPV e\nNIC I). A conduta mais apropriada para essa paciente é a realização de:","options":{"A":"Conização cervical.","B":"Colpocitologia oncológica em seis meses.","C":"Colposcopia e biópsia dirigida.","D":"Eletrocauterização do colo uterino.","E":"Pesquisa de HPV por método de biologia molecular."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-137558","number":"137558","sourceNumber":"137558","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher de 40 anos, multípara, com menstruações regulares, comparece a\numa consulta para realizar exame de prevenção\ndo câncer de colo uterino. No exame\nespecular , o médico observou um colo cilíndrico, sem corrimento vaginal. Ele colheu material\npara a colpocitologia oncótica, e o resultado do exame mostrou lesão intraepitelial de alto\ngrau. Qual a conduta mais adequada nesse caso?","options":{"A":"Solicitar à paciente que faça nova colpocitologia e ultrassonografia pélvica.","B":"Encaminhar a paciente para colposcopia e solicitar realização de biópsia.","C":"Realizar o teste do iodo no colo uterino para confirmar o diagnóstico da paciente.","D":"Solicitar à paciente que faça nova colpocitologia e ressonância nuclear magnética.","E":"Repetir imediatamente a colpocitologia e encaminhar a paciente para colposcopia se o exame\ncontinuar alterado."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-31010","number":"31010","sourceNumber":"31010","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Acerca de doenças sexualmente transmissíveis e infecções pélvicas, julgue o item\nsubsequente. Dos subtipos de papilomavírus humano (HPV) encontrados nas lesões de alto risco\n(16, 18, 31, 39, 45, 56, e 59), o mais comumente encontrado no adenocarcinoma de colo uterino é\n\no 18.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-31017","number":"31017","sourceNumber":"31017","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com referência a doenças benignas e malignas do trato genital feminino e mamário,\njulgue o item a seguir. O crescimento rápido\nde um mioma uterino com macroscopia evidenciando\nmargens infiltrativas e extensão além do útero e cujo exame histopatológico evidenciou atipia\ncitológica e necrose de coagulação das células tumorais evidencia um leiomiossarcoma de mau\nprognóstico.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-138735","number":"138735","sourceNumber":"138735","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente, com 25 anos de idade, sem queixas, retorna para consulta de rotina na\nUnidade Básica de Saúde trazendo o resultado\ndo exame citopatológico do colo uterino que\napresentou amostra satisfatória, com atipia de células escamosas de significado indeterminado\n(ASCUS). O exame especular vaginal feito na consulta em que o material colhido era normal. O\ncitopatológico anterior da paciente havia sido colhido dois anos antes e não apresentava sinais de\nmalignidade. Qual a conduta a ser adotada?","options":{"A":"Encaminhar a paciente para colposcopia com biópsia dirigida.","B":"Solicitar retorno da paciente em seis meses para repetir o exame citopatológico.","C":"Encaminhar a paciente para avaliação especializada em setor de patologia do trato genital\ninferior.","D":"Tratar a paciente com creme vaginal de metronidazol e repetir o citopatológico em seguida.","E":"Colher o exame novamente, pois trata-se de erro do\nlaboratório."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-22191","number":"22191","sourceNumber":"22191","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Acerca das doenças sexualmente transmissíveis e infecções pélvicas, julgue o item que\nse segue: Alguns tipos de HPV causam cânceres\ne lesões intraepteliais de alto grau. O tipo 16 é a\nforma de HPV mais comum no câncer invasivo e no NIC 2 e NIC 3.","options":{"A":"certo","B":"errado"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-22194","number":"22194","sourceNumber":"22194","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Julgue o item seguinte quanto aos distúrbios benignos e malignos do corpo uterino.\nO Papel do estrogênio no desenvolvimento da\nmaioria dos cânceres de endométrio é claro: todo\nfator que aumente a exposição ao estrogênio sem oposição da progesterona eleva o risco de\ncâncer do endométrio.","options":{"A":"certo","B":"errado"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-19286","number":"19286","sourceNumber":"19286","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 75 anos de idade vem apresentando, nos últimos oito meses, os seguintes\nsintomas em vulva: irritação com prurido, desconforto local e descarga sanguinolenta. Ao exame,\nidentificou-se lesão ulcerada de 0,5 cm entre o grande e pequeno lábio direito. Considerando o\nquadro clínico apresentado acima, julgue o item que se segue. As manifestações clínicas são de\nvulvite por fungo, justificando o tratamento com antifúngico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-359180","number":"359180","sourceNumber":"359180","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente 21 anos comparece à consulta ginecológica trazendo resultado de exame\ncitopatológico do colo do útero ASC-US (células escamosas atípicas de significado indeterminado,\npossivelmente não neoplásicas). De acordo com as diretrizes de rastreamento do câncer de colo do\nútero do Ministério da Saúde, assinale a alternativa que apresenta a conduta CORRETA.","options":{"A":"Repetir o citopatológico em 6 meses e, em caso de novo resultado anormal, encaminhar para\ncolposcopia.","B":"Repetir o citopatológico em 12 meses e, em caso de novo resultado anormal, encaminhar para\ncolposcopia.","C":"Repetir o citopatológico em 3 anos e, em caso de novo resultado anormal, a partir dos 25 anos\nencaminhar para colposcopia.","D":"Encaminhar para colposcopia."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-352170","number":"352170","sourceNumber":"352170","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"No Brasil, o método de rastreamento do câncer do colo do útero e de suas lesões\nprecursoras é o exame citopatológico. Marque a alternativa falsa em relação ao rastreamento do\ncâncer de colo uterino no Brasil.","options":{"A":"Com relação a periodicidade do exame, os dois primeiros exames citopatologicos devem ser\nrealizados com intervalo anual e, se ambos os resultados forem negativos, os próximos devem ser\nrealizados a cada 3 anos.","B":"As gestantes devem ter o exame evitado pela possibilidade de sangramento e risco de\nabortamento.","C":"O primeiro exame citopatológico deve ser aos 25 anos para as mulheres que já tiveram ou têm\natividade sexual.","D":"Os exames periódicos devem seguir até os 64 anos e, naquelas mulheres sem história prévia de\ndoença neoplásica pré-invasiva, interrompidos\nquando tiverem pelo menos dois exames negativos\nconsecutivos nos últimos cinco anos."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-320425","number":"320425","sourceNumber":"320425","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 37 anos, nulípara, em uso de pílula anticoncepcional combinada, solteira,\ncom vida sexual ativa, apresentando\nsinusorragia nos últimos 4 meses. Realizou colpocitologia\noncótica do colo uterino com resultado: HSIL ? lesão intraepitelial escamosa de alto grau. Assinale\na alternativa correta quanto ao caso clínico apresentado:","options":{"A":"a paciente deve ser encaminhada para realização de conização.","B":"a paciente deve ser orientada a retornar à unidade de saúde em 6 meses para\nacompanhamento com nova colpocitologia oncótica do colo uterino.","C":"a paciente deve ser orientada a retornar à unidade de saúde em 12 meses para\nacompanhamento com nova colpocitologia oncótica do colo uterino.","D":"a paciente deve ser encaminhada para a realização de histerectomia.","E":"a paciente deve ser encaminhada para realização de colposcopia."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-335085","number":"335085","sourceNumber":"335085","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer do colo do útero é o terceiro tipo de câncer mais incidente entre mulheres no\nBrasil. Com relação ao rastreamento do câncer de colo do útero, segundo o Ministério da Saúde do\nBrasil (2016), assinale a alternativa correta.","options":{"A":"O exame citopatológico deve ser realizado em todas as mulheres de 15 a 45 anos de idade.","B":"O exame citopatológico deve ser realizado com intervalos semestrais no primeiro ano após o\ninício da vida sexual e, se normal, manter seguimento anual.","C":"O rastreamento em gestantes deve ser evitado devido ao desconforto e à possibilidade de\nassociar risco à gestação.","D":"Mulheres sem história de atividade sexual não devem ser submetidas ao rastreamento do\ncâncer do colo do útero."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-334741","number":"334741","sourceNumber":"334741","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em paciente com adenocarcinoma de endométrio optou-se pela círurgia de\nWertheim-Meigs, nesse caso, qual órgão ou estrutura será preservado?","options":{"A":"Ovários.","B":"Terço médio da vagina.","C":"Paramétrios.","D":"Linfonodos pélvicos."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-336289","number":"336289","sourceNumber":"336289","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 26 anos, nulípara, apresentando citologia de colo do útero com lesão\nintraepitelial de alto grau, colposcopia\nevidenciando junção escamo-colunar (JEC) visível e achados\nsugestivos de lesão de alto grau. Frente a esses resultados, a conduta é:","options":{"A":"Criocauterização interessando a JEC.","B":"Conização de colo por CAF ( cirurgia de alta frequência).","C":"Seguimento com colposcopia e citologia a cada seis meses e, no agravo, realizar conização.","D":"Solicitação de hibridização para tipagem de sorotipo viral, que se for de baixo grau, assumir\nconduta expectante."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-345731","number":"345731","sourceNumber":"345731","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao câncer de endométrio, a situação que não representa risco aumentado\né:","options":{"A":"Curetagens de repetição.","B":"Obesidade..","C":"Uso prolongado de tamoxifeno.","D":"Diabete."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-345739","number":"345739","sourceNumber":"345739","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mantém estreita relação de causalidade com o câncer de colo uterino:","options":{"A":"Obesidade.","B":"Diabete.","C":"Uso de contraceptivo combinado oral.","D":"Múltiplos parceiros sexuais."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-291924","number":"291924","sourceNumber":"291924","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação à genitália feminina, é INCORRETO afirmar que:","options":{"A":"Os grandes lábios continuam em direção ao períneo para formarem, na linha média, a comissura\nposterior ou fúrcula, no limite inferior da vulva.","B":"O vestíbulo da vagina estende-se do clitóris até a borda posterior do hímen.","C":"Os bulbovestibulares correspondem ao corpo cavernoso no homem.","D":"As glândulas parauretrais, são homólogas da próstata masculina têm seus orifícios externos\nlocalizados lateroposteriormente ao meato uretral."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-291616","number":"291616","sourceNumber":"291616","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"?A Atenção Primária à Saúde (APS) apresenta-se como o eixo estruturante do SUS e\nconstitui-se como o primeiro nível de atenção na RAS, sendo enfatizada, cada vez mais, sua\nfunção de congregar um conjunto de ações de promoção e proteção à saúde, prevenção de\nagravos, diagnóstico, tratamento, reabilitação e manutenção da saúde nas dimensões coletiva e\nindividual, por meio de ações gerenciais e sanitárias participativas e democráticas, trabalho em\nequipe, responsabilização sanitária e base territorial. Dessa forma, suas três funções essenciais\nsão: (i) resolver a grande maioria dos problemas de saúde da população; (ii) organizar os fluxos e\ncontrafluxos dos usuários pelos diversos pontos de atenção à saúde, no sistema de serviços de\nsaúde, e (iii) responsabilizar-se pela saúde dos usuários em qualquer ponto de atenção à saúde em\nque estejam. É, assim, papel da atenção primária desenvolver ações para prevenção do câncer do\ncolo do útero por meio de ações de educação em saúde, vacinação de grupos indicados e\ndetecção precoce do câncer e de suas lesões precursoras por meio de seu rastreamento. O\nrastreamento é uma tecnologia da atenção primária, e os profissionais atuantes nesse nível de\natenção devem conhecer o método, a periodicidade e a população-alvo recomendados, sabendo\nainda orientar e encaminhar para tratamento as mulheres de acordo com os resultados dos exames\ne garantir seu seguimento? Fonte : Diretrizes brasileiras para o rastreamento do cancer do colo do\nutero / Instituto Nacional de Cancer Jose Alencar Gomes da Silva. Coordenacao de Prevencao e\nVigilancia. Divisao de Deteccao Precoce e Apoio a Organizacao de Rede. ? 2. ed. rev. atual. ? Rio\nde Janeiro: INCA, 2016. Analise as assertivas abaixo sobre o rastreamento do câncer do colo do\nútero no Brasil: I. Os dois primeiros exames devem ser realizados com intervalo anual e, se ambos\nos resultados forem negativos, os próximos devem ser realizados a cada 3 anos. II. O início da\ncoleta deve ser aos 25 anos de idade para as mulheres que já tiveram ou têm atividade sexual. III.\nO rastreamento em gestantes deve ser evitado pelo risco de sangramento e trabalho de parto\nprematuro. IV. Após os 65 anos, o rastreamento pode ser suspenso, inclusive nas pacientes com\ndoença neoplásica préinvasiva prévia, desde que o último citopatológico seja negativo. Sobre o\nrastreamento do câncer do colo do útero no Brasil é correto o que se afirm a em:","options":{"A":"I e III apenas.","B":"II e IV apenas.","C":"III e IV apenas.","D":"I, II e IV apenas.","E":"I e II apenas."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-304862","number":"304862","sourceNumber":"304862","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Entre os tipos de cânceres que acomete a mulher, o terceiro mais frequente é o câncer\nde colo de útero, e o tipo mais comum é o\ncarcinoma escamoso ou espinocelular. Qual a via de\npropagação mais frequente dessa neoplasia?","options":{"A":"Linfática.","B":"Por contiguidade.","C":"Venosa.","D":"Arterial."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-314066","number":"314066","sourceNumber":"314066","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Sobre os fatores de risco para carcinoma endometrial, analisar os itens abaixo: I. Uso\nde tamoxifeno. II. Nuliparidade. III.\nMultiparidade. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e II.","D":"Somente os itens I e III.","E":"Todos os itens."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-260679","number":"260679","sourceNumber":"260679","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em uma unidade básica de saúde, a equipe de saúde recebe os exames citológicos do\ncolo uterino das pacientes abaixo: Ana 42 anos = lesão intraepitelial escamosa de alto grau.\n\nBetânia 37 anos = lesão intraepitelial escamosa de baixo grau. Cleonice 29 anos = Atipias em\ncélulas glandulares de significado indeterminado,\npossivelmente não neoplásica. Debora 36 anos =\nCélulas escamosas atípicas de significado indeterminado, possivelmente não neoplásicas; Todas\nsão pacientes que fizeram regularmente exames nos últimos 5 anos e nunca apresentaram\nanormalidades previamente. A conduta indicada frente aos achados é:","options":{"A":"Ana encaminhar para colposcopia, Betânia repetir o exame em 6 meses, Cleonice encaminhar\npara colposcopia, Debora repetir o exame em 6 meses.","B":"Ana encaminhar para colposcopia, Betânia encaminhar para colposcopia, Cleonice encaminhar\npara colposcopia , Debora repetir o exame em 6\nmeses.","C":"Ana encaminhar para colposcopia, Betânia repetir o exame em 6 meses, Cleonice repetir o\nexame em 6 meses, Debora repetir o exame em 6 meses.","D":"Ana encaminhar para colposcopia, Betânia repetir o exame em 6 meses, Cleonice encaminhar\npara colposcopia , Debora encaminhar para colposcopia\n.","E":"Ana repetir o exame em 6 meses, Betânia repetir o exame em 6 meses, Cleonice encaminhar\npara colposcopia, Debora repetir o exame em 6 meses."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-257358","number":"257358","sourceNumber":"257358","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação a doença intra-epitelial do colo, assinale a alternativa INCORRETA:","options":{"A":"A Junção Escamo-Colunar (JEC) raramente permanece restrita ao óstio externo do colo, ao\ncontrário, é ponto dinâmico que se altera em resposta à puberdade, gravidez e menopausa.","B":"A Neoplasia Intra-Epitelial Cervical (NIC) é mais frequente no lábio posterior que no anterior, e\nraramente origina-se nos ângulos ou comissuras laterais.","C":"Os lactobacilos atuam sobre o glicogênio, presentes nas células da mucosa vaginal, com\nreflexos no pH, estimulando as células de reserva sub-colunares à metaplasia.","D":"A zona de transformação é o resultado do avanço da metaplasia em direção ao óstio externo e\nsobre as vilosidades colunares."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-266383","number":"266383","sourceNumber":"266383","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"No rastreamento do câncer genital feminino através da citologia oncótica, é correto\nafirmar que:","options":{"A":"Não deve ser realizado em gestante pelo baixo risco do câncer do colo uterino nesta condição.","B":"Deve ser realizado com maior frequência nas mulheres na pós-menopausa pelo risco provocado\npelo desequilíbrio hormonal.","C":"Deve ser realizado em mulheres submetidas à histerectomia por apresentar maior risco para o\ncâncer genital.","D":"A recomendação é de não realizar o rastreamento em mulheres que não tenham iniciado\natividade sexual."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-266384","number":"266384","sourceNumber":"266384","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Há muito se investiga a correlação entre o HPV (Vírus do Papiloma Humano) e a\nneoplasia cervical e até o momento foram descobertos mais de 120 tipos de HPV no trato genital.\nDentre eles, a maior correlação com a neoplasia de colo uterino ou de maior potencial oncogênico\ninclui os tipos:","options":{"A":"6 e 11.","B":"16 e 18.","C":"31 e 33.","D":"43 e 44."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-283916","number":"283916","sourceNumber":"283916","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 40 anos, G2P2, traz citopatológico de colo uterino (CP) realizado\nrecentemente, cujo resultado evidenciou lesão\nintraepitelial de alto grau. Em relação a esse caso, é\ncorreto afirmar que a paciente:","options":{"A":"Apresenta diagnóstico de lesão pré-invasora do colo uterino, devendo-se realizar conização.","B":"Tem exame de rastreamento alterado, devendo-se prosseguir na investigação com diagnóstico\nhistológico.","C":"Se beneficiará da vacina para HPV.","D":"Já tem diagnóstico firmado, dispensando-se a colposcopia.","E":"Se beneficiará de teste de DNA-HPV."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-232118","number":"232118","sourceNumber":"232118","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em um ambulatório de ginecologia, o médico responsável avalia os resultados de\nexames das pacientes abaixo: Maria, 47\nanos, resultado de exame citopatológico do colo uterino =\nlesão intraepitelial escamosa de alto grau. Katia, 26 anos, resultado de exame citopatológico do\ncolo uterino = lesão intraepitelial escamosa de baixo grau (o exame realizado há 1 ano foi negativo\npara neoplasia). Lucia, 29 anos, resultado de exame citopatológico do colo uterino = Células\nescamosas atípicas, de significado indeterminado, não podendo excluir lesão intraepitelial de alto\ngrau (o exame realizado há 1 ano foi negativo para neoplasia). Neusa, 53 anos, resultado de\nexame histopatológico do colo uterino = NIC III. A conduta adequada para cada uma das pacientes\nacima é: A conduta adequada para cada uma das pacientes acima é:","options":{"A":"Maria, realizar colposcopia. Katia, repetir o exame em 6 meses. Lucia, realizar colposcopia.\n\nNeusa, realizar colposcopia.","B":"Maria, realizar colposcopia. Katia, repetir o exame em 6 meses. Lucia, repetir o exame em 6\nmeses. Neusa, realizar colposcopia.","C":"Maria, realizar conização. Katia, repetir o exame em 6 meses. Lucia, realizar colposcopia.\n\nNeusa, realizar conização.","D":"Maria, realizar colposcopia. Katia, repetir o exame em 6 meses. Lucia, realizar colposcopia.\n\nNeusa, realizar conização.","E":"Maria, realizar colposcopia. Katia, realizar colposcopia. Lucia, realizar colposcopia. Neusa,\nrealizar colposcopia."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-227090","number":"227090","sourceNumber":"227090","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Sobre a anatomia pélvica feminina, é CORRETO afirmar que:","options":{"A":"O útero é irrigado exclusivamente pelas artérias uterinas esquerda e direita sem grande\ninfluência de vasos colaterais vaginais e ovarianos.","B":"Os ovários são estruturas peritonizadas e fixas à parede pélvica pelos ligamentos ovarianos.","C":"Os ligamentos redondos são os principais responsáveis pela estabilização do útero na pelve.","D":"Os ureteres são estruturas retroperitoniais e se inserem na bexiga bilateralmente no trígono\nvesical."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-243004","number":"243004","sourceNumber":"243004","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher de 23 anos de idade realizou exames de rotina em uma unidade básica de\nsaúde e obteve o seguinte resultado\ncitopatológico: lesão intraepitelial de baixo grau (NIC I). Com\nbase no caso clínico nas recomendações do Ministério da Saúde, assinale a alternativa CORRETA\nno que se refere à melhor conduta:","options":{"A":"a paciente em questão não necessita de rastreio, uma vez que o início da coleta da citologia\ncervical é recomendado para mulheres com mais de trinta anos de idade.","B":"deve?se repetir a citologia em um ano.","C":"deve?se realizar uma colposcopia.","D":"deve-se encaminhar a paciente para agendamento de conização do colo uterino.","E":"deve?se repetir a citologia em seis meses."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-227264","number":"227264","sourceNumber":"227264","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente com 28 anos, mãe de dois filhos vivos, apresentando exame colpocitológico\ncompatível com lesão escamosa de alto grau.\nComplementou a investigação com colposcopia que\nmostrou área de mosaico em lábio anterior que penetrava no canal endocervical. A biópsia da lesão\nmostrou neoplasia intra-epitelial grau 3. Qual a conduta a ser adotada?","options":{"A":"Controle com colpocitológico trimestral.","B":"Ressonância nuclear magnética da pelve.","C":"Conização (traquelectomia).","D":"Histerectomia total."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-243012","number":"243012","sourceNumber":"243012","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer de colo uterino é uma lesão invasiva intrauterina ocasionada principalmente\npelo HPV. Sobre o rastreio de câncer de colo de\nútero, conforme recomendação do Ministério da\nSaúde, assinale a alternativa INCORRETA:","options":{"A":"O início do rastreio deve ser tão logo a paciente iniciar a atividade sexual, visto que essa\nprática\né a precursora das lesões de colo uterino.","B":"O exame citopatológico deverá ser realizado a cada três anos, após dois exames negativos, com\nintervalo anual.","C":"Os exames devem ser realizados periodicamente até os 64 anos de idade e interrompidos\nquando, após essa idade, elas tiverem pelo\nmenos dois exames negativos consecutivos nos últimos\ncinco anos.","D":"Nas mulheres com mais de 64 anos, que nunca realizaram o citopatológico, deve-se realizar 02\nexames, com intervalo entre 1 e 3 anos. Se ambos forem negativos elas podem ser dispensadas de\nexames adicionais.","E":"O rastreio em gestantes deve seguir a mesma recomendação de periodicidade e faixa etária\ncomo para as demais mulheres."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-246386","number":"246386","sourceNumber":"246386","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A cirurgia de escolha para o carcinoma de endométrio estágio I, é:","options":{"A":"Histerectomia total.","B":"Pan histerectomia.","C":"Operação de Wertheim.","D":"Histerectomia total com anexectomia bilateral e exérese do terço superior de vagina."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-246762","number":"246762","sourceNumber":"246762","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Qual das seguintes pacientes de 25 anos é a mais provável para o desenvolvimento de\nadenocarcinoma endometrial?","options":{"A":"Uma prostituta utilizando Cos.","B":"Uma mulher casada com síndrome dos ovários policísticos (SOP).","C":"Uma garçonete com feminilização testicular.","D":"Uma médica com dispositivo intra-uterino (DIU).","E":"Nenhuma das anteriores tem risco aumentado de adenocarcinoma endometrial."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-246767","number":"246767","sourceNumber":"246767","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com relação ao câncer endometrial, assinale a alternativa incorreta:","options":{"A":"Obesidade, síndrome dos ovários policísticos e uso de tamoxifeno são fatores de risco\nsignificativos.","B":"O tratamento da Hiperplasia Endometrial não atípica em mulheres na pré-menopausa deve ser\nfeito com progestogênio de baixa dosagem por um período de 3 a 6 meses.","C":"Diante do diagnóstico de Hiperplasia Endometrial atípica, a realização de histerectomia se impõe\ne deverá ser realizada, independente da idade\ne dos antecedentes reprodutivos da paciente.","D":"O tipo histológico mais comum de Câncer de Endométrio é o adenocarcinoma endometrioide,\nque tem por característica apresentar glândulas\nque se assemelham às do endométrio normal.","E":"Todas as alternativas anteriores estão corretas."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-220282","number":"220282","sourceNumber":"220282","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao câncer do colo uterino, assinale a alternativa INCORRETA:","options":{"A":"A infecção por Papiloma Vírus Humano (HPV) é extremamente comum, porém resulta em\ncâncer cervical em apenas uma pequena proporção\nde mulheres infectadas, estimando- se que 75\na 80% dos adultos sexualmente ativos adquiram o HPV antes dos 50 anos.","B":"As alterações glandulares reativas, como nas inflamações, endometriose, cistos mesonéfricos,\nectrópio cervical, úlceras associadas a\ninfecções sexualmente transmissíveis, fazem parte do\ndiagnóstico diferencial do câncer cervical.","C":"O HPV é fator central no desenvolvimento do câncer cervical e pode ser detectado em 85,7%,\nsendo o mais comum tipo histológico o de células escamosas (69,9% cervicais) e os\nadenocarcinomas (25%).","D":"A maioria das infecções por HPV é transitória e o vírus apenas não é suficiente para causar\nneoplasia cervical, havendo a persistência da\ninfecção pelo HPV, o tempo desde a infecção inicial\naté o desenvolvimento de Neoplasia Intra-Epitelial Cervical de alto grau (NIC) e, finalmente, o\ncâncer invasivo leva em média 15 anos, embora tenham sido relatados cursos mais rápidos."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-199540","number":"199540","sourceNumber":"199540","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao câncer do colo uterino, é INCORRETO afirmar que:","options":{"A":"O papilomavírus humano (HPV) é fator central no desenvolvimento do câncer cervical e pode ser\ndetectado em 85,7% dos casos, sendo o mais comum tipo histológico o de células escamosas\n(69,9% cervicais) e os adenocarcinomas (25%).","B":"O câncer cervical atinge 84% dos casos nos países subdesenvolvidos, enquanto que em\nregiões em desenvolvimento é a 2ª causa de\n\ncâncer (15,7 por 100.000 mulheres) e a 3ª causa de morte (8,3 por 100.000 mulheres).","C":"O câncer cervical em seus estádios iniciais é\n\nfrequentemente assintomático e, de acordo com a Federação Internacional de Ginecologia e\nObstetrícia (FIGO), o risco de metástase em\n\nlinfonodos pélvicos aumenta de acordo com a invasão nas proporções de 0,6% no estádio IA1 e\n7% no estádio IA2.","D":"A vacina anti-HPV é recomendada a partir dos 9 anos em mulheres e a vacinação chamada de\nrecuperação é recomendada para mulheres com\n\nidade de 13 a 26 anos que não foram ainda\nvacinadas ou aquelas que não completaram a série."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-196772","number":"196772","sourceNumber":"196772","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A paciente histerectomizada deve colher colpocitológico quando:","options":{"A":"Anualmente.","B":"Semestral.","C":"Em intervalos de 3 a 3 anos.","D":"Apenas quando submete a cirurgia por lesão pré neoplasica ou neoplásica do colo."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-199569","number":"199569","sourceNumber":"199569","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao exame citopatológico para rastreio do câncer de colo uterino em\nmulheres imunocompetentes, analise as assertivas\nabaixo: I. O início da coleta deve ser feito aos\n20 anos para mulheres que tiveram ou têm atividade sexual. II. Os dois primeiros exames devem\nser realizados com intervalo anual e, se ambos os resultados forem negativos, os próximos devem\nser realizados a cada 03 anos. III. Os exames citopatológicos devem ser realizados trienalmente\naté os 70 anos e a partir dessa idade não será mais necessária a realização do mesmo. IV.\nMulheres submetidas à histerectomia total por lesões benignas sem história prévias de lesões\ncervicais de alto grau, podem ser excluídas do rastreamento, desde que apresentem exames\nanteriores normais. De acordo com as Diretrizes Brasileiras para o rastreamento do câncer do colo\nuterino 2016, é CORRETO afirmar:","options":{"A":"Apenas as assertivas I e II estão corretas.","B":"Apenas as assertivas III e IV estão corretas.","C":"Apenas as assertivas II e IV estão corretas.","D":"Apenas as assertivas I, II e III estão corretas."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-199584","number":"199584","sourceNumber":"199584","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 28 anos de idade, assintomática, sem comorbidades e imunocompetente,\nprocura o ambulatório de ginecologia para\nfazer preventivo de colo uterino. Após 35 dias retorna\ncom resultado de colpocitologia oncótica, que evidenciou células escamosas atípicas de significado\nindeterminado, não se podendo afastar lesão de alto grau neoplásicas (ASC-H). De acordo com as\nDiretrizes Brasileiras para o rastreamento do câncer do colo uterino, INCA/Ministério da\nSaúde/2016, a paciente deverá:","options":{"A":"Realizar colposcopia.","B":"Repetir a citologia em 6 meses.","C":"Repetir a citologia em 12 meses.","D":"Repetir a citologia em 3 anos."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-215154","number":"215154","sourceNumber":"215154","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer de colo de útero ainda é uma doença de alta incidência em países em\ndesenvolvimento. Qual a conduta mais adequada em uma paciente portadora de carcinoma\nepidermóide de colo de útero estádio IIB (lesão de 5 cm com invasão de paramétrios sem\nhidronefrose)?","options":{"A":"Histerectomia total ampliada com linfadenectomia pélvica.","B":"Histerectomia simples sem linfadenectomia.","C":"Radioterapia e quimioterapia.","D":"Exenteração pélvica total.","E":"Derivação urinária e colostomia."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-215162","number":"215162","sourceNumber":"215162","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente 52 anos, refere prurido vulvar resistente ao uso de medicamentos. Ao exame\né observado diminuição da gordura subcutânea da\nvulva, atrofia das formações vulvares, os\npequenos lábios ausentes e sepultamento do clitóris. Qual o provável diagnóstico?","options":{"A":"Líquen escleroso.","B":"Líquen plano.","C":"Candidíase vaginal crônica","D":"Distrofia hiperplásica.","E":"Doença de Paget."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-215103","number":"215103","sourceNumber":"215103","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente 28 anos, G3 P3 A0, ligadura tubária, fez exame preventivo de rotina na UBS,\napós três anos sem realizá-lo. O resultado\nfoi Lesão Intraepitelial Escamosa de Alto Grau (HSIL). A\nconduta adequada:","options":{"A":"Como a paciente tem prole constituída e tem ligadura tubária, encaminhar para conização.","B":"Repetir o preventivo, e se dois exames consecutivos alterados: enviar para colposcopia.","C":"Histerectomia total.","D":"Colposcopia.","E":"Exérese da zona de transformação."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-174393","number":"174393","sourceNumber":"174393","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"?Para o ano de 2016, no Brasil, são esperados 16.340 casos novos de câncer do colo\ndo útero, com um risco estimado de 15,85\ncasos a cada 100 mil mulheres. Sem considerar os\ntumores de pele não melanoma, o câncer do colo do útero é o primeiro mais incidente na Região\nNorte (23,97/100 mil). Nas Regiões Centro-Oeste (20,72/100 mil) e Nordeste (19,49/100 mil), ocupa\na segunda posição; na Região Sudeste (11,30/100 mil), a terceira; e, na Região Sul (15,17 /100\nmil), a quarta posição. O câncer do colo do útero é considerado um importante problema de saúde\npública. Foi estimada a ocorrência de 527 mil casos novos em mulheres, no mundo, em 2012,\nconfigurando, assim, o quarto tipo de câncer mais comum nessa população. Cerca de 70% dos\ncasos diagnosticados de câncer do colo do útero ocorrem em regiões menos desenvolvidas e,\nquase um quinto ocorre na Índia. A taxa de incidência do câncer do colo do útero vem diminuindo,\nao longo das últimas três décadas, na maioria dos países em processo de transição\nsocioeconômica. Tal fato reflete, principalmente, as implementações de programas de prevenção.\n\nGeralmente a doença começa a partir dos 30 anos e aumenta seu risco rapidamente até atingir as\nfaixas etárias acima de 50 anos. O principal fator de risco para o desenvolvimento do câncer do\ncolo do útero é a infecção pelo papilomavírus humano (HPV). Infecções persistentes por HPV\npodem levar a transformações intraepiteliais progressivas que podem evoluir para lesões\nintraepiteliais precursoras do câncer do colo do útero, as quais, se não diagnosticadas e tratadas\noportunamente, evoluem para o câncer do colo do útero. A infecção por HPV é a doença\nsexualmente transmissível (DST) mais comum em todo o mundo e a maioria das pessoas\nsexualmente ativas, homens e mulheres, terá contato com o vírus durante algum momento da vida.\nAproximadamente 291 milhões de mulheres no mundo apresentam infecção por HPV em algum\nperíodo da vida, correspondendo a uma prevalência de 10,4%. Entretanto, mais de 90% dessas\nnovas infecções por HPV regridem espontaneamente em seis a 18 meses. Existem hoje 13 tipos de\nHPV reconhecidos como oncogênicos pela Iarc. Desses, os mais comuns são o HPV16 e o HPV18.\nContudo, a infecção pelo HPV, por si só, não representa uma causa suficiente para o surgimento\ndessa neoplasia, sendo necessária a persistência da infecção. A associação com outros fatores de\n\nrisco, como o tabagismo e a imunossupressão (pelo vírus da imunodeficiência humana - HIV ou\noutras causas), influencia no surgimento desse\ncâncer. A vacina contra o HPV é uma das\nferramentas para o combate ao câncer do colo do útero. No Brasil, o Ministério da Saúde\nimplementou, no calendário vacinal, em 2014, a vacina tetravalente contra o HPV para meninas de\n9 a 13 anos. Essa vacina protege contra os subtipos 6, 11, 16 e 18 do HPV. Os dois primeiros\ncausam verrugas genitais e os dois últimos são responsáveis por cerca de 70% dos casos de\ncâncer do colo do útero. Vale ressaltar que, mesmo as mulheres vacinadas, quando alcançarem a\nidade preconizada, deverão realizar o exame preventivo, pois a vacina não protege contra todos os\nsubtipos oncogênicos do HPV. O rastreamento do câncer do colo do útero no Brasil, recomendado\npelo Ministério da Saúde, é o exame citopatológico em mulheres de 25 a 64 anos. A rotina é a\nrepetição do exame Papanicolau a cada três anos, após dois exames normais consecutivos\nrealizados com um intervalo de um ano. A efetividade do programa de controle do câncer do colo\ndo útero é alcançada com a garantia da organização, da integralidade e da qualidade dos serviços,\nbem como do tratamento e do seguimento das pacientes. Esse tumor apresenta alto potencial de\nprevenção e cura quando diagnosticado precocemente, ficando atrás somente do câncer de pele\nnão melanoma. De acordo com a última estimativa mundial, essa neoplasia foi responsável por de\n265 mil óbitos em mulheres em 2012, sendo que 87% desses óbitos ocorreram em países em\ndesenvolvimento. A última informação para mortalidade no Brasil aponta que ocorreram, em 2013,\n\n5.430 mortes por câncer do colo do útero em mulheres. A sobrevida em cinco anos para esse tipo\nde câncer obteve melhora ao longo dos anos,\nvariando de menos de 50% para mais de 70% em\ntodo o mundo, de uma forma geral. No Brasil, para o período de 2005 a 2009, a sobrevida ficou em\ntorno de 61%.? (Estimativa 2016: incidência de câncer no Brasil / Instituto Nacional de Câncer. José\nAlencar Gomes da Silva ? Rio de Janeiro: INCA, 2015. O texto acima evidencia a grande\nimportância do conhecimento do HPV e das lesões precursoras do câncer de colo uterino para sua\nprevenção. Assinale a alternativa INCORRETA:","options":{"A":"Pacientes com resultado de colpocitologia oncótica HSIL ? lesão intraepitelial de alto grau,\ndevem submeter-se à colposcopia com biópsia e, em\ncaso de confirmação do diagnóstico de NICII\n\nou NIC III, serão tratadas com conização.","B":"Mulheres que receberam a vacina tetravalente para HPV não precisam realizar exame\ncolpocitológico para rastreamento de câncer de colo do útero.","C":"As alterações citológicas causadas pelo HPV são denominadas coilocitose.","D":"Primeira relação sexual em idade jovem, múltiplos parceiros sexuais, tabagismo, paridade\nelevada, baixa condição socioeconômica e imunossupressão crônica são fatores de risco para\ndesenvolvimento do câncer de colo uterino.","E":"Pacientes diagnosticadas com NIC I têm altas taxas de regressão espontânea da doença em 2\nanos de acompanhamento ."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-188032","number":"188032","sourceNumber":"188032","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher, 26 anos, nulípara, com citologia de colo do útero de lesão intraepitelial de alto\ngrau, com colposcopia evidenciando JEC (junção escamo-celular) visível e achados sugestivos de\nlesão de alto grau. Qual é a conduta adequada?","options":{"A":"Seguimento com colposcopia e citologia a cada seis meses e, no agravo, realizar conização.","B":"Solicitação de hibridização para tipagem de sorotipo viral, que se for de baixo grau, assumir\nconduta expectante.","C":"Solicitação de hibridização para tipagem de sorotipo viral, que se confirmar de alto grau,\nassumir\nconduta ativa com conização clássica.","D":"Criocauterização interessando a JEC.","E":"Conização de colo por CAF (cirurgia de alta frequência)."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-172811","number":"172811","sourceNumber":"172811","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 31 anos de idade, assintomática, imunocompetente e sem comorbidades,\nprocura o ambulatório de ginecologia para\nfazer preventivo de colo uterino. Após 30 dias retorna\ncom resultado de colpocitologia oncótica, que evidenciou células escamosas atípicas de significado\nindeterminado, possivelmente não neoplásicas (ASC-US). Traz consigo também os últimos\nresultados dos colpocitológicos, sem sinais de malignidade, colhidos anualmente, nos últimos 2\nanos. De acordo com as Diretrizes Brasileiras de Rastreamento do Câncer de Colo Uterino,\nINCA/Ministério da Sáude/2016, a paciente deverá:","options":{"A":"Repetir a citologia em 3 anos.","B":"Repetir a citologia em 12 meses.","C":"Repetir a citologia em 6 meses.","D":"Realizar colposcopia."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-187482","number":"187482","sourceNumber":"187482","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Jovem de 22 anos com resultado de citologia oncótica do colo uterino de lesão de baixo\ngrau. A conduta mais apropriada para este caso:","options":{"A":"Genotipagem para HPV.","B":"Cauterização química ou elétrica.","C":"Repetição da citologia em 3 anos.","D":"Conização profilática.","E":"Exérese de toda a zona de transformação."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-187441","number":"187441","sourceNumber":"187441","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Idosa, pós menopausada com hipertensão, obesidade e diabetes melitus tipo 2. Iniciou\nquadro de sangramento vaginal e fez consulta ginecológica: dentre os exames solicitados foi\nidentificado endométrio espessado de 24mm, heterogêneo, com áreas císticas em permeio. A\nconduta mais assertiva para este caso seria:","options":{"A":"Histeroscopia diagnóstica;","B":"Teste da progesterona:","C":"Doppler de endométrio;","D":"Curetagem semiótica;","E":"Histerectomia vaginal;"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-155462","number":"155462","sourceNumber":"155462","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer de colo uterino ainda é um problema de saúde em todo o mundo. É também\nconsiderado um câncer evitável, pois seu estágio pré-invasor é longo. Sobre os aspectos que\nenvolvem essa doença, é INCORRETO afirmar:","options":{"A":"Entre os fatores de risco para desenvolvimento da doença podemos citar coitarca precoce,\nmúltiplos\n\nparceiros sexuais, paridade elevada e imunossupressão crônica.","B":"A infecção pelo HPV é responsável pela iniciação da displasia e pela carcinogênese cervical.\n\nEntre os subtipos de HPV associados ao câncer os mais importantes são os 16 e 18.","C":"Pacientes de 40 anos com exame colpocitológico mostrando lesão intraepitelial escamosa de\nalto grau devem ser encaminhadas para colposcopia com biópsia e, caso tenham o diagnóstico\nconfirmado, deverão ser submetidas a conização.","D":"O tipo histológico mais comum é o carcinoma de células escamosas, seguido do\nadenocarcinoma.","E":"O sintoma mais comum das pacientes com câncer de colo é a dor pélvica."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-148608","number":"148608","sourceNumber":"148608","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente do sexo feminino de 27 anos procura seu médico de família e comunidade\npara avaliação do resultado de seu exame\ncitopatológico do colo de útero de rotina. O exame\nmostrou lesão intraepitelial de baixo grau (LSIL), sendo que os exames anteriores estavam\nnormais. A paciente não apresenta em seu histórico nenhum problema que a coloque em uma faixa\nde maior risco para câncer de colo de útero. Considerando os protocolos do Ministério da Saúde do\nBrasil e a indisponibilidade do teste de DNA do HPV na rede de atenção à saúde local, qual a\nmelhor conduta a ser tomada neste caso?","options":{"A":"Estrogênio tópico, tratamento de eventual leucorreia e nova citologia em 15 dias.","B":"Repetição da citologia em seis meses.","C":"Repetição da citologia em três anos.","D":"Encaminhamento imediato para colposcopia.","E":"Histerectomia imediata."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-155389","number":"155389","sourceNumber":"155389","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 62 anos retorna ao seu consultório com resultado do colpocitológico de colo\nuterino com resultado ASC-H. Há 6 meses, apresentou outro preventivo com o mesmo resultado,\nquando foi orientada a realizar estrogenioterapia vaginal com creme de promestrieno. Foi\nsubmetida a colposcopia, quando não se visualizou totalmente a JEC. A conduta mais apropriada\npara este caso seria:","options":{"A":"Cauterização do colo.","B":"Conização diagnóstica.","C":"Troca do promestrieno por estriol creme vaginal.","D":"Histerectomia total.","E":"Biópsia ?às cegas?."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-155378","number":"155378","sourceNumber":"155378","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao tratamento do carcinoma epidermoide de colo de útero, assinale a\nalternativa ERRADA:","options":{"A":"IA1- <3mm invasão estromal e extensão <7mm. Se prole constituída: histerectomia radical. Sem\nprole ou desejo de engravidar: traquelectomia via vaginal. Paciente sem condições cirúrgicas:\nbraquiterapia.","B":"IA2- 3 a 5mm invasão estromal e extensão >7mm- Histerectomia total tipo II SEM\nlinfadenectomia pélvica e SEM biópsia de linfonodo sentinela.","C":"IB1- lesão <4cm ? Histerectomia total tipo II COM linfadenectomia pélvica.","D":"IB2- lesão de 2-4cm ? Histerectomia tipo III COM linfadenectomia pélvica.","E":"se a lesão tem <2cm e sem IAL, com desejo de manter fertilidade proceder a conização (IA2) ou\ntraquelectomia (IB1) com pesquisa de linfonodo sentinela ou linfadenectomia pélvica."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-162580","number":"162580","sourceNumber":"162580","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considerado método mais eficaz de rastreamento de lesões precursoras do câncer\nginecológico;","options":{"A":"Mamografia.","B":"Ultrassonografia Mamária.","C":"Ultrassonografia Endovaginal.","D":"Colpocitológico.","E":"Todas as afirmativas acima."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-137843","number":"137843","sourceNumber":"137843","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Sabemos que o câncer de colo de útero tem como causa a infecção pelo Papiloma\nVírus Humano (HPV) e que programas de\nrastreamento com uso de exame colpocitológico seguido\nde tratamento das lesões pré-invasoras são eficazes para redução da incidência desta neoplasia.\nAssinale a afirmativa INCORRETA:","options":{"A":"Colpocitolgia oncótica com resultado HSIL se refere a achado de atipias em células escamosas\ncompatíveis com lesões intraepiteliais escamosas de alto grau e a paciente deve ser encaminhada\npara colposcopia com biópsia dirigida.","B":"Pacientes com resultados de biópsia dirigida do colo uterino compatíveis com NIC II devem ser\nsubmetidas a tratamento excisional (conização).","C":"Pacientes com diagnóstico de NIC I acompanhadas por 2 anos sem tratamento apresentam\ntaxas de regressão espontânea entre 60-85%.","D":"A infecção pelo HPV foi detectada em até 99% das mulheres com carcinoma escamoso do colo\ndo útero e mais de 90% dos casos de NIC são atribuídos ao HPV. Entre os mais de 100 tipos de\nHPV existente os mais frequentemente encontrados nas situações mencionadas são os subtipos 6\ne 11.","E":"Já existem disponíveis para uso, vacinas contra HPV que protegem contra os subtipos 16 e 18 e\nque se mostraram eficazes na prevenção de\nNIC II e III."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-126885","number":"126885","sourceNumber":"126885","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao câncer do endométrio, assinale a alternativa CORRETA.","options":{"A":"O estádio I refere-se à invasão do tumor apenas no endométrio.","B":"O tratamento cirúrgico apenas é usualmente curativo em mulheres de baixo risco.","C":"A biópsia do linfonodo sentinela para o câncer do endométrio deverá ser realizada nos estádios\nII, III e IV da doença.","D":"O prognóstico do carcinoma de endométrio é determinado primariamente pelo estádio clínico e\npor sua histologia."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-127189","number":"127189","sourceNumber":"127189","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com relação ao câncer uterino é correto afirmar:","options":{"A":"A infecção pelo papiloma vírus humano (HPV) também é causa do câncer de endométrio.","B":"A minoria das pacientes com câncer endometrial necessita ser submetida a estadiamento\ncirúrgico.","C":"O câncer endometrial acomete igualmente mulheres no menacme e na pós-menopausa e sua\nvirulência aumenta com a idade.","D":"A sobrevida geral do câncer de endométrio em cinco anos é aproximadamente 30%.","E":"Em geral, os sarcomas uterinos formam o grupo mais maligno de tumores uterinos."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-127230","number":"127230","sourceNumber":"127230","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente com 28 anos apresentando citologia classe III de colo uterino com células\nescamosas atípicas sugerindo lesão de alto grau, foi submetida a colposcopia com epitélio\nacetobranco periorificial e biópsia que confirmou Neoplasia Intra-epitelial de Alto Grau. Qual a\nconduta indicada para essa paciente?","options":{"A":"Cauterização elétrica com margem de segurança.","B":"Conização do colo do útero.","C":"Cauterização com Ácido Tricloroacético.","D":"Histerectomia Total Abdominal.","E":"Criocauterização."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-131692","number":"131692","sourceNumber":"131692","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 40 anos, sexualmente ativa, encaminhada com os seguintes exames:\ncitologia do colo do útero: lesão\nintraepitelial de alto grau, Colposcopia: mosaico grosseiro. Biópsia\nde colo: carcinoma invasor do colo. A conduta é:","options":{"A":"Conização.","B":"Histerectomia total abominal.","C":"Cirurgia de Wertheim-Meigs.","D":"Radioterapia.","E":"Estadiamento."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-111598","number":"111598","sourceNumber":"111598","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Assinale a alternativa em que todos fatores relacionam-se ao risco de carcinoma de\nendométrio.","options":{"A":"Múltiplos parceiros, obesidade, menopausa tardia.","B":"Terapia estrogênica isolada, diabetes, anovulação crônica.","C":"Abortamentos de repetição com curetagem, multiparidade e SOP.","D":"Menopausa precoce, altas doses de tamoxifeno, multiparidade.","E":"Idade avançada, terapia hormonal com oposição estrogênica, uso de contraceptivos hormonais."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-102748","number":"102748","sourceNumber":"102748","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao câncer (Ca) do colo uterino, assinale a alternativa INCORRETA.","options":{"A":"A infecção pelo Papilomavírus Humano (HPV) é o evento causador do Ca de colo uterino, sendo\nprovável que o herpes-simples e a clamídia atuem como cofatores.","B":"O sinal mais importante no diagnóstico precoce da Ca de colo é o odor pútrido e a dispareunia.","C":"Na avaliação clínica da paciente com suspeita de Ca de colo, o toque retal está indicado com o\nobjetivo de estudar a extensão da doença.","D":"Em casos de doença macroscópica, a biópsia cervical, na maioria das vezes, é suficiente para o\ndiagnóstico."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-88881","number":"88881","sourceNumber":"88881","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Qual dos fatores abaixo relacionados NÃO é prognóstico no carcinoma de endométrio?","options":{"A":"Tipo histológico.","B":"Grau de diferenciação.","C":"Tamanho do útero.","D":"Citologia peritoneal.","E":"Invasão miometrial."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-88906","number":"88906","sourceNumber":"88906","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Quanto às vacinas disponíveis contra o Papilomavírus Humano (HPV), assinale a\nassertiva correta:","options":{"A":"Não está indicada para homens.","B":"Protegem apenas para lesões intraepiteliais de alto grau e câncer de colo uterino.","C":"Tem como público-alvo a população que ainda não foi exposta ao HPV.","D":"Está indicada em qualquer idade, desde que o último exame citológico do colo uterino tenha sido\nnormal.","E":"Exige reforço a cada 10 anos."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-77508","number":"77508","sourceNumber":"77508","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente com 28 anos, citologia classe III com células escamosas atípicas sugerindo\nlesão de alto grau, foi submetida à\ncolposcopia com epitélio acetobranco periorificial e biópsia que\nconfirmou neoplasia intraepitelial de alto grau. Qual a conduta indicada para essa paciente?","options":{"A":"Cauterização elétrica do colo uterino com margem de segurança.","B":"Conização do colo do útero.","C":"Ácido tricloroacético.","D":"Histerectomia total abdominal.","E":"Criocauterização."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-43944","number":"43944","sourceNumber":"43944","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação à epidemiologia do Carcinoma de Endométrio, é incorreto afirmar:","options":{"A":"É mais comum após 50 anos e raro antes dos 40 anos.","B":"É mais comum nas pacientes com menopausa tardia.","C":"É mais comum nas pacientes obesas, hipertensas e diabéticas.","D":"É mais comum nas pacientes que desenvolvem pólipos endometriais.","E":"É mais comum nas pacientes multíparas."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-27324","number":"27324","sourceNumber":"27324","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Qual propedêutica para lesões vulvares é mais importante para definir diagnóstico na\ndúvida entre benignidade e malignidade?","options":{"A":"Ácido acético","B":"Biópsia","C":"Vulvoscópia","D":"Teste Collens","E":"Citologia"},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-27328","number":"27328","sourceNumber":"27328","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 38 anos que apresenta resultados da citologia, da colposcópia e da biópsia\nque não guardam relação deve ser realizado.","options":{"A":"Nova citologia","B":"Amputação alargada do colo","C":"Curetagem do canal cervical","D":"Conização","E":"Histerectomia"},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-23095","number":"23095","sourceNumber":"23095","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"São fatores de risco para o desenvolvimento das hiperplasias do endométrio, exceto:","options":{"A":"Ciclos anovulatórios nos extremos da vida reprodutiva.","B":"Reposição hormonal com estrogênios associados a progestágenos de forma contínua.","C":"Obesidade.","D":"Síndrome dos ovários policísticos (anovulação crônica).","E":"Neoplasias ovarianas produtoras de estrogênio."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-23106","number":"23106","sourceNumber":"23106","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Quanto ao prognóstico das pacientes com Adenocarcinoma de Endométrio podemos\nafirmar, exceto:","options":{"A":"Quanto maior a idade, pior o prognóstico.","B":"Quanto maior o volume do útero, pior o prognóstico.","C":"Quanto mais indiferenciado, pior o prognóstico.","D":"Quanto maior a invasão miometrial, pior o prognóstico.","E":"Se houver comprometimento linfonodular, pior o prognóstico."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-8123","number":"8123","sourceNumber":"8123","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O colo uterino é revestido por várias camadas de células epiteliais pavimentosas,\narranjadas de forma ordenada. Quando ocorre\ndesordenação nas camadas mais basais do epitélio\nestratificado, estamos de frente a:","options":{"A":"neoplasia intraepitelial cervical grau I (NIC I).","B":"neoplasia intraepitelial cervical grau II (NIC II).","C":"neoplasia intraepitelial cervical grau III (NIC III).","D":"câncer invasor.","E":"Esta lesão não é considerada precursora de câncer."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-9407","number":"9407","sourceNumber":"9407","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Na pesquisa do câncer de endométrio:","options":{"A":"O teste Papanicolau é o melhor screening.","B":"O teste da progesterona não revela a patologia endometrial.","C":"A ultrassonografia transabdominal é o melhor método.","D":"A maioria das pacientes apresenta sangramento vaginal.","E":"A histeroscópia não identifica neoplasia endometrial."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-346422","number":"346422","sourceNumber":"346422","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao câncer do colo do útero, é correta a seguinte afirmação:","options":{"A":"o tabagismo não é um fator de risco pois recentemente se descobriu que a causa é a infecção\npelo HPV;","B":"o câncer do colo do útero pode se propagar por contiguidade, por continuidade por via linfática e\npor via hematogênica;","C":"o tipo histológico mais comum é o adenocarcinomamucinoso;","D":"a diferenciação entre ca in situ e invasivo só pode ser feita com a colposcopia e biópsia do\ncolo."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-331980","number":"331980","sourceNumber":"331980","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em colposcopia, a zona de transformação é a área:","options":{"A":"De epitélio metaplásico compreendida entre o epitélio original e o glandular.","B":"De epitélio glandular entre a junção escamocolunar e o orifício uterino.","C":"Endocervical onde pode ser encontrada a árvore da vida e os vasos atípicos.","D":"Patológica que permite a transformação neoplásica bacteriana."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-331986","number":"331986","sourceNumber":"331986","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O líquen escleroso é dermatose que acomete ambos os sexos e variadas faixas etárias.\nÉ mais frequente em:","options":{"A":"Mulheres jovens após a menarca.","B":"Meninas e adolescentes.","C":"Mulheres na perimenopausa.","D":"Mulheres na pós-menopausa.","E":"Mulheres no puerpério."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-339813","number":"339813","sourceNumber":"339813","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A fase do ciclo mais adequada para a realização da colposcopia é :","options":{"A":"a primeira fase.","B":"a segunda fase.","C":"o pré-menstrue.","D":"a pré-ovulatória."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-337451","number":"337451","sourceNumber":"337451","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher de 78 anos em consulta ginecológica de rotina, sem queixas, apresenta\nlaudo de ultrassom evidenciando endométrio\nde 17 mm. Nega fazer uso de terapia Hormonal e\nnega qualquer episódio de sangramento nos últimos anos. Nesse caso a melhor conduta é:","options":{"A":"Nada a fazer.","B":"Histeroscopia com biópsia.","C":"Curetagem uterina.","D":"Ressonância Nuclear Magnética."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-330124","number":"330124","sourceNumber":"330124","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A radioterapia é a modalidade de tratamento cujo agente terapêutico é a radiação\nionizante, ou seja, aquela que, em razão de\nsuas características físicas, tem a capacidade de\npromover ionização no meio em que incide, agindo sobre o controle da evolução local dos tumores.\nNo que se refere a esse tratamento, é CORRETO afirmar:","options":{"A":"As lesões tardias causadas pela radiação ionizante começam a surgir a partir de um ano após o\ntérmino do tratamento.","B":"A radioterapia não é indicada em casos de sangramentos provocados pelo tumor.","C":"A radiocirurgia é uma teleterapia de alta precisão tecnológica, indicada para tumores\ngastrintestinais.","D":"A braquiterapia é uma terapia em que a fonte radioativa é colocada dentro de uma cavidade\ncorporal ou diretamente no corpo, por meio de sementes, fios, agulhas ou fitas."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-334830","number":"334830","sourceNumber":"334830","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer de vulva é aquele que acomete predominantemente a pele dos lábios\nvulvares e, em menor proporção, pode se\noriginar do clitóris e das glândulas vestibulares. Qual é o\ntipo histológico mais frequente de câncer de vulva?","options":{"A":"Melanoma.","B":"Carcinoma escamoso.","C":"Tumor de célula basal.","D":"Adenocarcinoma."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-342662","number":"342662","sourceNumber":"342662","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com relação ao tratamento cirúrgico do câncer de colo de útero, é INCORRETO afirmar\nque:","options":{"A":"a histerectomia radical modificada (tipo II) difere da histerectomia (tipo III) por ter o\nligamento\ncardinal seccionado em sua porção medial","B":"a fístula ureterovaginal é uma das complicações da histerectomia radical","C":"a histerectomia radical videolaparoscópica nunca deve ser realizada no câncer de colo uterino","D":"para realizar a histerectomia radical, deve-se fazer a dissecação dos espaços paravesical e\npararretal"},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-334165","number":"334165","sourceNumber":"334165","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Ao longo da vida da mulher no menacme, o epitélio cilíndrico cervical é gradualmente\nsubstituído por epitélio escamoso. Esse processo tem o nome de:","options":{"A":"NIC.","B":"Metaplasia escamosa.","C":"Neoplasia escamosa.","D":"Câncer cervical in situ."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-334167","number":"334167","sourceNumber":"334167","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A doença de Paget vulvar é uma:","options":{"A":"inflamação.","B":"infecção.","C":"degeneração.","D":"neoplasia."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-334169","number":"334169","sourceNumber":"334169","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A complicação mais comum na conização com CAAF seguida de diatermocauterização\ndo colo uterino é:","options":{"A":"Estenose do canal cervical.","B":"Infecção.","C":"Sinéquia vaginal.","D":"Fistula vesicovaginal."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-334171","number":"334171","sourceNumber":"334171","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Na ausência de histeroscopia, o procedimento mais sensível para diagnóstico de\ncâncer de endométrio é:","options":{"A":"Ressonância magnética.","B":"Ultrassom endovaginal.","C":"Biópsia por aspiração.","D":"Exame de papanicolau."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-334173","number":"334173","sourceNumber":"334173","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em uma cirurgia de Wertheim-Meigs cursando com sangramento parametrial de difícil\ncontrole, o procedimento mais adequado é:","options":{"A":"Ligadura de infundibulo pélvico.","B":"Ligadura de artéria uterina.","C":"Ligadura de pudenda interna.","D":"Ligadura de ilíaca interna."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-321626","number":"321626","sourceNumber":"321626","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"No rastreamento do câncer de colo no Brasil, o Ministério da Saúde tem indicado que","options":{"A":"a citologia seja repetida com intervalo de 6 meses, em mulheres com idade superior a 30 anos,\ncom resultado mostrando ASC-US.","B":"a citologia pode ser realizada a cada cinco anos, entre a idade de 30 a 64 anos, desde que dois\nexames, com intervalos anuais, sejam negativos.","C":"o início do rastreamento seja realizado a partir de 25 anos de idade, em todas as mulheres que\niniciaram atividade sexual.","D":"o rastreamento com citologia em todas as mulheres com idade entre 25 a 64 anos, com\natividade sexual, em intervalos trienais."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-321627","number":"321627","sourceNumber":"321627","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A fase do ciclo mais adequada para a realização da colposcopia é","options":{"A":"a primeira fase.","B":"a segunda fase.","C":"o pré-menstrue.","D":"a pré-ovulatória."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-300896","number":"300896","sourceNumber":"300896","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer primário MAIS comum na gravidez é:","options":{"A":"colon.","B":"mama.","C":"linfoma.","D":"melanoma."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-308218","number":"308218","sourceNumber":"308218","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O laudo de uma paciente com 20 anos de idade apresentando Citologia oncótica de\nPapanicolau mostrou: Neoplasia intraepitelial de baixo grau (NIC I); Alterações citológicas\ncompatíveis com infecção pelo vírus HPV e processo inflamatório moderado; Qual a melhor\nconduta neste caso?","options":{"A":"Realizar cauterização cervical.","B":"Realizar biópsia do colo.","C":"Pesquisar o subtipo de HPV.","D":"Repetir a citologia oncótica em 6 meses."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-300906","number":"300906","sourceNumber":"300906","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente encaminhada ao ambulatório de colposcopia por diagnóstico de metaplasia\nescamosa em exame recente de papanicolaou. Tem 32 anos e laqueadura tubárea como método\nanticoncepcional. A conduta MAIS adequada nesse caso é:","options":{"A":"nada a fazer.","B":"colposcopia com biópsia dirigida.","C":"conização com margem de segurança.","D":"histerectomia."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-300912","number":"300912","sourceNumber":"300912","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em um laudo citopatológico, o encontro de células com alteração na relação\nnúcleo-citoplasma, halo perinuclear e multinucleação, faz o ginecologista pensar em:","options":{"A":"vaginose bacteriana.","B":"candidíase.","C":"infecção pelo HPV.","D":"câncer de colo uterino."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-300913","number":"300913","sourceNumber":"300913","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 29 anos, nuligesta, apresentando sangramento uterino irregular, submetida a\nhisteroscopia com biópsia que evidenciou hiperplasia complexa sem atipia. Planeja se casar e ter\nfilhos no futuro. O MELHOR tratamento no momento é:","options":{"A":"ablação de endométrio.","B":"histerectomia total.","C":"DIU de cobre.","D":"progestágeno contínuo."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-302849","number":"302849","sourceNumber":"302849","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 29 anos de idade refere ir ao ginecologista todo ano, com exames\ncitopatológicos cervicovaginais normais, desde os 25\nanos de idade. Na última consulta, recebeu\nlaudo do exame citopatológico com resultado ASC-US. Segundo as Diretrizes Brasileiras para o\nRastreamento do Câncer de Colo do Útero (2016), médico deve orientá-la a:","options":{"A":"Coletar secreção vaginal para cultura e bacterioscopia.","B":"Repetir o exame em 6 meses.","C":"Fazer colposcopia com biópsia.","D":"Repetir o exame em 12 meses.","E":"Coletar endocervical para pesquisa de gonococo."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-302852","number":"302852","sourceNumber":"302852","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 43 anos de idade apresenta carcinoma espinocelular do colo do útero,\nestágio FlGO lb. Foi realizada cirurgia de Wertheim-Meigs, com preservação dos ovários. O\nresultado anatomopatológico da peça mostrou margens vaginais livres, linfonodos negativos e\ninfiltração dos paramétrios laterais por neoplasia, porém com margens cirúrgicas livres de\nneoplasia. A conduta subsequente deve ser:","options":{"A":"Ooforectomia bilateral.","B":"Quimioterapia adjuvante.","C":"Radioterapia pélvica.","D":"Exenteração pélvica anterior.","E":"Seguimento clínico mensal com citologia e colposcopia."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-317181","number":"317181","sourceNumber":"317181","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Segundo a nomenclatura brasileira para laudos citopatológicos cervicais, são\nconsideradas alterações celulares benignas, exceto:","options":{"A":"inflamação.","B":"escamosas.","C":"atrofia com inflamação.","D":"metaplasia escamosa imatura."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-314135","number":"314135","sourceNumber":"314135","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Excluindo-se a terapia estrogênica sem a oposição progestagênica, a principal causa\nde câncer de endométrio é","options":{"A":"a síndrome dos ovários policísticos.","B":"a obesidade.","C":"a nuliparidade.","D":"o tabagismo."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-316339","number":"316339","sourceNumber":"316339","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Dos listados abaixo, qual o tipo de HPV responsável pela forma mais comum de câncer\ncervical invasivo, neoplasia intraepitelial NIC 2 e NIC 3?","options":{"A":"16.","B":"56.","C":"32.","D":"18."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-317187","number":"317187","sourceNumber":"317187","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A vacina quadrivalente do HPV (tipos 6, 11, 16 e 18) é usada para prevenção de: I.\nCâncer Anal. II. Câncer Vaginal. III. Câncer de Colo Uterino. IV. Câncer de Vulva. Está(ão)\ncorreta(s) a(s) alternativa(s):","options":{"A":"III, apenas.","B":"I, II, III e IV.","C":"I e IV, apenas.","D":"II, III e IV, apenas."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-317195","number":"317195","sourceNumber":"317195","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Um tumor vaginal maligno de crianças jovens que se apresenta clinicamente como uma\nmassa de pólipos edematosos tipo cachos de\nuva é:","options":{"A":"Vaginite enfisematosa","B":"Carcinoma de células escamosas","C":"Sarcoma botrióide","D":"Adenocarcinoma"},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-317196","number":"317196","sourceNumber":"317196","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher de 43 anos tem um Papanicolau suspeito e um exame pélvico normal. A\nbiopsia dirigida por colposcopia de uma cérvice de aparência normal revela carcinoma invasivo. O\npróximo passo no cuidado da paciente deveria ser:","options":{"A":"Avaliação metastática","B":"Conização","C":"Histerectomia radical","D":"Radioterapia"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-317197","number":"317197","sourceNumber":"317197","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O fator mais indicativo de câncer invasivo ao exame colposcópico é:","options":{"A":"Epitélio branco","B":"Leucoplasia","C":"Vasos sanguíneos atípicos","D":"Lesões puntiformes"},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-317978","number":"317978","sourceNumber":"317978","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Segundo o Ministério da Saúde, uma mulher de 29 anos de idade, com dois exames de\ncitologia oncótica negativos, em intervalos de um ano, deverá ser orientada a realizar uma nova\ncitologia oncótica a cada","options":{"A":"ano.","B":"dois anos.","C":"três anos.","D":"quatro anos."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-313241","number":"313241","sourceNumber":"313241","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com relação ao câncer do endométrio, assinale a alternativa correta:","options":{"A":"o tipo endometrioide em geral tem prognóstico melhor","B":"o estadiamento é melhor realizado pela histeroscopia","C":"pelos critérios de Rotterdam, quando o eco endometrial for maior que 5mm e a paciente tiver\nsangramento genital, no mínimo, tem-se estádio ll da neoplasia","D":"seus principais fatores de risco são: obesidade, hipertensão arterial, tabagismo e uso prévio de\nanticoncepcional hormonal combinado"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-294311","number":"294311","sourceNumber":"294311","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A vacina quadrivalente contra o HPV","options":{"A":"constitui a principal ação de prevenção primária.","B":"não confere imunidade permanente.","C":"não previne contra o câncer vulvar.","D":"está contraindicada em mulheres que estão com o HPV."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-300862","number":"300862","sourceNumber":"300862","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O exame citopatológico consiste em um método simples, indolor, rápido e de baixo\ncusto capaz de detectar alterações da cérvice uterina, a partir da descamação de células do\nepitélio. É o método mais adequado para o rastreamento do câncer uterino. Considerando o\ncontexto, NÃO devem ser incluídas no rastreamento as mulheres submetidas à:","options":{"A":"Histerectomia total por outras razões que não o câncer do colo do útero.","B":"Histerectomia supracervical.","C":"Histerectomia total por lesão precursora.","D":"Histerectomia por câncer do colo do útero."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-313245","number":"313245","sourceNumber":"313245","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher de 38 anos, que apresentou HPV no passado, encontra-se em seguimento\nna Unidade de Saúde e realizou colpocitologia\noncótica que revelou NIC III. Foi solicitada\ncolposcopia, que não mostrou nenhuma lesão, e foi classificada como insatisfatória por não expor a\nJEC. Qual é a conduta a ser tomada:","options":{"A":"uso de estrogênio e repetição dos exames","B":"biópsia em 4 quadrantes","C":"histerectomia total","D":"investigação do canal cervical"},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-300872","number":"300872","sourceNumber":"300872","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considere a realização de esfregaço de Papanicolaou em paciente do sexo feminino,\n38 anos, que mostra HSILs. Nesse contexto, caso\numa curetagem endocervical mostre displasia\ncervical:","options":{"A":"Então é recomendada citologia de rotina.","B":"Então não é necessária mais nenhuma análise.","C":"Se o Papanicolaou revelar apenas HSIL, então o câncer cervical é altamente improvável.","D":"Então um procedimento excisional do colo uterino é adequado."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-274440","number":"274440","sourceNumber":"274440","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher de 45 anos é diagnosticada com câncer cervical inicial, confinado ao colo\nuterino e com cerca de 3 cm de diâmetro. Ela pergunta como desenvolveu essa condição. Das\nalternativas seguintes qual é um fator de risco de câncer cervical?","options":{"A":"Idade precoce da relação sexual.","B":"Nuliparidade.","C":"Obesidade.","D":"História familiar de câncer cervical."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-274444","number":"274444","sourceNumber":"274444","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Ao realizar uma colposcopia, observa-se uma área de leucoplasia. A embrocação desta\nárea com lugol, mostrará, através do teste\nde Schiller, um resultado:","options":{"A":"Positivo - iodo positivo.","B":"Negativo - iodo positivo.","C":"Positivo - iodo negativo.","D":"Negativo - iodo negativo."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-274780","number":"274780","sourceNumber":"274780","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 45 anos, G3 P3 e laqueadura tubárea, traz para a consulta o laudo de\ncolpocitologia oncótica com LIEAG (lesão intraepitelial de alto grau). Em relação à sequencia\ndiagnóstica e terapêutica você informa que:","options":{"A":"deve ser feito a histerectomia, pois a paciente já tem prole definida.","B":"indicar conização com cirurgia de alta frequência, ver e tratar.","C":"deve ser feito a repetição do preventivo em 3 meses.","D":"indicar colposcopia com biópsia, para confirmar o diagnóstico."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-282000","number":"282000","sourceNumber":"282000","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"No caso da paciente A.J.S, de 34 anos, com diagnóstico de líquen vulvar crônico\nsimples, qual das seguintes alternativas abaixo representa o tratamento de escolha para o seu\ncaso?","options":{"A":"Creme de clotrimazol 10 mg/g.","B":"Prednisona oral, 10 mg/dia.","C":"Metronidazol oral ou tópico.","D":"Pomada de propionato de clobetasol 0,05%."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-282002","number":"282002","sourceNumber":"282002","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A recomendação do Ministério da Saúde, no Brasil, para o rastreamento do câncer de\ncolo uterino, é:","options":{"A":"A partir de 16 anos, uma vez por ano e, após três exames anuais consecutivos negativos, a\ncada dois anos.","B":"A partir de 20 anos, uma vez por ano e, após um exame negativo, a cada dois anos.","C":"A partir de 22 anos, uma vez por ano e, após três exames anuais consecutivos negativos, a\ncada dois anos.","D":"A partir de 25 anos, uma vez por ano e, após dois exames anuais consecutivos negativos, a\ncada três anos."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-282004","number":"282004","sourceNumber":"282004","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao câncer de endométrio, é correto afirmar que:","options":{"A":"O diagnóstico histológico é padrão-ouro e assertivo em todos os casos.","B":"A ultrassonografia transvaginal não é aceita como método de rastreamento.","C":"A histeroscopia com biópsia dirigida é o melhor método para avaliação da cavidade uterina.","D":"A curetagem pós-dilatação é o método mais assertivo, pois coleta todo o material do endométrio."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-277439","number":"277439","sourceNumber":"277439","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma nuligesta de 27 anos, queixando-se de corrimento sanguinolento com odor fétido\nhá 2 meses, não visita o ginecologista há\n5 anos. Iniciou a atividade sexual há 10 anos. Ao exame\nespecular, evidenciaram-se lesão vegetante acometendo o lábio posterior do colo uterino com\ncerca de 3cm de diâmetro e paredes vaginais livres de acometimento. O toque retal mostra\ncomprometimento do paramétrio à direita até a parede pélvica. Demais exames de estadiamento\nforam negativos. A histologia da lesão mostrou adenocarcinoma invasivo moderadamente\ndiferenciado. Com relação ao caso, o estadio do tumor e a melhor conduta terapêutica são,\nrespectivamente:","options":{"A":"IIIB radioquimioterapia","B":"IB1 cirurgia de Wertheim-Meigs","C":"IB2 radioterapia exclusiva","D":"IIA cirurgia de Wertheim-Meigs"},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-282005","number":"282005","sourceNumber":"282005","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher multípara, após fazer seus exames de rotina ginecológica, apresentou resultado\nde biópsia dirigida por colposcopia positiva que\nrevelou NIC lll. Qual a conduta?","options":{"A":"Criocauterização.","B":"Cirurgia de alta frequência.","C":"Conduta expectante e revisão em 6 meses.","D":"Histerectomia."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-281302","number":"281302","sourceNumber":"281302","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 36 anos com diagnóstico de câncer de colo uterino estádio IB1. A melhor\nconduta nesse caso é:","options":{"A":"Histerectomia radical com linfadenectomia pélvica.","B":"Histerectomia simples.","C":"Conização.","D":"Radioterapia."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-258209","number":"258209","sourceNumber":"258209","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O útero é um órgão ímpar, oco, situado na pelve, apresentando paredes musculares\ngrossas e contráteis. Tem variação de forma\ne tamanho, em função da idade, fase reprodutiva e\nparidade. Em relação ao útero, sabe-se que:","options":{"A":"apresenta-se em forma arredondada e em retroversoflexão, mais frequentemente.","B":"as dimensões habituais na mulher adulta não grávida são de 15 a 20 cm de comprimento e 25 a\n30 cm de largura.","C":"é dividido em fundo, corpo, istmo e colo.","D":"o fundo de saco de Douglas situa-se entre o útero e a bexiga."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-258211","number":"258211","sourceNumber":"258211","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A colpocitologia oncológica é o estudo das células esfoliadas cervicovaginais, utilizada\npara o rastreamento do câncer de colo do\nútero. A coleta, o preparo e a interpretação da lâmina\ndevem obedecer aos critérios de qualidade e a classificação vigente. É um exemplo de critério para\no diagnóstico em patologia cervical:","options":{"A":"o achado de células escamosas e glandulares, na amostra, são considerados dentro dos limites\nda normalidade do material examinado.","B":"o encontro de epitélio metaplásico é um achado anormal no exame colpocitológico.","C":"as células atípicas de significado indeterminado são as escamosas (AGC) e as glandulares\n(ASC-US).","D":"a lesão intraepitelial de baixo grau compreende o NIC graus II e III."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-257776","number":"257776","sourceNumber":"257776","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao rastreamento de câncer de colo uterino, o Ministério da Saúde\nrecomenda que mulheres","options":{"A":"histerectomizadas não necessitam ser rastreadas.","B":"que nunca tiveram atividade sexual não necessitam ser rastreadas.","C":"na pós-menopausa não necessitam ser rastreadas.","D":"com HIV não necessitam de rastreio diferente que as demais mulheres."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-252724","number":"252724","sourceNumber":"252724","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"São fatores de risco para câncer do colo do útero:","options":{"A":"Multiplicidade de parceiros sexuais, obesidade e tabagismo.","B":"Início precoce da atividade sexual, preservativo como método anticoncepcional e multiparidade.","C":"Tabagismo, uso da terapêutica de reposição hormonal da pós-menopausa e nuliparidade.","D":"Tabagismo, antecedente pessoal de doença sexualmente transmissível e imunodeficiência."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-249482","number":"249482","sourceNumber":"249482","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A sinéquia vulvar ou aglutinação labial é uma condição benigna, comum nas meninas,\nmas que costuma causar preocupação nos pais.\nDas alternativas abaixo, assinale aquela que não\nrepresenta uma possível causa de sinéquia.","options":{"A":"Traumatismos repetitivos.","B":"Higiene inadequada.","C":"Hímen imperfurado.","D":"Infecções locais."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-249881","number":"249881","sourceNumber":"249881","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Segundo orientações do Ministério da Saúde e do Instituto Nacional do Câncer (INCA),\numa mulher de 30 anos, com exames preventivos\nde câncer de colo uterino negativos para\nmalignidade, por dois anos seguidos, deverá realizar nova prevenção após:","options":{"A":"Três anos.","B":"Dois anos.","C":"Um ano.","D":"Seis meses."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-254262","number":"254262","sourceNumber":"254262","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 40 anos, com prole constituída, com diagnóstico de adenocarcinoma in situ\nde colo uterino com margens livres em conização. Qual é a próxima conduta?","options":{"A":"Quimioterapia exclusiva.","B":"Cirurgia de Wertheim.","C":"Radioterapia exclusiva.","D":"Histerectomia simples."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-254263","number":"254263","sourceNumber":"254263","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer de colo uterino pode-se propagar diretamente por continuidade e por\ncontiguidade. A propagação indireta será:","options":{"A":"Para paramétrios.","B":"Por via linfática e hemática.","C":"Pare bexiga e reto.","D":"Para paracolpos."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-246582","number":"246582","sourceNumber":"246582","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 46 anos de idade, peso 84 kg, 1,58 m de altura, apresenta ciclos menstruais\nlongos e fluxo aumentado. Identificado\nespessamento endometrial ao exame ultrassonográfico.\n\nBiópsia obtida por meio de histeroscopia revelou aumento do número e do tamanho de glândulas,\nproliferação irregular, com presença de atipias nucleares. A melhor conduta terapêutica é:","options":{"A":"ablação endometrial.","B":"histerectomia total.","C":"uso de progestínico por via oral.","D":"contraceptivo hormonal combinado.","E":"inserção de dispositivo intrauterino liberador de levonorgestrel."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-246588","number":"246588","sourceNumber":"246588","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 23 anos comparece à consulta para avaliação de exame citopatológico do\ncolo uterino, cujo resultado evidencia células escamosas atípicas de significado indeterminado\n(ASCUS), possivelmente não neoplásicas. De acordo com as Diretrizes Brasileiras para o\nrastreamento do câncer de colo do útero do Ministério da Saúde, qual a melhor conduta para a\npaciente?","options":{"A":"Repetir o exame em doze meses.","B":"Repetir o exame em três anos.","C":"Repetir o exame em seis meses.","D":"Realizar biópsia do colo uterino.","E":"Encaminhar para colposcopia."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-246589","number":"246589","sourceNumber":"246589","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 42 anos, G3Pn3A0, ciclos menstruais regulares, laqueada, queixando-se de\nsangramento vaginal após as relações sexuais, há um ano. Há um mês referindo corrimento vaginal\ncom odor fétido e dispareunia. Ao exame ginecológico, visualizada tumoração exofítica, ulcerada,\nfriável, em colo uterino, de aproximadamente 4 cm de diâmetro, paredes vaginais e paramétrios\nlivres. Realizada biópsia de colo, evidenciando carcinoma de células escamosas. Considerando o\nestadiamento clínico para essa paciente, assinale a alternativa com o tratamento mais indicado.","options":{"A":"Traquelectomia.","B":"Histerectomia simples, com preservação de trompas e ovários.","C":"Histerectomia radical com linfadenectomia pélvica.","D":"Quimioterapia.","E":"Braquiterapia."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-241762","number":"241762","sourceNumber":"241762","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 58 anos realiza biópsia endometrial, que demonstra carcinoma\nendometrioide bem diferenciado. Em relação a\ntal situação, julgue os itens a seguir. I. O tratamento\nnecessariamente inclui panhiterectomia. II. Está indicada radioterapia pós-operatória. III. O\nestadiamento é sempre cirúrgico. Pode se afirmar que:","options":{"A":"apenas o item I está correto.","B":"apenas o item II está correto.","C":"apenas os itens I e III estão corretos.","D":"apenas o item III está correto.","E":"todos os itens estão corretos."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-241763","number":"241763","sourceNumber":"241763","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 40 anos, obesa, prole definida, com hipermenorreia há seis meses,\nrealizou histeroscopia com biópsia, cujo laudo\nhistopatológico é de hiperplasia epitelial atípica. Qual\na melhor abordagem para o caso?","options":{"A":"Histerectomia total.","B":"Esquema cíclico mensal de progesterona na segunda fase.","C":"Emprego de anovulatório oral.","D":"Anticoncepcional oral do tipo progesterona contínuo.","E":"Injetável trimestral."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-249537","number":"249537","sourceNumber":"249537","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em uma paciente de 52 anos com diagnóstico de hiperplasia endometrial atípica,\nassinale a alternativa correta:","options":{"A":"O tratamento medicamentoso exclusivo só deve ser oferecido se a paciente não tiver condições\ncirúrgicas.","B":"Pode ser tratada com DIU de prata e repetir ultrassom em 3 meses.","C":"Pode ser tratada com pílula de levonorgestrel e repetir ultrassom em 3 meses.","D":"Pode ser tratada com raloxifeno e acompanhada com ultrassom a cada 3 meses."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-229570","number":"229570","sourceNumber":"229570","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O sinal/sintoma MAIS frequente encontrado em quadros de câncer de endométrio é:","options":{"A":"dor pélvica.","B":"tenesmo.","C":"sangramento via vaginal.","D":"dispareunia."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-229896","number":"229896","sourceNumber":"229896","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Assinale a resposta que melhor corresponde aos fatores de risco para o câncer de\nendométrio:","options":{"A":"Multiparidade, obesidade, menopausa precoce, terapia de reposição com estrogênio.","B":"Multiparidade, obesidade, menopausa tardia, terapia de reposição com estrogênio.","C":"Nulipariedade, obesidade, menopausa tardia, terapia com reposição de estrogênio.","D":"Nulipariedade, obesidade, menopausa precoce, terapia com reposição de estrogênio."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-214134","number":"214134","sourceNumber":"214134","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Sabendo-se que existem mais de 200 tipos de vírus HPV, e que aproximadamente 40\nsão responsáveis por infecções genitais, os mais\nfrequentemente relacionados ao desenvolvimento\nde câncer de colo uterino são:","options":{"A":"6, 11","B":"20 ,22","C":"16, 18","D":"14, 19"},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-214178","number":"214178","sourceNumber":"214178","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente procura o ginecologista para avaliação de resultado de exame de Papanicolau\n(COP), que indicou lesão intraepitelial de\nalto grau (LIEAG). Neste caso a consuta inicial adequada\né realizar a:","options":{"A":"Conização.","B":"Colposcopia com Biópsia do colo uterino.","C":"Colpocitologia após 3 meses.","D":"Cauterização química no local."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-218245","number":"218245","sourceNumber":"218245","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Onde se localizam os cistos de Naboth?","options":{"A":"Na vulva.","B":"Na vagina.","C":"No colo do útero.","D":"Nos ovários."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-216443","number":"216443","sourceNumber":"216443","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente com 28 anos, Gesta III para III, com ligadura tubária, fez exame preventivo de\nrotina na Clínica Escola da Faculdade de Medicina. Relava que havia 3 anos que não realizava\nseus exames de rotina ginecológica. No momento da consulta, não apresentava queixas do ponto\nde vista ginecológico. O resultado foi lesão intraepitelial escamosa de alto grau (HSIL). A conduta\nadequada é:","options":{"A":"Histerectomia.","B":"Conização.","C":"Exérese de zona de transformação.","D":"Colposcopia."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-216531","number":"216531","sourceNumber":"216531","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Os carcinomas do endométrio são neoplasias malignas considerados:","options":{"A":"O segundo tipo de neoplasias invasoras mais comum encontrado no trato genital feminino.","B":"Tumores do tipo I - de baixo grau e geralmente indolentes - e os do tipo II - agressivos e de\nalto\ngrau, com prognóstico desfavorável.","C":"Tumores precedidos de hiperplasia atípica que apresentam mutações no gene TP53, e que\npodem, ainda, ser identificados nas lesões precursoras.","D":"Os carcinomas do tipo II, associados ao carcinoma intraepitelial endometrioide seroso e suas\nmutações mais encontradas são: a PTEN, a PIK3CA, a KRAS e a ARIDIA."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-216630","number":"216630","sourceNumber":"216630","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Dentre os tumores malignos do corpo do útero, o câncer de endométrio representa\ncerca de 90% das neoplasias, sendo que a\nincidência dos sarcomas varia entre 1% a 8% na\nliteratura. Sobre os tumores do corpo do útero, verifica-se que:","options":{"A":"O câncer de endométrio é uma neoplasia ginecológica que nos países desenvolvidos está\napresentando uma diminuição na sua incidência.","B":"O comprometimento linfonodal é o fator prognóstico mais importante.","C":"O câncer de endométrio tipo II é classificado histologicamente como adenocarcinoma\nendometrioide e tem como fator de risco a obesidade.","D":"O estadiamento do câncer de endométrio é clínico."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-216522","number":"216522","sourceNumber":"216522","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O fator de risco mais importante para desenvolvimento de lesões pré-neoplásicas e de\ncarcinoma invasor do colo do útero é:","options":{"A":"Uso prolongado de tamoxifeno para tratamento de câncer de mama.","B":"Uso de anticoncepcionais orais ou injetáveis.","C":"Presença de doença imunossupressora em paciente gestante.","D":"Infecção pelo papiloma vírus humano."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-201667","number":"201667","sourceNumber":"201667","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"É considerado fator de risco para câncer de endométrio:","options":{"A":"Menarca tardia.","B":"Multiparidade.","C":"Índice de massa corporal abaixo de 25.","D":"Terapia estrogênica sem progestágeno."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-210601","number":"210601","sourceNumber":"210601","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Entre os achados no exame de colposcopia, não é caracterizado como miscelânea:","options":{"A":"zona de tranformação congênita","B":"condiloma","C":"pópilo","D":"mosaico","E":"endometriose"},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-217008","number":"217008","sourceNumber":"217008","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 56 anos, G4Pn4A0, menopausa aos 49 anos, sem terapia hormonal.\nCitologias irregulares. Comparece em consulta\nmédica com queixa de sangramento vaginal\nrecorrente. Ao exame clínico, evidenciada lesão endurecida em colo com 6 cm de diâmetro,\nacometimento de paredes vaginais em terço superior e paramétrios bilateralmente, sem invasão de\nmucosa retal. Realizada biópsia de lesão, que evidenciou carcinoma de células escamosas.\n\nAssinale a alternativa que compreende o estadiamento da doença baseado no exame clínico.","options":{"A":"IB1.","B":"IB2.","C":"IIA.","D":"IIB.","E":"IVA."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-214942","number":"214942","sourceNumber":"214942","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma paciente de 25 anos comparece à consulta com resultado de preventivo\nevidenciando metaplasia escamosa. A conduta adotada é:","options":{"A":"conização clássica","B":"colposcopia e biópsia","C":"cirurgia de alta frequência","D":"acompanhamento citológico de rotina"},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-201712","number":"201712","sourceNumber":"201712","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com referência ao câncer de colo uterino:","options":{"A":"A realização de rastreamento citológico faz-se necessário devido às caracterìsticas da evolução\nde suas lesões precursoras.","B":"A colposcopia está indicada quando forem encontradas anormalidades citológicas.","C":"Uma minoria dos casos relaciona-se à infecção por HPV, razão pela qual o uso de preservativos\nnas relações sexuais levou à redução do número\ndeste tipo de câncer.","D":"O aumento do número de casos diagnosticados de câncer de mama e de pele fez com que esse\ntipo deixasse de ser um problema de saúde pública."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-217031","number":"217031","sourceNumber":"217031","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 34 anos apresenta-se em consulta médica com citologia evidenciando\ncélulas escamosas atípicas de significado indeterminado,\npossivelmente não neoplásicas\n\n(ASC-US). Segundo as diretrizes de 2016 do Ministério da Saúde para rastreamento do câncer de\ncolo uterino, qual a melhor conduta nesse caso?","options":{"A":"Nova citologia em 12 meses.","B":"Nova citologia em 6 meses.","C":"Realização de colposcopia.","D":"Biópsia de colo uterino.","E":"Nova citologia imediata."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-205645","number":"205645","sourceNumber":"205645","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em uma colposcopia são observadas as seguintes características: área de mosaico\nplano em zona de transformação atípica, com teste de Schiller positivo (iodo negativo). A mais\nprovável causa é:","options":{"A":"CA in situ.","B":"NIC I.","C":"CA microinvasivo.","D":"Metaplasia escamosa."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-202629","number":"202629","sourceNumber":"202629","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Leia o caso clínico a seguir. Mulher de 42 anos, G3, P3, três partos normais,\nlaqueadura há 20 anos, foi submetida a\nhisteroscopia diagnóstica por apresentar sangramento\nuterino anormal e espessamento endometrial na ultrassonografia. O resultado do histopatológico\nmostrou hiperplasia endometrial simples, sem atipias. Diante deste quadro, o tratamento é:","options":{"A":"histerectomia.","B":"ablação de endométrio.","C":"progestágeno.","D":"leuprorrelina."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-205663","number":"205663","sourceNumber":"205663","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A imagem colposcópica mais sugestiva de câncer de colo uterino é:","options":{"A":"Orifícios glandulares espessados.","B":"Vasos atípicos.","C":"Mosaico.","D":"Zona de transformação típica."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-210543","number":"210543","sourceNumber":"210543","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considere o seguinte caso: T.C.L, 38 anos, branca, G2PN2A0, histerectomizada por\nleiomiomatose uterina com menorragia refratária a tratamento clínico, sexualmente inativa há 3\nmeses, sem comorbidades, história familiar de mãe com câncer de mama na pré-menopausa; essa\npaciente chega ao consultório para exame de rotina. Está assintomática. Qual a conduta mais\ncorreta seguindo os protocolos do Ministério da Saúde?","options":{"A":"Exame clínico completo e coleta de colpocitologia.","B":"Exame clínico completo, solicitação de ultrassonografia de mamas e coleta de colpocitologia.","C":"Exame clínico completo, solicitação de ultrassonografia das mamas e orientação sobre a não\nnecessidade de coleta de colpocitologia.","D":"Exame clínico completo, solicitação de mamografia e orientação sobre a não necessidade de\ncoleta de colpocitologia.","E":"Exame clínico completo, solicitação de mamografia e coleta de colpocitologia."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-214150","number":"214150","sourceNumber":"214150","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Márcia, 50 anos, dona-de-casa, vem à consulta de revisão com seu médico de família.\nRelata que nos últimos meses tem apresentado episódios de calorões e insônia. Descreve\nepisódios súbitos de calor localizado em tórax superior e face, associados à sudorese profusa e\nintenso desconforto. Já teve o sono interrompido durante a noite por esses episódios e,\nultimamente, ao preparar-se para dormir, já imagina que irá acordar com esses sintomas. Algumas\nvezes, também fica acordada para esperar a filha voltar do curso noturno. Está preocupada com a\ndoença do pai, que tem enfisema e recentemente teve indicação e oxigenioterapia domiciliar.\n\nEmociona-se ao fazer este relato. Questionada, refere que há 4 meses não menstrua e, antes\ndisso, os ciclos estavam irregulares.\nPergunta ao médico se pode estar na menopausa. Menciona\nque a irmã mais velha disse que \"isso faz parte da idade\" e que ela \"irá se acostumar\". Reside com\nesposo e os três filhos mais novos. A filha mais velha é casada e tem filhos gêmeos de 2 anos, que\nsão cuidados por Márcia no turno da tarde. Nega desavenças ou problemas familiares, admitindo\napenas \"preocupações\". Apresenta sobrepeso e fez colecistectomia há 5 anos. A mãe é hipertensa\ne a tia paterna faleceu por câncer de mama. Questiona médico sobre a necessidade de dosagens\nhormonais e realização de densitometria óssea. Refere que \"quer fazer tudo o que for possível para\nviver bem na velhice\". Não é uma contraindicação à terapia hormonal a:","options":{"A":"Históra de câncer de mama.","B":"História de tromboembolismo venoso.","C":"Doença hepática em atividade.","D":"Migrânea."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-205563","number":"205563","sourceNumber":"205563","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Qual o tumor ginecológico mais comum durante a gravidez?","options":{"A":"Câncer de colo uterino.","B":"Câncer de mama.","C":"Câncer de ovário.","D":"Câncer de endométrio."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-214155","number":"214155","sourceNumber":"214155","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"São considerados fatores de risco para neoplasia de colo uterino:","options":{"A":"início precoce da atividade sexual, uso prolongado de contraceptivos orais, tabagismo e\nimunossupressão.","B":"baixas condições socioeconômicas e culturais, início tardio das atividades sexuais, tabagismo e\nelitismo.","C":"infecção pelo HPV, vaginoses de repetição, multiplicidade de parceiros e não uso de\ncontraceptivos orais.","D":"uso prolongado de contraceptivos orais, adicção, multiplicidade de parceiros e imunossupressão."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-214157","number":"214157","sourceNumber":"214157","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Nos casos de lesão de baixo grau e ASC-US em uma mulher de 35 anos, o profissional\ndeve:","options":{"A":"Encaminhar para colposcopia nos dois casos.","B":"Repetir o exame citopatológico em seis meses nos dois casos.","C":"Repetir o exame citopatolóligo em seis meses no primeiro caso e encaminhar para colposcopia\nno segundo.","D":"Encaminhar para colposcopia no primeiro caso e repetir o citopatológico em seis meses no\nsegundo."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-215445","number":"215445","sourceNumber":"215445","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O HPV está envolvido em aproximadamente 100% dos casos de câncer cervical, com\npercentual menor em outros locais. Está INCORRETO que se afirma em:","options":{"A":"Aproximadamente 1% a 2% da população apresentam verrugas genitais e 2% a 5% das\nmulheres apresentam alterações do Papanicolaou provocadas por infecção pelo HPV.","B":"A prevalência é menor em mulheres jovens, quando comparadas com mulheres com mais de 30\nanos.","C":"A maioria das infecções por HPV em mulheres (sobretudo quando adolescentes) tem resolução\nespontânea, em um período aproximado de 24 meses.","D":"Nos homens, a prevalência se mantém constante nas diversas faixas etárias"},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-215434","number":"215434","sourceNumber":"215434","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O HPV está envolvido nos casos de câncer cervical, a infecção persistente por tipos\noncogênicos de HPV está associada ao maior risco de desenvolver lesão intraepitelial escamosa\n(neoplasia intraepitelial do colo uterino ? NIC). Sobre isso, podemos aceitar que:","options":{"A":"O tempo médio entre a infecção pelo HPV de alto risco e o desenvolvimento do câncer cervical é\nde aproximadamente 20 anos, de acordo com o tipo, a\ncarga e a capacidade de persistência viral, e\no estado imunológico do hospedeiro.","B":"O tempo médio entre a infecção pelo HPV de alto risco e o desenvolvimento do câncer cervical é\nde aproximadamente 10 anos, de acordo com o tipo, a\ncarga e a capacidade de persistência viral, e\no estado imunológico do hospedeiro.","C":"O tempo médio entre a infecção pelo HPV de alto risco e o desenvolvimento do câncer cervical é\nde aproximadamente 30 anos, de acordo com o tipo, a\ncarga e a capacidade de persistência viral, e\no estado imunológico do hospedeiro.","D":"O tempo médio entre a infecção pelo HPV de alto risco e o desenvolvimento do câncer cervical é\nde aproximadamente 20 anos, de acordo com o tipo, a\ncarga e a capacidade de persistência viral,\nmas independe do estado imunológico do hospedeiro."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-215442","number":"215442","sourceNumber":"215442","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Apresentação subclínica é a lesão subclínica, ocorre quando as microlesões pelo HPV\nsão diagnosticadas por meio de exame de\nPapanicolaou e/ou colposcopia (lesões acetobrancas),\ncom ou sem biópsia. Não faz parte dos conceitos o item:","options":{"A":"A lesão intraepitelial escamosa de baixo ou alto risco é detectada com mais raramente.","B":"Os tipos oncogênicos de HPV podem resultar em lesões precursoras do carcinoma escamoso da\ncérvice uterina.","C":"A lesão intraepitelial escamosa de baixo grau.","D":"Lesão intraepitelial escamosa de alto grau."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-187691","number":"187691","sourceNumber":"187691","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A avaliação da citologia cérvico-vaginal representa um exame importante na prevenção\ndo carcinoma do colo uterino, sendo que este exame\né considerado satisfatório quando são\nevidenciadas células:","options":{"A":"Escamosas e endocervicais ou metaplásicas.","B":"Endometriais.","C":"Da mucosa vaginal.","D":"Da flora bacteriana vaginal."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-185125","number":"185125","sourceNumber":"185125","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer da vulva é responsável por 3% a 5% das neoplasias malignas do trato genital\nfeminino e representa 1% a 4% de todos os tumores malignos da mulher. Sobre essa diferença,\nverifica-se o seguinte:","options":{"A":"o adenocarcinoma é reponsável por 85% dos casos.","B":"o sintoma mais frequente é prurido.","C":"o diagnóstico é geralmente realizado de forma precoce.","D":"a radioterapia não está indicada no tratamento dessa doença."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-187550","number":"187550","sourceNumber":"187550","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente com 78 anos, menopausa há 30 anos, apresentou sangramento vaginal\nmoderado. Ao exame de ultrassom transvaginal foi visualizado eco endometrial de 25mm. O\ndiagnóstico provável e a conduta indicada para o caso clínico é","options":{"A":"patologia benigna uterina e prescrição de acetato de noretisterona 10 mg por 3 meses.","B":"atrofia endometrial e prescrição de estadiol 1 mg + acetato de noretisterona 0,5mg por 3 meses.","C":"hiperplasia do endométrio sem atípica celular e realização de histerectomia.","D":"adenocarcinoma de endométrio e realização de histeroscopia diagnóstica com biópsia ou\ncuretagem semiótica com biópsia do material."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-187561","number":"187561","sourceNumber":"187561","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher, 48 anos, casada, G4P4A0, sexarca aos 13 anos, queixa-se de leucorréia e\nsinusiorragia, relata sete parceiros sexuais e história pregressa de sífilis e tabagismo. Apresenta\nlesão cervical uterina exofítica, teste de Schiller positivo e Neoplasia Intraepitelial Cervical\ngrau III\n(NIC III) como resultado de exame de citologia oncótica e biópsia de colo uterino. No retorno à\nconsulta para apresentar seus exames, a paciente alega que seu esposo possui lesão peniana e\nque se recusa a ir ao médico. Nessa situação, a conduta médica adequada é a indicação de","options":{"A":"cauterização de colo uterino e comparecimento do marido na próxima consulta médica.","B":"cauterização de colo uterino e encaminhamento do marido ao urologista.","C":"conização do colo uterino e comparecimento do marido na próxima consulta médica.","D":"histerectomia total e encaminhamento que o marido ao urologista."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-173514","number":"173514","sourceNumber":"173514","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Do ponto de vista do câncer de colo uterino e suas lesões precursoras, considera-se o\nseguinte:","options":{"A":"o exame colpocitológico de rastreio, realizado a cada três anos, aumentou o risco de câncer de\ncolo uterino em 80% quando comparado com exames anuais.","B":"o HPV apresenta diversos tipos e, por isso, a vacina quadrivalente é eficaz e indicada a\npacientes jovens que tenham relacionamento sexual restrito a um parceiro.","C":"a colposcopia e a conização são indicadas em casos de citologia negativa, mas com alterações\nsugestivas de HPV.","D":"a infecção persistente por HPV de alto risco é uma condição necessária para o desenvolvimento\ndo câncer de colo uterino."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-178781","number":"178781","sourceNumber":"178781","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente, 37 anos, chega ao consultório para coleta de preventivo, pois faz controle\nanual sem anormalidades desde os 18 anos e se\nsente segura e feliz por cuidar bem de sua saúde.\nAssintomática, G2PN2A0, histerectomizada (total) há 1 ano devido a leiomioma uterino e\nmenorragia refratária a tratamento clínico. Sexualmente ativa, parceiro fixo. No que diz respeito à\ncoleta de colpocitologia da paciente, assinale a alternativa correta.","options":{"A":"A coleta deveria ter sido realizada 6 meses após a cirurgia.","B":"Pacientes que realizaram histerectomia subtotal por doença benigna não necessitam de nova\ncoleta, independentemente de exames anteriores.","C":"Paciente histerectomizada (total) por doença benigna que apresentam exames anteriores sem\nanormalidades não necessitam de nova coleta","D":"Caso a histerectomia fosse subtotal a nova coleta deveria ser feita em 6 meses.","E":"A coleta deverá ser realizada a cada 3 anos, de acordo com as Diretrizes Brasileiras para\nrastreamento de câncer de útero."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-173527","number":"173527","sourceNumber":"173527","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"São fatores de risco para o câncer de endométrio:","options":{"A":"anticoncepcional com DIU contendo levonogestrel e multiparidade.","B":"análogos de GnRH e prolactina.","C":"acetato de medroxiprogesterona e nuliparidade.","D":"TH com estrogênio sem progestagênio em paciente com útero e nuliparidade."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-178785","number":"178785","sourceNumber":"178785","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente, 35 anos, foi diagnosticada com câncer de útero há 3 meses. Realizou\ntomografia computadorizada de abdome que evidenciou hidronefrose sem nenhuma outra\nassociação, exceto o tumor. De acordo com o estadiamento clínico do câncer de colo de útero\n(segundo o sistema FIGO), a classificação dessa paciente é:","options":{"A":"IIIB","B":"IV","C":"IVA","D":"IIIA"},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-183285","number":"183285","sourceNumber":"183285","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Os vasos de Sampsom percorrem as seguintes estruturas:","options":{"A":"ligamentos infundíbulo-pélvicos","B":"ligamentos útero-sacros","C":"ligamentos redondos","D":"ligamentos cardinais"},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-183307","number":"183307","sourceNumber":"183307","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 60 anos com queixa de prurido em região vulvar, nega uso de qualquer\nmedicação, inclusive Terapia de Reposição Hormonal. Ao exame físico, é evidenciada área de\nhipocromia em fúrcula vaginal. A melhor opção nesse caso é:","options":{"A":"Tratar como líquen esclero-atrófico.","B":"Biopsiar a área hipocrômica.","C":"Exérese de toda a lesão.","D":"Realizar teste terapêutico com corticóide local."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-160488","number":"160488","sourceNumber":"160488","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A incidência de câncer de colo uterino continua elevada e crescente no Brasil, segundo\no INCA (Instituto Nacional do Câncer). Quanto\nà prevenção e rastreamento desse tipo de câncer,\nsão medidas eficazes:","options":{"A":"Vacinação contra HPV e USG endovaginal anual.","B":"coleta de citologia cervical e cultura da secreção vaginal.","C":"Exame clínico do colo uterino e coleta da citologia cervical.","D":"Vacinação contra HPV e coleta da citologia cervical."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-158456","number":"158456","sourceNumber":"158456","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O tratamento do líquen escleroso da vulva tem o objetivo de prevenir:","options":{"A":"Tricomoníase e candidíase recorrente.","B":"Alterações anatômicas e transformação maligna.","C":"Transformação maligna e tricomoníase.","D":"Vaginose bacteriana e alterações anatômicas."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-156972","number":"156972","sourceNumber":"156972","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Com relação ao tratamento cirúrgico do câncer de colo de útero, é INCORRETO afirmar\nque:","options":{"A":"A histerectomia radical modificada (tipo II) difere da histerectomia (tipo III) por ter o\nligamento\ncardinal seccionado em sua porção medial.","B":"A fístula ureterovaginal é uma das complicações da histerectomia radical.","C":"A histerectomia radical videolaparoscópica nunca deve ser realizada no câncer de colo uterino.","D":"Para realizar a histerectomia radical, deve-se fazer a dissecação dos espaços paravesical e\npararretal."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-150237","number":"150237","sourceNumber":"150237","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 55 anos queixa-se de prurido vulvar intenso há vários anos que, por vezes,\ninterfere no sono. Ao exame, apresenta lesão brancacenta bem delimitada, envolvendo vulva e\nânus, em forma de ?8?. Ao exame especular, a mucosa vaginal está íntegra. Neste caso:","options":{"A":"A hipótese mais provável é líquen plano.","B":"A biópsia é obrigatória para confirmar o diagnóstico.","C":"O tratamento de escolha é o corticoide tópico de alta potência.","D":"A alta ambulatorial é programada após a remissão dos sintomas."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-157271","number":"157271","sourceNumber":"157271","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"De acordo com o Ministério da Saúde, sobre o rastreamento do câncer de colo do\nútero, assinale a alternativa CORRETA.","options":{"A":"Células metaplásicas presentes em amostra de colpocitologia a definem como inadequada.","B":"O início da coleta deve ser aos 25 anos para mulheres que já tiveram início da atividade sexual.","C":"Não deve ser realizada a coleta da colpocitologia durante a gestação.","D":"Lesão intraepitelial escamosa de baixo grau (LSIL) compreende NIC II/III.","E":"Mulheres com mais de 64 anos devem ter a coleta interrompida, independentemente de\nresultados anteriores recentes."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-150221","number":"150221","sourceNumber":"150221","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Segundo as diretrizes brasileiras, o rastreamento citológico do câncer do colo do útero:","options":{"A":"Deve ser realizado com intervalo trienal após dois consecutivos negativos.","B":"Deve ocorrer após dois anos do início da atividade sexual.","C":"Deve ocorrer em mulheres sem história de atividade sexual após os 25 anos.","D":"Deve ser realizado até os 75 anos de idade."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-150240","number":"150240","sourceNumber":"150240","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A realização da colpocitologia oncológica durante o pré-natal:","options":{"A":"Está contraindicada em função dos riscos maternos e fetais.","B":"Está limitada ao terceiro trimestre da gravidez.","C":"Está indicada no primeiro trimestre, em caso de necessidade.","D":"Deve ser evitada, tendo em vista a sua baixa sensibilidade."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-157289","number":"157289","sourceNumber":"157289","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"T.G.S, 31 anos, chega ao consultório preocupada com resultado de colpocitologia\noncótica realizada há 1 mês com resultado ASC-US;\nexames anteriores sem anormalidades. Qual\ndeve ser a conduta adotada?","options":{"A":"Repetir exame colpocitológico em 6 meses e, se o achado se repetir, indicar colposcopia.","B":"Repetir exame colpocitológico em 6 meses e, se o achado se repetir, indicar conização.","C":"Repetir exame colpocitológico em 12 meses e, se o achado se repetir, indicar colposcopia.","D":"Repetir exame colpocitológico em 6 meses e, se o achado se repetir, indicar tratamento clínico\ncom ácido tricloroacético.","E":"Repetir exame colpocitológico em 12 meses e, se o achado se repetir, indicar conização."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-149183","number":"149183","sourceNumber":"149183","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 39 anos comparece para exame ginecológico de rotina, relatando\nantecedente de \"verrugas no colo uterino\",\ntratadas há 2 anos. Ao exame ginecológico: ausência de\ndistopias, vulva normal, colo uterino com pequena mácula rubra em lábio anterior. Colhido material\npara citologia oncótica e realizado teste de Schiller, que resultou positivo. A colposcopia revelou\nepitélio aceto-branco, pontilhado e mosaico das 10 às 2 h. Ao toque vaginal: útero e anexos\nnormais. Após uma semana é recebida a citologia oncótica cervical: compatível com lesão de alto\ngrau, Neoplasia Intracervical (NIC) II, associado ao HPV. Para conduzir esse caso:","options":{"A":"É indispensável solicitar exames de biologia molecular e identificar o sorotipo viral para\ndefinir o\ntratamento.","B":"Deve-se instituir imediatamente o tratamento destrutivo ou ablativo da lesão cervical.","C":"Deve-se instituir o tratamento para o HPV e aguardar a regressão da lesão cervical.","D":"Deve-se estabelecer correlação entre a citologia e a biópsia dirigida pela colposcopia para\nexcluir o carcinoma invasor."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-157375","number":"157375","sourceNumber":"157375","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 42 anos, obesa, com queixa de aumento do fluxo menstrual nos últimos 12\nmeses. Submetida à biópsia endometrial, o laudo anatomopatológico evidenciou hiperplasia\nendometrial atípica. Diante de tal caso, aponte a alternativa que apresenta a MELHOR conduta:","options":{"A":"Anticoncepcional combinado oral contínuo para suprimir o sangramento.","B":"Histerectomia total.","C":"Anticoncepção com progesterona injetável de depósito para atrofiar o endométrio.","D":"Curetagem uterina vigorosa para retirada de toda a área de atipia."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-150852","number":"150852","sourceNumber":"150852","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Os carcinomas do endométrio são neoplasias malignas considerados:","options":{"A":"O segundo tipo de neoplasias invasoras mais comum encontrado no trato genital feminino.","B":"Tumores do tipo I ? de baixo grau e geralmente indolentes ? e os do tipo II ? agressivos e de\nalto\ngrau, com prognóstico desfavorável.","C":"Tumores precedidos de hiperplasia atípica que apresentam mutações no gene TP53, e que\npodem, ainda, ser identificados nas lesões precursoras.","D":"Os carcinomas do tipo II, associados ao carcinoma intraepitelial endometrióide seroso e suas\nmutações\n\nmais encontradas são: a PTEN, a PIK3CA, a KRAS e a ARID1A."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-149253","number":"149253","sourceNumber":"149253","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 26 anos, G2P2A0C0, nega uso de métodos contraceptivos, vida sexual\nativa, refere lesões verrucosas em vulva e\nvagina há 3 meses. Refere ter tido 6 parceiros sexuais.\nFez exame de Papanicolaou há 4 meses que veio resultado de lesão de baixo grau e HPV. Qual é\no exame MAIS indicado para esse caso?","options":{"A":"Conização.","B":"Histerectomia total abdominal.","C":"Pesquisa de DNA viral (captura híbrida).","D":"Colher exame de Papanicolaou anual."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-149263","number":"149263","sourceNumber":"149263","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 25 anos, G2P2A0C2 + Laqueadura tubárea, vida sexual ativa, vem para\nconsulta com exame de Papanicolaou realizado há 6 meses com diagnóstico de ?Ca in situ?. Qual\né a conduta mais adequada para esse caso?","options":{"A":"Conização.","B":"Histerectomia total abdominal.","C":"Colposcopia e biópsia dirigida.","D":"Cirurgia de Wethein Meigs."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-141550","number":"141550","sourceNumber":"141550","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"São HPV relacionados ao câncer de colo:","options":{"A":"16, 18.","B":"26, 28.","C":"36, 38.","D":"46, 48."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-136874","number":"136874","sourceNumber":"136874","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A colposcopia como um exame para detecção de microcarcinoma de colo uterino, como\na desenvolvida por Hinselmann, vem sofrendo\nmuitas mudanças ao longo do tempo. A colposcopia\nestá indicada nas seguintes alterações:","options":{"A":"1 exame isolado apresentando ASC-US e 1 exame isolado apresentando LIEBG.","B":"1 exame isolado apresentando ASC-H e 1 exame isolado apresentando LIEBG.","C":"2 exames apresentando LIEBG e 1 exame isolado apresentando ASC-H.","D":"1 exame isolado apresentando LIEBG e 1 exame isolado apresentando LIEAG."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-137019","number":"137019","sourceNumber":"137019","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O câncer do colo uterino é, em nosso país, o tumor maligno mais frequente no sistema\ngenital feminino, diferentemente do que ocorre em países desenvolvidos, onde prevalece o câncer\nde endométrio. Em relação ao câncer de colo uterino, verifica-se que:","options":{"A":"O estadiamento do câncer do colo uterino é cirúrgico.","B":"Na avaliação histológica interessam o tamanho, o tipo de tumor, seu grau de diferenciação e a\npresença ou ausência de invasão do espaço linfovascular.","C":"A sua prevalência não pode ser reduzida através da realização de diagnóstico oportuno e\ntratamento correto de suas lesões\nprecursoras, que são as neoplasias intraepiteliais, especialmente\nas de alto grau.","D":"A apresentação clínica do câncer do colo do útero pode ser de dois tipos: tumor exofítico e\nulcerativo."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-136545","number":"136545","sourceNumber":"136545","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 25 anos, vida sexual ativa, vários parceiros, refere uso de preservativo com\ntodos, comparece à UBS com exame de preventivo cujo resultado mostrou ?carcinoma in situ?.\n\nFrente a esse caso, indique a MELHOR conduta?","options":{"A":"Histerectomia total abdominal.","B":"Colposcopia e biópsia.","C":"Conização.","D":"Histerectomia total vaginal."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-127595","number":"127595","sourceNumber":"127595","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 35 anos foi encaminhada para colposcopia por ter apresentado lesão de\nalto grau em seu exame citológico. A\ncolposcopia identificou zona de transformação indicativa de\nalterações maiores, adentrando o canal, com junção escamocolunar não visível. O exame\nhistológico do material obtido por biópsia dirigida, na periferia da lesão, mostrou NIC 1. Neste\ncaso,\na conduta adequada é:","options":{"A":"Detecção e genotipagem do HPV.","B":"Conização por cirurgia de alta frequência.","C":"Acompanhamento citológico.","D":"Vacinação contra o HPV."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-127612","number":"127612","sourceNumber":"127612","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 45 anos queixa-se de leucorreia fétida e sangramento genital após o coito,\niniciado há aproximadamente seis meses. O exame especular mostrou colo com lesão exofítica,\ncom aproximadamente 3 cm, friável, sangrante, com secreção purulenta e necrótica. A conduta\nadequada é:","options":{"A":"Coletar esfregaço citológico.","B":"Encaminhar para exame colposcópico.","C":"Realizar biópsia para estudo histológico.","D":"Solicitar ultrassonografia transvaginal."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-127324","number":"127324","sourceNumber":"127324","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 46 anos, G3P3A0C0, fez exame de Papanicolaou, cujo resultado foi NIC I.\nDiante de tal resultado, qual é a MELHOR conduta?","options":{"A":"Controle anual com Papanicolaou.","B":"Fazer conização.","C":"Repetir Papanicolau em 6 meses.","D":"Fazer colposcopia e biópsia."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-5-136960","number":"136960","sourceNumber":"136960","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Você é médico da equipe 12 na UBS Vila Matilde. Uma família que mudou\nrecentemente para a sua área adscrita vem à\nUnidade para uma primeira avaliação. O casal Denis\ne Lucimar e sua filha Maraisa de 17 anos, todos assintomáticos e com desejo de uma \"avaliação de\nrotina\" Maraísa, 17 anos, iniciou vida sexual aos 14 anos, com parceiro fixo, pergunta sobre a\nnecessidade de realizar o \"exame preventivo\" para câncer de colo uterino. Nesse caso qual deve\nser a sua orientação?","options":{"A":"Exame ginecológico regular, porém a coleta de material para exame citológico deverá ser feita\npreferencialmente após ela completar 18 anos (04 anos após início da vida sexual).","B":"Exame ginecológico regular, porém a coleta de material para exame citológico deverá ser feita\npreferencialmente após ela completar 25 anos.","C":"Coleta de material para exame citológico no momento da consulta, se a paciente concordar e\nnão tiver sangramentos no momento ou relação\nsexual no dia anterior.","D":"Exame ginecológico regular, porém coleta de material para exame citológico deverá ser feita\npreferencialmente após ela completar 19 anos (05 anos após início da vida sexual)."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-127331","number":"127331","sourceNumber":"127331","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Menopausada sem TRH apresenta espessamento endometrial ao ultrassom. Deve-se:","options":{"A":"Realizar teste com estrógenos.","B":"Realizar histerectomia.","C":"Realizar vídeolaparoscopia.","D":"Realizar curetagem de prova."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-127333","number":"127333","sourceNumber":"127333","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Qual, entre as alternativas abaixo, melhor caracteriza a sequência (ordem) de\nmaturação fisiológica celular das mucosas vaginal e ectocervical do epitélio escamoso?","options":{"A":"Células basais, intermediárias, superficiais, parabasais.","B":"Células intermediárias, barabasais, basais, superficiais.","C":"Células superficiais, basais, parabasais, intermediárias.","D":"Células basais, barabasais, intermediárias, superficiais."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-127641","number":"127641","sourceNumber":"127641","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente do sexo feminino, de 60 anos, realiza uma citologia de rastreamento em que\nse observam blocos celulares atípicos, com\nhipercromatismo nuclear, bordos nucleares irregulares\ne nucléolos ausentes. A colposcopia demonstra exocérvice sem alterações e Junção\nEscamocolunar (JEC) não visível. Faz-se a revisão da citologia e as alterações citológicas são\nconfirmadas, e a captura de híbridos demonstra positividade para HPV de alto risco. A curetagem\ndo canal está representada abaixo: (VER IMAGEM) A análise da representação da curetagem do\ncanal indica que a lesão não foi observada pelo colposcopista porque se trata de:","options":{"A":"Um adenocarcinoma de endométrio.","B":"Um adenocarcinoma de tipo endocervical.","C":"Uma lesão de alto grau (displasia acentuada/carcinoma escamoso in situ), dentro do canal\nendocervical.","D":"Uma lesão de baixo grau (HPV/displasia leve), dentro do canal endocervical."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":["question_bank/media/medcurso/medcurso-gineco-gin-5/127641.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-127662","number":"127662","sourceNumber":"127662","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente do sexo feminino, de 59 anos, com sangramento discreto, em água de carne,\nfaz uma citologia vaginal de rastreamento e\nos esfregaços evidenciam raros blocos celulares\npequenos, tridimensionais, circundados por diátese aquosa e nucléolos evidentes (figura 1). A\ncuretagem do corpo e canal demonstra as alterações observadas na figura 2. A imuno-histoquímica\ndemonstra positividade difusa para o PTEN e para o receptor de estrógeno. O diagnóstico dessa\npaciente é:","options":{"A":"Adenocarcinoma endometrioide do endométrio.","B":"Adenocarcinoma invasor do colo uterino.","C":"Carcinoma escamoso invasor do colo uterino.","D":"Hiperplasia simples atípica do endométrio."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":["question_bank/media/medcurso/medcurso-gineco-gin-5/127662.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-129914","number":"129914","sourceNumber":"129914","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente do sexo feminino, de 25 anos, sexualmente ativa, apresenta citologia descrita\ncomo células profundas atípicas com\ncariomegalia, hipercromatismo e irregularidades nucleares. A\nbiópsia está representada na figura a seguir. (VER IMAGEM) O diagnóstico da paciente é:","options":{"A":"Lesão intraepitelial de alto grau (citologia), displasia acentuada/carcinoma in situ (biópsia) e\na\npróxima conduta para essa paciente é a histerectomia simples.","B":"Adenocarcinoma in situ e a próxima conduta médica será a conização clássica para afastar a\npresença de lesão microinvasora ou invasora.","C":"Lesão de baixo grau e a conduta é o seguimento clínico-citológico, pois a paciente é muito\njovem.","D":"Lesão intraepitelial de alto grau (citologia), displasia acentuada/carcinoma in situ (biópsia) e\na\npróxima conduta é a CAF (cirurgia de alta frequência), para confirmação diagnóstica e estudo das\nmargens cirúrgicas."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":["question_bank/media/medcurso/medcurso-gineco-gin-5/129914.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-127280","number":"127280","sourceNumber":"127280","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 35 anos, garota de programa, G0P0, pós-operatório de câncer de colo do\nútero invasivo há 6 meses, sendo realizada cirurgia de Wertheim-Meigs, com necessidade de\nradioterapia e quimioterapia. Quanto ao caso clínico acima descrito, podemos concluir que a\npaciente:","options":{"A":"Deve fazer exame de citologia de cúpula vaginal de controle.","B":"Não precisa fazer exame nenhum de controle.","C":"Deve realizar US endovaginal a cada 6 meses.","D":"Deve realizar radioterapia a cada 6 meses."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-106698","number":"106698","sourceNumber":"106698","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente, 50 anos de idade, com laudo citopatológico revelando lesão intraepitelial\nescamosa de alto grau, é submetida a biópsia de\ncolo uterino que acusa NIC III. A conduta a ser\nseguida é:","options":{"A":"eletrocauterização.","B":"histerectomia total.","C":"conização.","D":"aplicação de ácido tricloroacético."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-109184","number":"109184","sourceNumber":"109184","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Qual dos seguintes cânceres de vulva ocorre mais comumente?","options":{"A":"Melanoma.","B":"Adenocarcinoma.","C":"Tumor de Paget.","D":"Tumor epidermoide."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-109351","number":"109351","sourceNumber":"109351","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Em relação ao câncer do colo de útero, estudos apontam que 270 mil mulheres morrem\ndevido à doença, no mundo. Neste ano, o Instituto Nacional do Câncer estima o surgimento de 15\nmil novos casos. Para a prevenção, o Ministério da Saúde recomenda:","options":{"A":"a vacina quadrivalente com 98% da eficácia contra o HPV, implementada no ano de 2014 para\nmeninas de 9 a 15 anos.","B":"a vacina do HPV em quatro doses, sendo a segunda seis meses depois da primeira, e a terceira\ne a quarta, respectivamente, um ano e dois\nanos após a 1ª dose.","C":"a vacina do HPV em susbstituição ao exame preventivo, o Papanicolau, desde que as mulheres,\nna faixa etária dos 15 aos 60 anos, tenham\nsido devidamente vacinadas na adolescência.","D":"a vacina do HPV e o uso de preservativos nas relações sexuais, porque o HPV é transmitido\npelo contato direto com pele ou mucosas infectadas."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-109312","number":"109312","sourceNumber":"109312","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 32 anos, GIII, PIII, A0, três cesarianas, laqueada há cinco anos, chega\ntrazendo resultado de colpocitologia que mostra\nlesão intraepitelial de alto grau, não podendo\nexcluir microinvasão ou carcinoma epiodermoide invasor e, ainda, resultado de uma colposcopia\nque se mostrou insatisfatória porque não visualizou a junção escamocolunar. Diante desse quadro,\na conduta é:","options":{"A":"histerectomia total.","B":"histerectomia ampliada.","C":"conização.","D":"curetagem do canal."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-111400","number":"111400","sourceNumber":"111400","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Eudirene, 28 anos, nulípara, comparece em consulta médica trazendo laudo de biópsia\ndirigida por colposcopia compatível com carcinoma in situ de colo uterino. A proposta terapêutica\né:","options":{"A":"Eletrocauterização do colo uterino.","B":"Conização.","C":"Histerectomia subtotal abdominal.","D":"Histerectomia total abdominal.","E":"Cirurgia de Werthein-Meigs."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-101160","number":"101160","sourceNumber":"101160","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente do sexo feminino, de 25 anos, retorna ao médico do PSF com diagnóstico no\ncitopatológico de LIEAG (Lesão Intraepitelial de Alto Grau). Na condução deste caso,","options":{"A":"a repetição da citologia após seis meses é aceitável como conduta inicial.","B":"a realização de nova citologia após três meses, a contar da data da coleta da citologia anterior,\nse a colposcopia não evidenciar lesão, para\navaliar o canal endocervical.","C":"a recomendação de exérese imediata da lesão, se a paciente estiver gestante de doze semanas\ne o diagnóstico histopatológico evidenciar\nNIC II ou III.","D":"a realização de nova citologia após três meses, se a paciente em questão estiver infectada pelo\nHIV."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-109374","number":"109374","sourceNumber":"109374","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A infecção pelo HPV é altamente prevalente e alguns sorotipos estão associados ao\ncâncer do colo uterino. As vacinas contra\nos sorotipos de HPV 16 e 18 (bivalente) e 6, 11, 16, 18\n(quadrivalente), disponíveis no mercado, têm sido consideradas uma arma a mais contra a infecção\npelo vírus. É uma condição que contraindica o uso dessas vacinas:","options":{"A":"Mulheres no climatério.","B":"Mulheres que não iniciaram a atividade sexual.","C":"Mulheres com infecção atual do HPV.","D":"Mulheres grávidas."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-101226","number":"101226","sourceNumber":"101226","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Para paciente de 60 anos, que apresenta prurido vulvar crônico e lesão esbranquiçada\nna região clitoridiana, a conduta correta é:","options":{"A":"anti-histamínico.","B":"retirada total da lesão.","C":"corticoide.","D":"biópsia da lesão."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-101231","number":"101231","sourceNumber":"101231","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Pacientes obesas com ciclos anovulatórios possuem maior risco de câncer de\nendométrio devido à hiperplasia endometrial por\nestímulo permanente de estrogênio, sem oposição\nprogesterônica. Que enzima é responsável pela conversão de andrógenos em estrógenos?","options":{"A":"Aromatase.","B":"17 betadesidrogenase.","C":"5 alfarredutase.","D":"20 e 22 desmolase."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-101178","number":"101178","sourceNumber":"101178","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 57 anos foi ao seu ginecologista queixando-se de ter notado área pálida e\npruriginosa em um dos lábios vulvares. O exame ginecológico mostrou uma área plana e branca de\n0,9 cm no lábio direito. Foi realizada biópsia incisional, fixada em formol a 10%. O histopatológico\nrevelou a presença de células discarióticas que comprometem os dois terços basais do epitélio\nescamoso, bem como a presença de mitoses. A hibridização in situ aponta o DNA do papilomavírus\nhumano tipo 16 nas células epiteliais. O diagnóstico para essa paciente é:","options":{"A":"condiloma plano.","B":"verruga plana.","C":"neoplasia intraepitelial vulvar.","D":"líquen escleroso e atrófico."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-101186","number":"101186","sourceNumber":"101186","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 46 anos tem apresentado sangramento pós-coito há um ano. Sua menarca\nfoi aos 11 anos e teve 12 parceiros sexuais\ndurante toda a vida. Atualmente, continua tendo ciclos\nmenstruais regulares, sem sangramento intermenstrual anormal. No exame ginecológico foi\nevidenciada, por visão direta, uma área extensa, elevada e eritematosa que compromete o lábio\nposterior e invade o canal endocervical. O exame citopatológico revelou neoplasia escamosa\nintraepitelial de alto grau/carcinoma in situ, não podendo afastar microinvasão. Intempestivamente,\nfoi realizada conização convencional. Considerando o quadro clinicoepidemiológico, o diagnóstico\nhistopatológico esperado é:","options":{"A":"lesão intraepitelial de alto grau/carcinoma in situ.","B":"carcinoma escamoso microinvasor.","C":"carcinoma escamoso francamente invasor.","D":"carcinoma escamoso francamente invasor não ceratinizante."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-109377","number":"109377","sourceNumber":"109377","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma mulher de 62 anos, sem filhos, notou corrimento vaginal tingido de sangue, duas\nvezes no último mês. Seu último ciclo\nmenstrual foi há 14 anos. O exame ginecológico revelou que\nseu útero tem tamanho normal, sem massa palpável em anexos. Não há erosões ou massas\ncervicais. O seu índice de massa corporal é de 33. Os antecedentes pessoais mostram que tem\nhipertensão arterial há 30 anos e diabetes melito do tipo 2. Foi realizada histeroscopia com\nbiópsia.\nQual diagnóstico histopatológico tem maior probabilidade de ser encontrado?","options":{"A":"Leiomiossarcoma.","B":"Adenocarcinoma de endométrio.","C":"Carcinoma escamoso de endométrio.","D":"Tumor mulheriano misto."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-103632","number":"103632","sourceNumber":"103632","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 17 anos, G0P0, com vida sexual ativa desde os 15 anos, sem método\ncontraceptivo desde então. Refere lesões\nverrucosas em vulva há 2 meses, que estão aumentando\nde tamanho. Qual é o diagnóstico MAIS provável?","options":{"A":"Herpes Genital.","B":"Foliculite.","C":"Condiloma Acuminado.","D":"Cisto de Bartholin."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-110259","number":"110259","sourceNumber":"110259","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Paciente de 32 anos, procurou ambulatório de ginecologia com queixa de saída de\nsecreção serosanguinolenta pela vagina e com odor\nfétido. Trouxe consigo uma biopsia de colo do\nútero que evidenciava carcinoma de colo. O exame físico evidenciou tumor comprometendo o terço\ninferior da vagina, sem extensão à parede pélvica e USG de vias urinárias sem comprometimento\nde vias urinárias. A paciente apresenta o seguinte estadiamento:","options":{"A":"IIa","B":"IIIb","C":"IIIa","D":"IIb"},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-86369","number":"86369","sourceNumber":"86369","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Na lesão de alto grau que se estende pelo interior do canal endocervical,\ntotalmente visível e com concordância citocolposcópica, deve-se realizar:","options":{"A":"Cauterização da lesão.","B":"Excisão ampla com alça diatérmica.","C":"Traquelectomia radical.","D":"Histerectomia."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-84685","number":"84685","sourceNumber":"84685","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A infecção genital pelo Papilomavírus Humano (HPV) é a infecção de transmissão\nsexual mais comum, considerada fator necessário\npara o desenvolvimento do câncer do colo\nuterino e por isso, importante problema de saúde pública. Com relação a esta infecção, pode-se\nafirmar que:","options":{"A":"Não é prevenida pelo uso do preservativo.","B":"É mais frequente na faixa de idade de 20 a 24 anos.","C":"Deve ser tratada ativamente em todas as suas formas de apresentação.","D":"É causa importante de infecção do recém-nascido, que a adquire no canal de parto infectado.","E":"Nenhuma das anteriores"},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-89988","number":"89988","sourceNumber":"89988","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Dentre os fatores abaixo citados, qual está relacionado à diminuição do câncer de\nendométrio?","options":{"A":"Diabetes mellitus.","B":"Hipertensão arterial.","C":"Obesidade.","D":"Terapia de Reposição Hormonal (TRH) com estrógeno.","E":"Uso prolongado de pílulas anticoncepcionais que contenham progestogênio."},"answer":"E","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-83877","number":"83877","sourceNumber":"83877","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O exame citológico pela técnica de Papanicolau é recomendado para todas as\nmulheres sexualmente ativas, independentemente da\nidade. Se exames anteriores são normais, há\npossibilidade de suspensão das coletas a partir de:","options":{"A":"35 anos.","B":"45 anos.","C":"55 anos.","D":"65 anos.","E":"75 anos."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-83802","number":"83802","sourceNumber":"83802","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Uma senhora de 60 anos procura sua ginecologista por perceber o aparecimento de\numa \"bola\" em seu pescoço. Ao exame físico,\nhá linfonodo em região cervical direita, de cerca de 3\ncm, fixo, indolor. Considerando-se que este linfonodo pode ser relacionado à neoplasia maligna,\nqual é o sítio primário desta possível neoplasia ginecológica?","options":{"A":"mama.","B":"colo de útero.","C":"ovário.","D":"anexos.","E":"endométrio."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-83845","number":"83845","sourceNumber":"83845","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"É fator de risco para carcinoma de endométrio, EXCETO:","options":{"A":"Baixo peso corporal.","B":"Diabetes mellitus.","C":"Menarca precoce.","D":"Menopausa tardia.","E":"Uso crônico de estrógeno."},"answer":"A","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-84384","number":"84384","sourceNumber":"84384","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Mulher de 25 anos de idade realizou o exame de citologia oncoparasitária do colo\nuterino na rede básica e o resultado mostrou lesão intraepitelial de baixo grau. Diante desse\nquadro, qual é a conduta correta?","options":{"A":"Repetir imediatamente a citologia.","B":"Repetir o exame citológico com 6 meses.","C":"Solicitar Captura Híbrida para HPV.","D":"Solicitar colposcopia.","E":"Realizar curetagem de canal cervical."},"answer":"B","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-78096","number":"78096","sourceNumber":"78096","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"Considerando-se as neoplasias mais frequentes do colo uterino, a que apresenta\ncomportamento benigno, e no seu manuseio clínico\npode ser tratada de forma conservadora, é a\nseguinte:","options":{"A":"carcinoma verrucoso.","B":"carcinoma escamoso microinvasor.","C":"adenocarcinoma microinvasor.","D":"carcinoma escamoso in situ."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-61282","number":"61282","sourceNumber":"61282","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"O carcinoma do endométrio é a neoplasia maligna mais comum do aparelho genital\nfeminino e representa quase metade de todos os cânceres ginecológicos nos EUA. Com base\nnessa afirmação, qual das alternativas está correta?","options":{"A":"acomete mais mulheres na pré-menopausa e sua virulência diminui com a idade.","B":"o papel do estrogênio em seu desenvolvimento não está claro.","C":"toda mulher que faz terapia hormonal deve usar somente estrogênio.","D":"acomete mais mulheres na pós-menopausa e nulíparas, e sua virulência aumenta com a idade.","E":"acomete mais mulheres na pré-menopausa e multíparas, e sua virulência aumenta com a idade."},"answer":"D","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-5-62785","number":"62785","sourceNumber":"62785","collectionBlock":"medcurso:medcurso-gineco-gin-5","collectionLabel":"Medcurso · GIN 5","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 5","subtopic":"","stem":"A associação do HPV com o câncer do colo já é bem estabelecida. Nessa relação:","options":{"A":"Os sorotipos do vírus 16, 18, 31, 33 e 45 são os mais relacionados às verrugas vulvares.","B":"As AGUS são lesões específicas do epitélio escamoso.","C":"O NIC III compreende os casos de displasia acentuada e de carcinoma in situ, que possuem o\nmesmo prognóstico.","D":"As ASC-US são consideradas lesões de alto grau."},"answer":"C","source":"Gineco/GIN 5/GIN 5.txt","sourceLabel":"Medcurso · GIN 5","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 5","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
